-- recipes_ka: CREATE TABLE + INSERTs
-- contributor_id=2 | source='khairulaming_tiktok'
-- Do NOT run without reviewing recipes_ka_review.csv first.

BEGIN;

CREATE TABLE IF NOT EXISTS recipes_ka (
    id                SERIAL PRIMARY KEY,
    video_id          VARCHAR(25)  NOT NULL,
    title             TEXT         NOT NULL,
    title_ms          TEXT,
    description       TEXT,
    description_ms    TEXT,
    cuisine           VARCHAR(100),
    difficulty        VARCHAR(20),
    prep_time         INTEGER,
    cook_time         INTEGER,
    servings          INTEGER,
    ingredients       JSONB,
    ingredients_detailed JSONB,
    steps             JSONB,
    steps_ms          JSONB,
    tags              JSONB,
    is_recipe         BOOLEAN      NOT NULL DEFAULT TRUE,
    needs_review      BOOLEAN      NOT NULL DEFAULT FALSE,
    review_notes      TEXT,
    contributor_id    INTEGER,
    image_url         TEXT,
    source            VARCHAR(100),
    created_at        TIMESTAMPTZ  DEFAULT NOW()
);

INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7476807227114835218', 'Fried Mackerel with Chilli Padi (Ikan Kembung Goreng Cili Padi)', 'Ikan Kembung Goreng Cili Padi', 'Crispy fried mackerel tossed with fried shallots, lemongrass, garlic and bird''s eye chilli in a quick savory sauce.', 'Ikan kembung yang digoreng garing dicampurkan dengan tumisan bawang merah, serai, bawang putih dan cili padi.', 'Malaysian', 'Easy', 10, 15, 2, '["Indian mackerel", "salt", "turmeric powder", "cooking oil", "shallot", "bird''s eye chilli", "garlic", "lemongrass", "oyster sauce", "fish sauce", "lime", "sugar"]', '[{"name": "Indian mackerel", "name_ms": "ikan kembung", "quantity": null, "unit": null, "note": "quantity not stated; scored"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": null, "unit": null, "note": "pinch for coating"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "chopped"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "to taste"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 1, "unit": "clove", "note": ""}, {"name": "lemongrass", "name_ms": "serai", "quantity": 1, "unit": null, "note": "sliced"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "fish sauce", "name_ms": "sos ikan", "quantity": null, "unit": null, "note": "a dash"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "squeezed over at end"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "to taste"}]', '["Score the mackerel deeply; coat with salt and a pinch of turmeric powder.", "Fry in hot oil until golden and crispy on both sides. Drain and set aside.", "In the same pan, sauté 1 shallot (chopped), some bird''s eye chilli, 1 garlic clove and 1 lemongrass stalk (sliced) until softened.", "Add 1 tbsp oyster sauce, a dash of fish sauce, salt and sugar to taste.", "Add the fried mackerel back; toss to coat. Squeeze over lime juice and serve."]', '["Kelar ikan kembung dalam-dalam; salit dengan garam dan sedikit serbuk kunyit.", "Goreng dalam minyak panas sehingga golden garing di kedua-dua belah. Toskan dan ketepikan.", "Dalam kuali yang sama, tumis 1 bawang merah (dicincang), cili padi, 1 ulas bawang putih dan 1 batang serai (dihiris) sehingga layu.", "Masukkan 1 sudu sos tiram, sedikit sos ikan, garam dan gula secukup rasa.", "Masukkan balik ikan goreng; gaul rata. Perah jus limau dan hidang."]', '["halal", "fish", "fried", "malaysian", "ramadan", "sahur"]', TRUE, TRUE, 'mackerel quantity not stated; sugar quantity to taste', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7476807227114835218', 'Minced Chicken Egg Roll (Telur Bungkus)', 'Telur Bungkus Isi Ayam', 'A thin egg omelette wrapped around a sticky-sweet minced chicken filling — a simple and popular Malaysian sahur dish.', 'Telur dadar nipis yang dibungkus dengan inti ayam cincang berkicap — hidangan sahur Malaysia yang mudah dan popular.', 'Malaysian', 'Easy', 10, 15, 2, '["chicken fillet", "shallot", "garlic", "oyster sauce", "sweet soy sauce", "black pepper", "water", "cornstarch", "egg", "salt", "cooking oil"]', '[{"name": "chicken fillet", "name_ms": "isi ayam", "quantity": null, "unit": null, "note": "minced; quantity not stated"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": ""}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": ""}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "black pepper", "name_ms": "black pepper", "quantity": 0.5, "unit": "tbsp", "note": "crushed"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a splash for filling"}, {"name": "cornstarch", "name_ms": "tepung jagung", "quantity": 1, "unit": "tsp", "note": "for slurry"}, {"name": "egg", "name_ms": "telur", "quantity": 3, "unit": null, "note": "for omelette wrapper"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "pinch for eggs"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for omelette"}]', '["Sauté 1 shallot and 3 garlic cloves; add minced chicken fillet.", "Season with 1 tbsp oyster sauce, 2 tbsp sweet soy sauce and 0.5 tbsp crushed black pepper.", "Add a splash of water and a cornstarch slurry (1 tsp cornstarch + water); stir until the filling is thick and glossy. Set aside.", "Beat 3 eggs with a pinch of salt; pour into a lightly oiled pan to form a large thin omelette — do not brown.", "Place the filling in the centre of the omelette; fold all four edges over to enclose.", "Serve seam-side down."]', '["Tumis 1 bawang merah dan 3 ulas bawang putih; masukkan isi ayam yang dicincang.", "Tambah 1 sudu sos tiram, 2 sudu kicap manis dan setengah sudu black pepper yang dihancurkan.", "Masukkan sedikit air dan bancuhan tepung jagung (1 sudu kecil tepung jagung + air); kacau sehingga inti pekat dan berkilat. Ketepikan.", "Pukul 3 biji telur dengan secubit garam; tuang ke dalam kuali berminyak untuk jadi telur dadar besar yang nipis — jangan biar perang.", "Letakkan inti di tengah telur dadar; lipat keempat-empat sisi ke dalam untuk bungkus.", "Hidang dengan bahagian lipatan ke bawah."]', '["halal", "chicken", "egg", "malaysian", "ramadan", "sahur"]', TRUE, TRUE, 'chicken fillet quantity not stated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7476807227114835218', 'Chicken in Sweet Soy Sauce (Ayam Masak Kicap)', 'Ayam Masak Kicap', 'Crispy fried chicken simmered in a sweet soy sauce glaze with aromatics — a classic Malaysian home-cooked dish.', 'Ayam yang digoreng garing kemudian direneh dalam sos kicap manis bersama rempah — hidangan rumah Malaysia yang klasik.', 'Malaysian', 'Easy', 15, 20, 3, '["chicken", "salt", "turmeric powder", "cooking oil", "shallot", "garlic", "lemongrass", "ginger", "sweet soy sauce", "oyster sauce", "bird''s eye chilli", "tomato", "spring onion"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated; any cut"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": null, "unit": null, "note": "for coating"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": ""}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": ""}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": ""}, {"name": "lemongrass", "name_ms": "serai", "quantity": 1, "unit": null, "note": ""}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob"}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": null, "unit": null, "note": "to taste"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "to taste"}, {"name": "tomato", "name_ms": "tomato", "quantity": 1, "unit": null, "note": "chopped"}, {"name": "spring onion", "name_ms": "daun bawang", "quantity": null, "unit": null, "note": "garnish"}]', '["Coat chicken pieces with salt and turmeric; fry in hot oil until golden and crispy. Set aside.", "Sauté 1 shallot, 3 garlic cloves, 1 lemongrass stalk and a knob of ginger until fragrant.", "Add sweet soy sauce to taste, 1 tbsp oyster sauce, bird''s eye chilli and 1 tomato (chopped).", "Return the fried chicken; toss to coat in the sauce. Simmer briefly.", "Garnish with spring onion and serve."]', '["Salit kepingan ayam dengan garam dan kunyit; goreng dalam minyak panas sehingga golden garing. Ketepikan.", "Tumis 1 bawang merah, 3 ulas bawang putih, 1 batang serai dan seketul halia sehingga wangi.", "Masukkan kicap manis secukup rasa, 1 sudu sos tiram, cili padi dan 1 biji tomato (dicincang).", "Masukkan balik ayam goreng; gaul dalam sos. Reneh sebentar.", "Hiaskan dengan daun bawang dan hidang."]', '["halal", "chicken", "soy sauce", "malaysian", "ramadan", "sahur"]', TRUE, TRUE, 'chicken quantity not stated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7476807227114835218', 'Butter Fried Rice (Nasi Goreng Butter)', 'Nasi Goreng Butter', 'Simple and quick butter fried rice with prawn, egg and garlic — flavoured with a packet of instant fried rice seasoning.', 'Nasi goreng butter yang mudah dan cepat dengan udang, telur dan bawang putih — dibumbui dengan satu paket perencah nasi goreng.', 'Malaysian', 'Easy', 5, 10, 2, '["butter", "egg", "prawn", "garlic", "cooked white rice", "instant fried rice seasoning", "bird''s eye chilli", "spring onion"]', '[{"name": "butter", "name_ms": "butter", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "egg", "name_ms": "telur", "quantity": 1, "unit": null, "note": ""}, {"name": "prawn", "name_ms": "udang", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": "minced"}, {"name": "cooked white rice", "name_ms": "nasi putih", "quantity": null, "unit": null, "note": "day-old rice preferred; quantity not stated"}, {"name": "instant fried rice seasoning", "name_ms": "perencah nasi goreng", "quantity": 1, "unit": null, "note": "1 packet"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "to taste"}, {"name": "spring onion", "name_ms": "daun bawang", "quantity": null, "unit": null, "note": "garnish"}]', '["Melt 2 tbsp butter in a hot wok.", "Add 1 egg (broken) and prawn; stir until egg is just set and prawn turns pink.", "Add 3 minced garlic cloves; sauté briefly.", "Add leftover cooked rice; break up any clumps and toss well.", "Season with 1 packet instant fried rice seasoning; toss to combine.", "Add bird''s eye chilli and spring onion; serve."]', '["Cairkan 2 sudu besar butter dalam kuali panas.", "Masukkan 1 biji telur (pecahkan) dan udang; kacau sehingga telur baru masak dan udang bertukar merah jambu.", "Masukkan 3 ulas bawang putih yang dihacam; tumis sebentar.", "Masukkan nasi masak sejuk; hancurkan ketulan dan gaul rata.", "Tambah 1 paket perencah nasi goreng; gaul sebati.", "Masukkan cili padi dan daun bawang; hidang."]', '["halal", "fried rice", "butter", "prawn", "malaysian", "ramadan", "sahur"]', TRUE, TRUE, 'prawn quantity not stated; cooked rice quantity not stated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7476807227114835218', 'Chicken Paprik (Ayam Paprik)', 'Ayam Paprik', 'Thai-influenced stir-fried chicken with lemongrass, blended chilli, oyster sauce and kaffir lime leaf — aromatic and slightly spicy.', 'Ayam paprik gaya Thai yang ditumis bersama serai, cili kisar, sos tiram dan daun limau purut — wangi dan sedikit pedas.', 'Fusion', 'Easy', 10, 15, 3, '["chicken", "cooking oil", "onion", "garlic", "lemongrass", "blended chilli", "oyster sauce", "tomato sauce", "chilli sauce", "fish sauce", "kaffir lime leaf", "bird''s eye chilli"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": ""}, {"name": "onion", "name_ms": "bawang holland", "quantity": 0.5, "unit": null, "note": "half a Holland onion"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": ""}, {"name": "lemongrass", "name_ms": "serai", "quantity": 1, "unit": null, "note": ""}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "tomato sauce", "name_ms": "sos tomato", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "fish sauce", "name_ms": "sos ikan", "quantity": null, "unit": null, "note": "a dash"}, {"name": "kaffir lime leaf", "name_ms": "daun limau purut", "quantity": null, "unit": null, "note": "2-3 leaves"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "to taste"}]', '["Sauté 0.5 onion (bawang Holland), 3 garlic cloves and 1 lemongrass stalk in hot oil.", "Add 1 tbsp blended chilli; fry until fragrant.", "Add chicken pieces; stir-fry until sealed.", "Add 1 tbsp oyster sauce, 1 tbsp tomato sauce, 1 tbsp chilli sauce and a dash of fish sauce.", "Add 2–3 kaffir lime leaves and bird''s eye chilli; toss and cook until the chicken is done.", "Serve with rice."]', '["Tumis setengah biji bawang Holland, 3 ulas bawang putih dan 1 batang serai dalam minyak panas.", "Masukkan 1 sudu cili kisar; goreng sehingga wangi.", "Masukkan kepingan ayam; tumis sehingga bertukar warna.", "Masukkan 1 sudu sos tiram, 1 sudu sos tomato, 1 sudu sos cili dan sedikit sos ikan.", "Masukkan 2-3 helai daun limau purut dan cili padi; gaul dan masak sehingga ayam masak.", "Hidang bersama nasi."]', '["halal", "chicken", "stir-fry", "thai", "fusion", "malaysian", "ramadan", "sahur"]', TRUE, TRUE, 'chicken quantity not stated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7476807227114835218', 'Sardine Omelette (Telur Dadar Sardin)', 'Telur Dadar Sardin', 'A simple sardine filling spooned over a plain fried egg omelette — finished with sweet soy sauce and bird''s eye chilli.', 'Inti sardin yang dimasak dihidang di atas telur dadar goreng — diselesaikan dengan kicap manis dan cili padi.', 'Malaysian', 'Easy', 5, 10, 2, '["canned sardine", "shallot", "garlic", "cooking oil", "water", "sweet soy sauce", "bird''s eye chilli", "coriander leaves", "egg", "salt"]', '[{"name": "canned sardine", "name_ms": "sardin tin", "quantity": 1, "unit": "can", "note": "use sauce liquid; break up flesh"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": ""}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": ""}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "a little"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a little"}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": null, "unit": null, "note": "to taste"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "to taste"}, {"name": "coriander leaves", "name_ms": "daun ketumbar", "quantity": null, "unit": null, "note": "stirred in at end"}, {"name": "egg", "name_ms": "telur", "quantity": null, "unit": null, "note": "2-3 for omelette base"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "pinch for eggs"}]', '["Sauté 1 shallot and 3 garlic cloves in a little oil until soft.", "Add 1 can sardines — pour the sauce in first and add a little water.", "Break up the sardine flesh; add sweet soy sauce to taste and bird''s eye chilli.", "Cook until the filling thickens. Stir in coriander leaves; remove from heat.", "Fry 2–3 eggs into a thin plain omelette.", "Serve the sardine filling on top of the omelette."]', '["Tumis 1 bawang merah dan 3 ulas bawang putih dalam sedikit minyak sehingga layu.", "Masukkan 1 tin sardin — tuang sos dulu dan tambah sedikit air.", "Pecah-pecahkan isi sardin; masukkan kicap manis secukup rasa dan cili padi.", "Masak sehingga inti pekat. Masukkan daun ketumbar; angkat dari api.", "Goreng 2-3 biji telur jadi telur dadar nipis.", "Hidang inti sardin di atas telur dadar."]', '["halal", "fish", "egg", "sardine", "malaysian", "ramadan", "sahur"]', TRUE, FALSE, 'sardine tin 1 can; egg quantity flexible for omelette base', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7477057275442564359', 'Vanilla Sarsi Float', 'Vanilla Sarsi Float', 'A creamy Malaysian-style cream soda float with vanilla ice cream, evaporated milk and a drop of vanilla essence.', 'Float sarsi gaya Malaysia berkrim dengan aiskrim vanila, susu cair dan esen vanila.', 'Malaysian', 'Easy', 5, 0, 1, '["sarsi (cream soda)", "vanilla ice cream", "evaporated milk", "vanilla essence", "ice"]', '[{"name": "sarsi (cream soda)", "name_ms": "sarsi", "quantity": null, "unit": null, "note": "any brand; fill glass"}, {"name": "vanilla ice cream", "name_ms": "aiskrim vanila", "quantity": 1, "unit": null, "note": "1 scoop"}, {"name": "evaporated milk", "name_ms": "susu cair", "quantity": null, "unit": null, "note": "a splash"}, {"name": "vanilla essence", "name_ms": "esen vanila", "quantity": null, "unit": null, "note": "a few drops"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": "to fill glass"}]', '["Fill a glass with ice.", "Add a few drops of vanilla essence and a splash of evaporated milk.", "Pour sarsi (cream soda) over the ice.", "Top with 1 scoop of vanilla ice cream and serve immediately."]', '["Isi gelas dengan ais.", "Masukkan beberapa titik esen vanila dan sedikit susu cair.", "Tuang sarsi di atas ais.", "Letak 1 skop aiskrim vanila dan hidang dengan segera."]', '["halal", "drink", "cold", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'quantities are by feel; serve 1 tall glass', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7477057275442564359', 'Roselle Tea and Apple Soda (Teh Bunga Zapple)', 'Teh Bunga Zapple', 'A refreshing layered iftar drink: chilled roselle tea topped with apple sparkling drink, lychee, lemon, lemongrass and preserved sour plum.', 'Minuman berbuka berlapis yang menyegarkan: teh bunga ros sejuk ditambah air zapple, laici, lemon, serai dan asam boi.', 'Malaysian', 'Easy', 10, 0, 2, '["roselle tea", "apple sparkling drink", "lychee", "lemon", "lemongrass", "preserved sour plum", "mint", "ice"]', '[{"name": "roselle tea", "name_ms": "teh bunga ros", "quantity": null, "unit": null, "note": "brewed and chilled; sweeten to taste"}, {"name": "apple sparkling drink", "name_ms": "zapple", "quantity": null, "unit": null, "note": "any apple soda brand"}, {"name": "lychee", "name_ms": "laici", "quantity": null, "unit": null, "note": "canned or fresh"}, {"name": "lemon", "name_ms": "lemon", "quantity": null, "unit": null, "note": "sliced"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 1, "unit": null, "note": "bruised"}, {"name": "preserved sour plum", "name_ms": "asam boi", "quantity": 1, "unit": null, "note": ""}, {"name": "mint", "name_ms": "daun pudina", "quantity": null, "unit": null, "note": "a few leaves"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": "to fill glass"}]', '["Brew dried roselle flowers in hot water; sweeten to taste and chill.", "In a glass, add ice, lychee pieces, a bruised lemongrass stalk, 1 preserved sour plum, lemon slices and mint leaves.", "Pour the chilled roselle tea over.", "Top with Zapple (apple sparkling drink); stir gently and serve."]', '["Seduh bunga ros kering dalam air panas; manis secukup rasa dan sejukkan.", "Dalam gelas, masukkan ais, laici, 1 batang serai diketuk, 1 biji asam boi, hirisan lemon dan daun pudina.", "Tuang teh bunga ros sejuk di atas.", "Tambah Zapple (air epal berkarbonat); kacau perlahan dan hidang."]', '["halal", "drink", "cold", "roselle", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'amounts are to taste; quantities are by feel', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7477057275442564359', 'Vitagen Longan Drink', 'Vitagen Longan', 'A simple and refreshing iced drink: canned longan with syrup, diced watermelon and a probiotic Vitagen drink.', 'Minuman ais yang mudah dan menyegarkan: longan tin bersama airnya, kiub tembikai dan minuman probiotik Vitagen.', 'Malaysian', 'Easy', 5, 0, 1, '["probiotic drink", "longan", "watermelon", "ice"]', '[{"name": "probiotic drink", "name_ms": "vitagen", "quantity": 1, "unit": null, "note": "1 bottle Vitagen or similar"}, {"name": "longan", "name_ms": "buah longan", "quantity": 1, "unit": "can", "note": "with syrup"}, {"name": "watermelon", "name_ms": "tembikai", "quantity": null, "unit": null, "note": "diced"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": "to fill glass"}]', '["Fill a glass with ice.", "Add canned longan with its syrup.", "Add diced watermelon.", "Pour in 1 bottle of Vitagen (or any probiotic/vitamin drink); stir and serve."]', '["Isi gelas dengan ais.", "Masukkan longan tin bersama air longan.", "Masukkan kiub tembikai.", "Tuang 1 botol Vitagen (atau mana-mana minuman probiotik/vitamin); kacau dan hidang."]', '["halal", "drink", "cold", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'quantities are by feel; Vitagen = probiotic drink', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7477057275442564359', 'Vietnamese Coconut Coffee (Kopi Santan Vietnam)', 'Kopi Santan Vietnam', 'A viral creamy slushy drink: blended coconut milk slushy layered with strong instant coffee — a Vietnamese-inspired iftar favourite.', 'Minuman slushy yang viral: slushy santan yang diblend dilapis dengan kopi segera yang pekat — kegemaran berbuka gaya Vietnam.', 'Fusion', 'Easy', 10, 0, 2, '["coconut milk", "sweetened condensed milk", "salt", "ice", "instant coffee", "water"]', '[{"name": "coconut milk", "name_ms": "santan", "quantity": 2, "unit": null, "note": "2 small boxes"}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": 0.5, "unit": "cup", "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "a pinch"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": "generous amount for slushy"}, {"name": "instant coffee", "name_ms": "kopi segera", "quantity": 3, "unit": "tsp", "note": "dissolved in 2 tbsp hot water"}, {"name": "water", "name_ms": "air", "quantity": 2, "unit": "tbsp", "note": "hot; for dissolving coffee"}]', '["Blend ice, 2 small boxes coconut milk, 0.5 cup sweetened condensed milk and a pinch of salt until a slushy forms.", "Dissolve 3 tsp instant coffee in 2 tbsp hot water; stir until dissolved and let cool slightly.", "Fill a tall glass with the coconut slushy.", "Pour the coffee liquid over the top; serve immediately — stir before drinking."]', '["Blend ais, 2 kotak kecil santan, setengah cawan susu pekat manis dan secubit garam sehingga jadi slushy.", "Larutkan 3 sudu kecil kopi segera dalam 2 sudu besar air panas; kacau sehingga larut dan biarkan sedikit sejuk.", "Isi gelas tinggi dengan slushy santan.", "Tuang cecair kopi di atas; hidang dengan segera — kacau sebelum minum."]', '["halal", "drink", "coffee", "cold", "vietnamese", "fusion", "ramadan", "iftar"]', TRUE, FALSE, 'coconut milk 2 small boxes and condensed milk 0.5 cup are stated; serves 2 tall glasses', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7477428153808325906', 'Basmati Nasi Lemak with Spiced Fried Chicken and Sambal', 'Nasi Lemak Basmati dengan Ayam Goreng Berempah dan Sambal', 'A complete nasi lemak set with fluffy basmati coconut rice, rich spiced fried chicken marinated in lemongrass paste and curry powder, and a deep dark sambal made with two types of dried chilli.', 'Hidangan nasi lemak lengkap dengan nasi lemak basmati yang gebu, ayam goreng berempah yang juicy, dan sambal nasi lemak yang hitam pekat daripada dua jenis cili kering.', 'Malaysian', 'Medium', 50, 40, 6, '["dried chilli", "shallot", "garlic", "dried anchovies", "shrimp paste", "cooking oil", "palm sugar", "tamarind paste", "salt", "seasoning powder", "lemongrass", "galangal", "curry powder", "chilli powder", "coriander powder", "fennel seeds", "cumin", "turmeric powder", "curry leaf", "water", "chicken", "basmati rice", "ginger", "pandan leaf", "coconut milk"]', '[{"name": "dried chilli", "name_ms": "cili kering", "quantity": null, "unit": null, "note": "2 types: fat (not spicy) and thin (spicy); equal bowls of each"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": null, "unit": null, "note": "2 large for sambal; 1 for nasi"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": null, "unit": null, "note": "6 cloves for sambal; 5 cloves for nasi"}, {"name": "dried anchovies", "name_ms": "ikan bilis", "quantity": null, "unit": null, "note": "a small handful for sambal; fried separately for topping (not shown)"}, {"name": "shrimp paste", "name_ms": "belacan", "quantity": 1, "unit": null, "note": "1 block; roasted before blending"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "generous amount for sambal; also for nasi"}, {"name": "palm sugar", "name_ms": "gula melaka", "quantity": 2, "unit": null, "note": "2 small blocks; for sambal"}, {"name": "tamarind paste", "name_ms": "pes asam jawa", "quantity": 0.5, "unit": "tbsp", "note": "for sambal"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste (sambal + nasi)"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 6, "unit": null, "note": "4 stalks blended for ayam marinade; 2 stalks for nasi"}, {"name": "galangal", "name_ms": "lengkuas", "quantity": null, "unit": null, "note": "1 knob; blended for ayam marinade"}, {"name": "curry powder", "name_ms": "serbuk kari", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "chilli powder", "name_ms": "serbuk cili", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "coriander powder", "name_ms": "serbuk ketumbar", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "fennel seeds", "name_ms": "jintan manis", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "cumin", "name_ms": "jintan putih", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "curry leaf", "name_ms": "daun kari", "quantity": 2, "unit": null, "note": "2 stalks; for ayam marinade"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a little for marinade; 6 cups for nasi"}, {"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "basmati rice", "name_ms": "beras basmati", "quantity": 4, "unit": "cup", "note": "rinsed; for nasi lemak"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; for nasi"}, {"name": "pandan leaf", "name_ms": "daun pandan", "quantity": 2, "unit": null, "note": "for nasi"}, {"name": "coconut milk", "name_ms": "santan", "quantity": 1, "unit": null, "note": "1 small box; for nasi"}]', '["[Sambal] Boil the fat dried chillies separately from the thin dried chillies; blend each type separately. Blend 2 large onions, 6 garlic cloves, a small handful of dried anchovies and 1 roasted shrimp paste block together.", "Use equal proportions of the fat chilli paste and the blended aromatics (ratio 1:1). Heat plenty of oil; fry until the oil separates. Add 2 small blocks palm sugar, 0.5 tbsp tamarind paste, salt and seasoning powder.", "[Ayam Goreng Berempah] Blend 4 lemongrass stalks and a knob of galangal to a dry paste (press out excess water). Mix the paste with 1 tsp each: curry powder, chilli powder, coriander powder, fennel seeds, cumin, turmeric powder; 0.5 tsp salt; 2 stalks curry leaf; a little water. Marinate the chicken for 20 minutes.", "Fry the marinated chicken in medium-heat oil (not too hot or the spices will burn) until golden and cooked through.", "[Nasi Lemak Basmati] Rinse 4 cup basmati rice; add 5 garlic cloves, 1 onion, a knob of ginger, 2 pandan leaves, 2 lemongrass stalks, 1 small box coconut milk, 6 cup water, 2 tbsp cooking oil and 1 tsp salt; cook as normal."]', '["[Sambal] Rebus cili kering gemuk dan cili kering kurus secara berasingan; blend berasingan. Blend 2 biji bawang merah besar, 6 ulas bawang putih, segenggam kecil ikan bilis dan 1 ketul belacan bakar bersama.", "Guna nisbah 1:1 cili gemuk dengan blend bawang. Panaskan banyak minyak; goreng sehingga pecah minyak. Masukkan 2 ketul kecil gula Melaka, setengah sudu pes asam jawa, garam dan serbuk perasa.", "[Ayam Goreng Berempah] Blend 4 batang serai dan seketul lengkuas jadi pes kering (buang air berlebihan). Gaul pes dengan 1 sudu kecil setiap satu: serbuk kari, serbuk cili, serbuk ketumbar, jintan manis, jintan putih, serbuk kunyit; setengah sudu kecil garam; 2 tangkai daun kari; sedikit air. Perap ayam selama 20 minit.", "Goreng ayam dalam minyak api sederhana (jangan terlalu panas atau rempah akan hangus) sehingga golden dan masak.", "[Nasi Lemak Basmati] Basuh 4 cawan beras basmati; masukkan 5 ulas bawang putih, 1 biji bawang merah, seketul halia, 2 helai daun pandan, 2 batang serai, 1 kotak kecil santan, 6 cawan air, 2 sudu minyak masak dan 1 sudu kecil garam; masak seperti biasa."]', '["halal", "chicken", "rice", "coconut milk", "nasi lemak", "sambal", "malaysian", "ramadan"]', TRUE, TRUE, 'multi-component recipe (nasi lemak + sambal + ayam goreng berempah); some ratios are ''one bowl each'' without exact weights; chicken quantity not stated; fried anchovies and peanuts method not shown', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7477798778829851912', 'Sour and Spicy Chicken Soup (Asam Pedas Ayam)', 'Asam Pedas Ayam', 'A thick, tangy and fiery Malay soup with a whole chicken, tamarind, Vietnamese mint and torch ginger bud for deep aroma.', 'Kuah asam pedas Melayu yang pekat dan masam-masam pedas dengan satu ekor ayam, asam jawa, daun kesum dan bunga kantan.', 'Malaysian', 'Easy', 20, 30, 5, '["shallot", "garlic", "ginger", "fresh turmeric", "bird''s eye chilli", "shrimp paste", "lemongrass", "blended chilli", "chicken", "salt", "seasoning powder", "water", "tamarind paste", "Vietnamese mint", "torch ginger bud", "tomato", "okra"]', '[{"name": "shallot", "name_ms": "bawang merah", "quantity": 2, "unit": null, "note": "large; blended"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": "blended"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; blended"}, {"name": "fresh turmeric", "name_ms": "kunyit hidup", "quantity": null, "unit": null, "note": "small piece; blended"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 3, "unit": null, "note": "blended"}, {"name": "shrimp paste", "name_ms": "belacan", "quantity": null, "unit": null, "note": "1 small block; roasted and blended"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 2, "unit": null, "note": "bruised; sautéed"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": null, "unit": null, "note": "to taste; more = redder gravy"}, {"name": "chicken", "name_ms": "ayam", "quantity": 1, "unit": null, "note": "1 whole chicken, cut up; or substitute any protein"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a little for gravy"}, {"name": "tamarind paste", "name_ms": "pes asam jawa", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "Vietnamese mint", "name_ms": "daun kesum", "quantity": null, "unit": null, "note": "generous amount; quantity not stated"}, {"name": "torch ginger bud", "name_ms": "bunga kantan", "quantity": null, "unit": null, "note": "generous amount; quantity not stated"}, {"name": "tomato", "name_ms": "tomato", "quantity": 1, "unit": null, "note": ""}, {"name": "okra", "name_ms": "kacang bendi", "quantity": null, "unit": null, "note": "kacang bendi in transcript; quantity not stated"}]', '["Blend 2 large onions, 5 garlic cloves, a knob of ginger, a small piece of fresh turmeric, 3 bird''s eye chillies and 1 small roasted shrimp paste block until smooth.", "Sauté the blend with 2 bruised lemongrass stalks until fragrant.", "Add blended chilli (the more, the redder the gravy); continue to cook.", "Add 1 whole chicken (cut up) when the oil starts to separate; add salt, seasoning powder and a little water.", "Add 1 tbsp tamarind paste; stir.", "Add Vietnamese mint (daun kesum) and torch ginger bud (bunga kantan) — add generously for best aroma.", "Once the gravy begins to thicken, add 1 tomato and okra (kacang bendi); cook until the vegetables are tender.", "Serve hot with white rice."]', '["Blend 2 biji bawang merah besar, 5 ulas bawang putih, seketul halia, seketul kecil kunyit hidup, 3 biji cili padi dan 1 ketul kecil belacan yang sudah dibakar sehingga lumat.", "Tumis blend bersama 2 batang serai yang diketuk sehingga wangi.", "Masukkan cili kisar (lebih banyak = kuah lebih merah); sambung masak.", "Masukkan 1 ekor ayam (dipotong) bila minyak dah mula pecah; tambah garam, serbuk perasa dan sedikit air.", "Masukkan 1 sudu pes asam jawa; kacau.", "Masukkan daun kesum dan bunga kantan — masukkan banyak-banyak untuk aroma terbaik.", "Bila kuah mula pekat, masukkan 1 biji tomato dan kacang bendi; masak sehingga sayur lembut.", "Hidang panas dengan nasi putih."]', '["halal", "chicken", "sour", "spicy", "soup", "malaysian", "ramadan"]', TRUE, TRUE, 'Vietnamese mint and torch ginger bud quantities not stated; okra quantity not stated; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7477829809536535826', 'Hot Chicken Tenders with Creamy White Sauce', 'Hot Chicken Tenders dengan Creamy White Sauce', 'Crispy fried chicken strips coated in a hot spiced oil, served with a cool, tangy yogurt-mayo dipping sauce.', 'Isi ayam yang disalut tepung berlapis, digoreng crispy dan dimandikan dalam minyak berempah pedas, dihidang dengan sos krim putih dari yogurt dan mayo.', 'Western', 'Easy', 15, 20, 4, '["chicken fillet", "chicken fried flour", "water", "cooking oil", "paprika powder", "cayenne pepper", "garlic powder", "chilli flakes", "brown sugar", "salt", "plain yogurt", "mayonnaise", "lemon", "black pepper", "garlic"]', '[{"name": "chicken fillet", "name_ms": "isi ayam", "quantity": null, "unit": null, "note": "cut into long strips"}, {"name": "chicken fried flour", "name_ms": "tepung goreng ayam", "quantity": null, "unit": null, "note": "brand Bestari; split into wet and dry portions"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "to make the wet batter"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying; a portion also used to bloom the spice mix"}, {"name": "paprika powder", "name_ms": "serbuk paprika", "quantity": 1, "unit": "tbsp", "note": "for spice mix"}, {"name": "cayenne pepper", "name_ms": "cayenne pepper", "quantity": 1, "unit": "tbsp", "note": "for spice mix"}, {"name": "garlic powder", "name_ms": "garlic powder", "quantity": 0.5, "unit": "tbsp", "note": "for spice mix"}, {"name": "chilli flakes", "name_ms": "cili flakes", "quantity": 0.5, "unit": "tbsp", "note": "for spice mix"}, {"name": "brown sugar", "name_ms": "brown sugar", "quantity": 1, "unit": "tbsp", "note": "for spice mix"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste (spice mix and sauce)"}, {"name": "plain yogurt", "name_ms": "yogurt original", "quantity": 3, "unit": "tbsp", "note": "for sauce; original (unflavoured) variety"}, {"name": "mayonnaise", "name_ms": "mayonis", "quantity": 3, "unit": "tbsp", "note": "for sauce"}, {"name": "lemon", "name_ms": "lemon", "quantity": null, "unit": null, "note": "squeezed to taste for sauce"}, {"name": "black pepper", "name_ms": "black pepper", "quantity": null, "unit": null, "note": "to taste for sauce"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 2, "unit": "clove", "note": "crushed; for sauce"}]', '["Divide the chicken fried flour into two portions: mix one with water to form a wet batter; leave the other dry.", "Dip chicken fillets cut into long strips into the wet batter, then coat with the dry flour.", "Fry in very hot cooking oil until crispy and golden brown; drain and set aside.", "In a bowl, combine 1 tbsp paprika powder, 1 tbsp cayenne pepper, 0.5 tbsp garlic powder, 0.5 tbsp chilli flakes, 1 tbsp brown sugar, and salt to taste.", "Carefully ladle very hot oil from the frying pan directly over the spice mix to bloom the spices.", "Toss the fried chicken in the spiced oil until every piece is evenly coated.", "For the sauce: whisk together 3 tbsp plain yogurt, 3 tbsp mayonnaise, a squeeze of lemon juice, black pepper to taste, 2 cloves garlic (crushed), and salt to taste.", "Serve the chicken tenders hot alongside the creamy white sauce."]', '["Bahagikan tepung goreng ayam kepada 2 bahagian: satu dicampur dengan air untuk jadi basah, satu lagi kekal kering.", "Celupkan isi ayam yang dipotong panjang ke dalam tepung basah, kemudian salit dengan tepung kering.", "Goreng dalam minyak goreng betul-betul panas sehingga crispy golden brown, angkat dan tepi.", "Dalam mangkuk, campurkan 1 sudu besar serbuk paprika, 1 sudu besar cayenne pepper, setengah sudu besar garlic powder, setengah sudu besar cili flakes, 1 sudu besar brown sugar, dan garam secukupnya.", "Tuang minyak goreng yang betul-betul panas dari kuali ke atas campuran rempah tadi.", "Masukkan ayam goreng ke dalam minyak berempah, kacau sehingga rempah melekat rata.", "Untuk sos: campurkan 3 sudu besar yogurt original, 3 sudu besar mayonis, perahan lemon secukup rasa, black pepper, 2 ulas bawang putih yang dah ditumbuk hancur, dan garam — kacau sebati.", "Hidangkan chicken tenders panas-panas bersama sos krim putih."]', '["halal", "chicken", "fried", "spicy", "western", "ramadan"]', TRUE, TRUE, 'quantity of chicken fillet not stated; quantity of chicken fried flour not stated; prep_time estimated; cook_time estimated; servings estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7478170848759696648', 'Siamese Chicken Soup (Sup Ayam Siam)', 'Sup Ayam Siam', 'A peppery, sour and spicy Thai-style chicken soup with coriander roots, dried chilli and a generous finish of fish sauce and lime.', 'Sup ayam gaya Thai yang pedas, masam dan berempah dengan akar ketumbar, cili kering dan perahan limau serta sos ikan yang banyak.', 'Fusion', 'Easy', 10, 30, 4, '["chicken", "shallot", "garlic", "coriander roots", "dried chilli", "salt", "water", "soup powder", "tomato", "bird''s eye chilli", "fish sauce", "lime", "coriander leaves"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": 1, "unit": null, "note": "1 whole chicken"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 2, "unit": null, "note": "per pot"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": ""}, {"name": "coriander roots", "name_ms": "akar ketumbar", "quantity": 5, "unit": null, "note": ""}, {"name": "dried chilli", "name_ms": "cili kering", "quantity": 5, "unit": null, "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "enough to cover chicken"}, {"name": "soup powder", "name_ms": "perencah sup", "quantity": 1, "unit": null, "note": "1 packet Siamese chicken flavour"}, {"name": "tomato", "name_ms": "tomato", "quantity": 1, "unit": null, "note": ""}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "generously"}, {"name": "fish sauce", "name_ms": "sos ikan", "quantity": 3, "unit": "tbsp", "note": "added off heat"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "1-2 limes; added off heat"}, {"name": "coriander leaves", "name_ms": "daun ketumbar", "quantity": null, "unit": null, "note": "garnish"}]', '["Sauté 2 shallots and 5 garlic cloves briefly in a pot.", "Add 5 coriander roots and 5 dried chillies.", "Add 1 whole chicken; season with salt and cover with water.", "Add 3 tbsp Siamese chicken soup powder (1 packet); simmer until the chicken is tender and the broth has thickened, about 25–30 minutes.", "Add 1 tomato and generous bird''s eye chilli.", "Remove from heat; stir in 3 tbsp fish sauce and juice of 1–2 limes.", "Garnish with fresh coriander leaves and serve."]', '["Tumis 2 bawang merah dan 5 ulas bawang putih sebentar dalam periuk.", "Masukkan 5 akar ketumbar dan 5 biji cili kering.", "Masukkan 1 ekor ayam; tambah garam dan tutup dengan air.", "Masukkan 3 sudu serbuk sup Siam ayam (1 paket); reneh sehingga ayam empuk dan kuah pekat, lebih kurang 25-30 minit.", "Masukkan 1 biji tomato dan banyak cili padi.", "Padamkan api; masukkan 3 sudu sos ikan dan jus 1-2 biji limau nipis.", "Tabur daun ketumbar segar dan hidang."]', '["halal", "chicken", "soup", "thai", "sour", "spicy", "fusion", "malaysian", "ramadan"]', TRUE, FALSE, '1 whole chicken used; total cook time approx. 30 min', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7478170848759696648', 'Siamese Fish Soup (Sup Ikan Siam)', 'Sup Ikan Siam', 'The fish version of Sup Ayam Siam — same tangy, spicy broth but made with fish and a fish-flavoured Siamese soup packet.', 'Versi ikan bagi Sup Ayam Siam — kuah yang sama masam-pedas tetapi menggunakan ikan dan paket sup Siam rasa ikan.', 'Fusion', 'Easy', 10, 20, 4, '["red snapper", "shallot", "garlic", "coriander roots", "dried chilli", "salt", "water", "soup powder", "tomato", "bird''s eye chilli", "fish sauce", "lime", "coriander leaves"]', '[{"name": "red snapper", "name_ms": "ikan merah", "quantity": null, "unit": null, "note": "quantity not stated; or sea bass"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 2, "unit": null, "note": ""}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": ""}, {"name": "coriander roots", "name_ms": "akar ketumbar", "quantity": 5, "unit": null, "note": ""}, {"name": "dried chilli", "name_ms": "cili kering", "quantity": 5, "unit": null, "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "enough to cover fish"}, {"name": "soup powder", "name_ms": "perencah sup", "quantity": 1, "unit": null, "note": "1 packet Siamese fish flavour"}, {"name": "tomato", "name_ms": "tomato", "quantity": 1, "unit": null, "note": ""}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "generously"}, {"name": "fish sauce", "name_ms": "sos ikan", "quantity": 3, "unit": "tbsp", "note": "added off heat"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "1-2 limes; added off heat"}, {"name": "coriander leaves", "name_ms": "daun ketumbar", "quantity": null, "unit": null, "note": "garnish"}]', '["Sauté 2 shallots and 5 garlic cloves briefly.", "Add 5 coriander roots and 5 dried chillies.", "Add fish (red snapper or sea bass); season with salt and cover with water.", "Add 3 tbsp Siamese fish soup powder (look for the packet with a fish-head image); simmer until the fish is cooked through.", "Add 1 tomato and generous bird''s eye chilli.", "Remove from heat; stir in 3 tbsp fish sauce and juice of 1–2 limes.", "Garnish with coriander leaves and serve."]', '["Tumis 2 bawang merah dan 5 ulas bawang putih sebentar.", "Masukkan 5 akar ketumbar dan 5 biji cili kering.", "Masukkan ikan (siakap atau ikan merah); tambah garam dan tutup dengan air.", "Masukkan 3 sudu serbuk sup Siam rasa ikan (cari yang ada gambar kepala ikan); reneh sehingga ikan masak.", "Masukkan 1 biji tomato dan banyak cili padi.", "Padamkan api; masukkan 3 sudu sos ikan dan jus 1-2 biji limau nipis.", "Tabur daun ketumbar dan hidang."]', '["halal", "fish", "soup", "thai", "sour", "spicy", "fusion", "malaysian", "ramadan"]', TRUE, TRUE, 'fish quantity not stated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7478200055418162439', 'Spicy Wet Instant Noodles (Mee Goreng Basah)', 'Mee Goreng Basah Extra Pedas', 'A quick and satisfying spicy wet instant noodle dish with fish ball, fish cake, prawn and egg in a flavourful sauce.', 'Mi goreng basah yang cepat dan pedas dengan fishball, fishcake, udang dan telur dalam sos yang sedap.', 'Malaysian', 'Easy', 5, 10, 2, '["shallot", "garlic", "blended chilli", "fish ball", "fish cake", "sweet soy sauce", "tomato sauce", "chilli sauce", "water", "instant noodles", "prawn", "egg", "bird''s eye chilli", "lime"]', '[{"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": ""}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 2, "unit": "clove", "note": ""}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "fish ball", "name_ms": "fishball", "quantity": null, "unit": null, "note": ""}, {"name": "fish cake", "name_ms": "fishcake", "quantity": null, "unit": null, "note": ""}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "tomato sauce", "name_ms": "sos tomato", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "enough for broth"}, {"name": "instant noodles", "name_ms": "mi segera", "quantity": 2, "unit": null, "note": "2 packets; use only 1 seasoning packet"}, {"name": "prawn", "name_ms": "udang", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "egg", "name_ms": "telur", "quantity": 1, "unit": null, "note": "break yolk into broth"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "to taste"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "squeeze over to serve"}]', '["Sauté 1 onion and 2 garlic cloves; add 1 tbsp blended chilli.", "Add fish balls and fish cake; stir briefly.", "Add 1 tbsp sweet soy sauce, 1 tbsp tomato sauce and 1 tbsp chilli sauce; add water.", "Add 2 packets of instant noodles with 1 seasoning packet; wait for the noodles to soften.", "Add prawn, egg and bird''s eye chilli; break the egg yolk into the broth for a creamier sauce.", "Stir to combine; serve with a squeeze of lime."]', '["Tumis 1 biji bawang merah dan 2 ulas bawang putih; masukkan 1 sudu cili kisar.", "Masukkan fishball dan fishcake; kacau sebentar.", "Masukkan 1 sudu kicap manis, 1 sudu sos tomato dan 1 sudu sos cili; masukkan air.", "Masukkan 2 paket mi segera dengan 1 paket perencah; tunggu mi kembang.", "Masukkan udang, telur dan cili padi; pecahkan kuning telur ke dalam kuah untuk rasa lebih creamy.", "Gaul sebati; hidang dengan perahan limau nipis."]', '["halal", "noodles", "spicy", "quick", "seafood", "malaysian", "ramadan"]', TRUE, TRUE, 'prawn quantity not stated; vegetable not quantified; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7478542516279610642', 'Pandan Burnt Cheesecake (Basque Cheesecake)', 'Pandan Burnt Cheesecake', 'A crustless Basque-style cheesecake with pandan flavour — creamy inside with a deliberately charred top.', 'Cheesecake Basque tanpa kerak dengan perisa pandan — lembut berkrim di dalam, dengan permukaan yang sengaja dihanguskan.', 'Fusion', 'Easy', 20, 60, 8, '["cream cheese", "sugar", "egg", "all-purpose flour", "whipping cream", "pandan extract", "vanilla essence", "salt"]', '[{"name": "cream cheese", "name_ms": "krim cheese", "quantity": 1, "unit": null, "note": "1 block (approx. 250 g); at room temperature"}, {"name": "sugar", "name_ms": "gula", "quantity": 0.5, "unit": "cup", "note": ""}, {"name": "egg", "name_ms": "telur", "quantity": 3, "unit": null, "note": "transcript says 3; possibly 4 — needs_review"}, {"name": "all-purpose flour", "name_ms": "tepung gandum", "quantity": 2, "unit": "tbsp", "note": "sifted"}, {"name": "whipping cream", "name_ms": "whipping cream", "quantity": 1, "unit": "cup", "note": ""}, {"name": "pandan extract", "name_ms": "ekstrak pandan", "quantity": null, "unit": null, "note": "a few drops; or pandan paste"}, {"name": "vanilla essence", "name_ms": "esen vanila", "quantity": 1, "unit": "tsp", "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "a pinch"}]', '["Let 1 block cream cheese come to room temperature; beat until smooth.", "Add 0.5 cup sugar; beat well.", "Add 3 eggs one at a time, mixing after each.", "Sift in 2 tbsp all-purpose flour; fold in.", "Add 1 cup whipping cream, a few drops of pandan extract, 1 tsp vanilla essence and a pinch of salt; mix until smooth.", "Line a springform tin with baking paper; pour in the batter.", "Bake at 220°C (fan) for 55–65 minutes — the top should be deep brown/charred while the centre remains slightly jiggly.", "Cool completely at room temperature before slicing."]', '["Biarkan 1 blok krim cheese ke suhu bilik; pukul sehingga licin.", "Masukkan setengah cawan gula; pukul sebati.", "Masukkan 3 biji telur satu persatu, gaul setiap kali.", "Ayak masuk 2 sudu tepung gandum; lipat masuk.", "Masukkan 1 cawan whipping cream, beberapa titik pewarna/ekstrak pandan, 1 sudu kecil esen vanila dan secubit garam; gaul sehingga licin.", "Alaskan loyang springform dengan kertas pembakar; tuang adunan.", "Bakar pada suhu 220°C (kipas) selama 55-65 minit — bahagian atas sepatutnya perang gelap/hangus manakala tengah masih sedikit bergetar.", "Sejukkan sepenuhnya di suhu bilik sebelum dipotong."]', '["halal", "dessert", "cheesecake", "pandan", "baked", "western", "ramadan"]', TRUE, TRUE, 'egg count stated as ''3 biji'' but transcript mentions adding an extra — ambiguous whether 3 or 4 eggs total; bake time 55-65 min; cream cheese block size stated as 1 block', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7478580043820616967', 'Smash Burger Tacos', 'Smash Burger Tacos', 'Thin, crispy smashed beef patties cooked inside a folded flour tortilla — a fusion of burger and taco with cheese, sauce and lettuce.', 'Patty daging nipis yang dihempas dan garing dimasak di dalam tortilla yang dilipat — gabungan burger dan taco dengan cheese, sos dan salad.', 'Fusion', 'Easy', 15, 15, 4, '["minced beef", "salt", "black pepper", "garlic powder", "cooking oil", "flour tortilla", "processed cheese", "mayonnaise", "chilli sauce", "lettuce", "tomato"]', '[{"name": "minced beef", "name_ms": "daging cincang", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "black pepper", "name_ms": "black pepper", "quantity": null, "unit": null, "note": "to taste"}, {"name": "garlic powder", "name_ms": "garlic powder", "quantity": null, "unit": null, "note": "to taste"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "a little for griddle"}, {"name": "flour tortilla", "name_ms": "roti wrap", "quantity": null, "unit": null, "note": "number not stated"}, {"name": "processed cheese", "name_ms": "cheese", "quantity": null, "unit": null, "note": "1 slice per taco"}, {"name": "mayonnaise", "name_ms": "mayonis", "quantity": null, "unit": null, "note": "for serving"}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": null, "unit": null, "note": "for serving"}, {"name": "lettuce", "name_ms": "salad", "quantity": null, "unit": null, "note": "shredded"}, {"name": "tomato", "name_ms": "tomato", "quantity": null, "unit": null, "note": "diced"}]', '["Season minced beef with salt, black pepper and garlic powder; shape into loose balls.", "Heat a flat griddle or pan; add a little oil.", "Place a ball of beef on the pan; immediately press flat with a spatula (smash) until very thin.", "Place a flour tortilla on top of the patty; press down.", "When the beef is seared on one side, flip the whole thing (tortilla side down) to toast the tortilla.", "Lay a slice of cheese on the beef; fold the tortilla in half.", "Serve with mayonnaise, chilli sauce, shredded lettuce and diced tomato."]', '["Perasa daging cincang dengan garam, black pepper dan garlic powder; bentuk menjadi bebola longgar.", "Panaskan griddle atau kuali rata; masukkan sedikit minyak.", "Letakkan bebola daging di atas kuali; terus hempas rata dengan pengepit (smash) sehingga sangat nipis.", "Letakkan tortilla di atas patty; tekan.", "Bila daging dah garing di satu sisi, balik kesemuanya (sisi tortilla ke bawah) untuk bakar tortilla.", "Letakkan sekeping cheese di atas daging; lipat tortilla jadi dua.", "Hidang dengan mayo, sos cili, hirisan salad dan tomato kiub."]', '["halal", "beef", "burger", "taco", "fusion", "western", "ramadan", "easy"]', TRUE, TRUE, 'beef quantity not stated; number of wraps not stated; cook/prep times estimated; flour tortilla substituted for taco shell', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7478912764619115783', 'Steamed Chicken with Indonesian Sambal (Ayam Kukus Sambal Embe)', 'Ayam Kukus Sambal Embe', 'Tender steamed chicken thighs, shredded and topped with a hot sambal made from pouring sizzling oil over pounded chillies and shrimp paste — Indonesian Embe style.', 'Peha ayam yang dikukus hingga lembut kemudian disuwir dan ditutup dengan sambal yang dimasak dengan cara menuang minyak panas ke atas cili tumbuk — cara Embe dari Indonesia.', 'Indonesian', 'Easy', 10, 30, 2, '["chicken", "oyster sauce", "sesame oil", "tapioca flour", "white pepper", "salt", "shallot", "garlic", "green bird''s eye chilli", "bird''s eye chilli", "shrimp paste", "cooking oil", "calamansi lime", "soy sauce"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": 2, "unit": null, "note": "thigh pieces"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 1, "unit": "tbsp", "note": "for marinade"}, {"name": "sesame oil", "name_ms": "minyak bijan", "quantity": 0.5, "unit": "tbsp", "note": "for marinade"}, {"name": "tapioca flour", "name_ms": "tepung ubi kayu", "quantity": 0.5, "unit": "tbsp", "note": "for marinade"}, {"name": "white pepper", "name_ms": "white pepper", "quantity": null, "unit": null, "note": "to taste; for marinade"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste; for marinade"}, {"name": "shallot", "name_ms": "bawang ros", "quantity": 5, "unit": null, "note": "for sambal"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": "for sambal"}, {"name": "green bird''s eye chilli", "name_ms": "cili padi hijau", "quantity": 4, "unit": null, "note": "for sambal"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 4, "unit": null, "note": "red; for sambal"}, {"name": "shrimp paste", "name_ms": "belacan", "quantity": 1, "unit": null, "note": "1 block; roasted and pounded"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "must be very hot when poured over sambal"}, {"name": "calamansi lime", "name_ms": "limau kasturi", "quantity": null, "unit": null, "note": "squeezed over to serve"}, {"name": "soy sauce", "name_ms": "kicap", "quantity": null, "unit": null, "note": "drizzled over to serve"}]', '["Mix 2 chicken thigh pieces with 1 tbsp oyster sauce, 0.5 tbsp sesame oil, 0.5 tbsp tapioca flour, white pepper and salt.", "Add spring onion on top and steam for 25 minutes until cooked through.", "Let cool; shred the chicken. Mix a little of the steaming liquid back in to keep it moist.", "[Sambal] Fry 5 small red shallots, 5 garlic cloves, 4 green bird''s eye chillies, 4 red bird''s eye chillies and 1 roasted shrimp paste block until wilted.", "Pound the fried ingredients until coarsely ground.", "Heat cooking oil until very hot; pour directly over the pounded sambal — this cooks it in seconds.", "Spoon the sambal over the shredded chicken; squeeze calamansi lime over and drizzle with soy sauce to serve."]', '["Gaul 2 ketul peha ayam dengan 1 sudu sos tiram, setengah sudu minyak bijan, setengah sudu tepung ubi kayu, white pepper dan garam.", "Letakkan daun bawang di atas dan kukus selama 25 minit sehingga masak sepenuhnya.", "Biarkan sejuk; carik-carikkan ayam. Gaul sedikit air kukus kembali untuk kekalkan moist.", "[Sambal] Goreng 5 biji bawang Ros, 5 ulas bawang putih, 4 biji cili padi hijau, 4 biji cili padi merah dan 1 ketul belacan yang sudah dibakar sehingga layu.", "Tumbuk semua bahan yang dah digoreng sehingga lumat kasar.", "Panaskan minyak masak sehingga betul-betul panas; tuang terus ke atas sambal yang dah ditumbuk — ini memasaknya dalam masa singkat.", "Senduk sambal di atas ayam suwir; perah limau kasturi dan tuang kicap untuk dihidang."]', '["halal", "chicken", "steamed", "sambal", "indonesian", "easy", "ramadan"]', TRUE, FALSE, 'recipe for 2 pieces chicken thigh; steaming time 25 min; prep/cook times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7479285273063427336', 'Roti Khurasan (Beef-Stuffed Crispy Spring Roll Burger)', 'Roti Khurasan (Burger Dibalut Kulit Popia)', 'A unique snack that wraps a spiced minced-beef burger bun in spring roll pastry and deep-fries until crispy — crunchy outside, hearty inside.', 'Makanan unik yang membalut burger bun berinti daging cincang berbumbu dengan kulit popia kemudian digoreng sehingga crispy — garing kat luar, padat kat dalam.', 'Fusion', 'Easy', 20, 20, 4, '["onion", "garlic", "minced beef", "curry powder", "tomato sauce", "oyster sauce", "chilli sauce", "water", "black pepper", "salt", "seasoning powder", "burger bun", "butter", "mayonnaise", "processed cheese", "spring roll pastry", "cooking oil"]', '[{"name": "onion", "name_ms": "bawang holland", "quantity": 1, "unit": null, "note": "chopped"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": "chopped"}, {"name": "minced beef", "name_ms": "daging cincang", "quantity": 200, "unit": "g", "note": "frozen is fine"}, {"name": "curry powder", "name_ms": "serbuk kari", "quantity": 2, "unit": "tbsp", "note": "for filling"}, {"name": "tomato sauce", "name_ms": "sos tomato", "quantity": 1, "unit": "tbsp", "note": "for filling"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 1, "unit": "tbsp", "note": "for filling"}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": 2, "unit": "tbsp", "note": "for filling; more for assembling"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a little to prevent burning"}, {"name": "black pepper", "name_ms": "black pepper", "quantity": null, "unit": null, "note": "to taste"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "burger bun", "name_ms": "roti burger", "quantity": null, "unit": null, "note": "quantity not stated; 1 per serving"}, {"name": "butter", "name_ms": "butter", "quantity": null, "unit": null, "note": "to spread on bun; quantity not stated"}, {"name": "mayonnaise", "name_ms": "mayonis", "quantity": null, "unit": null, "note": "to spread on bun; quantity not stated"}, {"name": "processed cheese", "name_ms": "cheese", "quantity": null, "unit": null, "note": "quantity per roll not stated"}, {"name": "spring roll pastry", "name_ms": "kulit popia", "quantity": null, "unit": null, "note": "water to seal edges"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "deep frying; must be very hot"}]', '["Sauté 1 sweet onion and 5 garlic cloves (chopped); add 200 g frozen minced beef.", "Add 2 tbsp curry powder, 1 tbsp tomato sauce, 1 tbsp oyster sauce and 2 tbsp chilli sauce; add water to prevent burning.", "Season with black pepper, salt and seasoning powder; cook until the filling is dry. Set aside.", "Cut a burger bun in half; spread butter on both sides.", "Spread a little mayonnaise on the cut surfaces; add the beef filling generously, a little more chilli sauce and a slice of cheese.", "Press the bun halves together and wrap tightly in spring roll pastry, sealing all edges with water.", "Deep-fry in very hot oil for just a few seconds until golden and puffed. Drain and serve hot."]', '["Tumis 1 biji bawang Holland dan 5 ulas bawang putih (dihacam); masukkan 200g daging cincang beku.", "Masukkan 2 sudu serbuk kari, 1 sudu sos tomato, 1 sudu sos tiram dan 2 sudu sos cili; masukkan air elak hangus.", "Tambah black pepper, garam dan serbuk perasa; masak sehingga inti kering. Ketepikan.", "Potong roti burger menjadi dua; sapu butter di kedua-dua belah.", "Sapu sedikit mayo pada permukaan yang dipotong; letak inti daging banyak-banyak, sedikit sos cili lagi dan sekeping cheese.", "Kepit dua bahagian bun dan balut rapat dengan kulit popia, lekatkan semua tepi dengan air.", "Goreng dalam minyak betul-betul panas hanya beberapa saat sehingga golden dan kembang. Toskan dan hidang panas."]', '["halal", "beef", "fried", "snack", "fusion", "malaysian", "ramadan"]', TRUE, TRUE, 'butter for spreading not quantified; mayonnaise quantity not stated; cheese slices quantity per roll not stated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7479656713285569800', 'Stir-Fried Flat Rice Noodles with Cockles (Kuey Teow Goreng Kerang)', 'Kuey Teow Goreng Kerang', 'Classic wok-fried flat rice noodles with cockles, fish ball, egg, garlic chives and bean sprouts in a smoky dark soy sauce.', 'Kuetiau goreng klasik dengan kerang, fishball, telur, kucai dan taugeh dalam kicap karamel yang wangi.', 'Malaysian', 'Easy', 10, 10, 2, '["flat rice noodles", "caramel soy sauce", "sweet soy sauce", "cooking oil", "shallot", "garlic", "blended chilli", "fish ball", "cockles", "oyster sauce", "egg", "garlic chives", "bean sprouts"]', '[{"name": "flat rice noodles", "name_ms": "kuetiau", "quantity": 1, "unit": null, "note": "1 packet; separated"}, {"name": "caramel soy sauce", "name_ms": "kicap karamel", "quantity": 1, "unit": "tbsp", "note": "for pre-seasoning noodles"}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": 1, "unit": "tbsp", "note": "for pre-seasoning; more to taste during cooking"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "a little for noodles and sautéing"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": ""}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": ""}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "fish ball", "name_ms": "fishball", "quantity": null, "unit": null, "note": ""}, {"name": "cockles", "name_ms": "kerang", "quantity": null, "unit": null, "note": "can substitute prawn or chicken"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": null, "unit": null, "note": "a little to taste"}, {"name": "egg", "name_ms": "telur", "quantity": 1, "unit": null, "note": "scrambled into noodles"}, {"name": "garlic chives", "name_ms": "kucai", "quantity": null, "unit": null, "note": ""}, {"name": "bean sprouts", "name_ms": "taugeh", "quantity": null, "unit": null, "note": ""}]', '["Separate 1 packet of flat rice noodles; toss with 1 tbsp caramel soy sauce, 1 tbsp sweet soy sauce and a little oil.", "Stir-fry the seasoned noodles in a hot wok briefly until the soy sauce is absorbed; remove and set aside.", "Sauté 1 onion and 3 garlic cloves; add 1 tbsp blended chilli.", "Add fish balls and cockles; toss until the cockles are just cooked.", "Return the noodles to the wok; add a little extra oyster sauce and sweet soy sauce to taste.", "Push everything to the side; crack in 1 egg and scramble it, then fold into the noodles.", "Adjust seasoning; add garlic chives and bean sprouts. Serve with pickled chilli or sliced fresh chilli in soy sauce."]', '["Leraikan 1 paket kuetiau; gaul dengan 1 sudu kicap karamel, 1 sudu kicap manis dan sedikit minyak.", "Goreng kuetiau yang dah dibumbui dalam kuali panas sebentar sehingga kicap meresap; angkat dan ketepikan.", "Tumis 1 biji bawang merah dan 3 ulas bawang putih; masukkan 1 sudu cili kisar.", "Masukkan fishball dan kerang; gaul sehingga kerang baru masak.", "Masukkan balik kuetiau; tambah sedikit sos tiram dan kicap manis mengikut rasa.", "Tolak ke tepi; pecahkan 1 biji telur dan scramble, kemudian gaul bersama kuetiau.", "Laraskan perasa; masukkan kucai dan taugeh. Hidang dengan cili jeruk atau cili potong dalam kicap."]', '["halal", "noodles", "cockles", "stir-fry", "malaysian", "ramadan"]', TRUE, FALSE, 'kucai and taugeh quantities flexible; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7480080996398828807', 'Crispy Tempeh and Tofu with Sambal Kicap', 'Tempe Goreng Crispy dan Tauhu dengan Sambal Kicap', 'Golden crispy fried tempeh slices and tofu served with a fresh blended sweet soy and chilli dipping sauce.', 'Hirisan tempe dan tauhu yang digoreng garing dan golden dihidang bersama sambal kicap manis-pedas.', 'Malaysian', 'Easy', 10, 15, 3, '["tempeh", "tofu", "cooking oil", "sweet soy sauce", "bird''s eye chilli", "garlic", "calamansi lime"]', '[{"name": "tempeh", "name_ms": "tempe", "quantity": 1, "unit": null, "note": "1 block; sliced thin"}, {"name": "tofu", "name_ms": "tauhu", "quantity": 1, "unit": null, "note": "1 block firm tofu; cubed"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for deep frying"}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": null, "unit": null, "note": "for sambal kicap; amount to taste"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 5, "unit": null, "note": "blended into sambal kicap"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": "blended into sambal kicap"}, {"name": "calamansi lime", "name_ms": "limau kasturi", "quantity": 3, "unit": null, "note": "juiced into sambal kicap"}]', '["Slice 1 block tempeh thinly; cut 1 block firm tofu into cubes.", "Deep-fry both in hot oil until golden and crispy on all sides. Drain.", "[Sambal kicap] Blend sweet soy sauce, 5 bird''s eye chillies and 3 garlic cloves until smooth.", "Squeeze in juice of 3 calamansi limes.", "Serve the fried tempeh and tofu with sambal kicap on the side."]', '["Potong 1 blok tempe nipis-nipis; potong 1 blok tauhu keras menjadi kiub.", "Goreng kedua-duanya dalam minyak panas sehingga golden crispy semua sisi. Toskan.", "[Sambal kicap] Blend kicap manis, 5 biji cili padi dan 3 ulas bawang putih sehingga lumat.", "Perah jus 3 biji limau kasturi.", "Hidang tempe dan tauhu goreng bersama sambal kicap."]', '["halal", "vegetarian", "tempeh", "tofu", "sambal", "malaysian", "ramadan"]', TRUE, FALSE, 'recipe for 1 block tempeh and 1 block tofu; sambal kicap is served on the side; prep/cook times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7480398655820795144', 'Cockle Sambal with Dried Tamarind (Sambal Taun)', 'Sambal Taun (Sambal Kerang)', 'A tangy, spicy cockle sambal soured with dried tamarind — a traditional Malay sambal that is excellent with white rice.', 'Sambal kerang yang masam-pedas dengan asam keping — sambal Melayu tradisi yang sangat sedap bersama nasi putih.', 'Malaysian', 'Easy', 15, 15, 3, '["cockles", "cooking oil", "shallot", "garlic", "blended chilli", "dried tamarind slices", "water", "palm sugar", "salt", "seasoning powder", "kaffir lime leaf"]', '[{"name": "cockles", "name_ms": "kerang", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": ""}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "sliced"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": ""}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 3, "unit": "tbsp", "note": ""}, {"name": "dried tamarind slices", "name_ms": "asam keping", "quantity": null, "unit": null, "note": "4-5 pieces; quantity vague"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a little"}, {"name": "palm sugar", "name_ms": "gula melaka", "quantity": 1, "unit": null, "note": "1 small block"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "kaffir lime leaf", "name_ms": "daun limau purut", "quantity": null, "unit": null, "note": "torn; for fragrance"}]', '["Open and wash cockles; blanch briefly in boiling water. Set aside.", "Sauté sliced onion and 5 garlic cloves in oil until fragrant.", "Add 3 tbsp blended chilli; fry until oil separates.", "Add 4–5 dried tamarind slices and a little water; stir.", "Season with 1 small palm sugar block, salt and seasoning powder.", "Add cockles; fold in gently. Do not over-cook — cockles toughen quickly.", "Add torn kaffir lime leaves for fragrance; serve immediately."]', '["Buka dan basuh kerang; celur sebentar dalam air mendidih. Ketepikan.", "Tumis hirisan bawang dan 5 ulas bawang putih dalam minyak sehingga wangi.", "Masukkan 3 sudu cili kisar; goreng sehingga pecah minyak.", "Masukkan 4-5 keping asam keping dan sedikit air; kacau.", "Tambah 1 ketul kecil gula Melaka, garam dan serbuk perasa.", "Masukkan kerang; gaul perlahan. Jangan masak terlalu lama — kerang mudah keras.", "Masukkan daun limau purut yang dicarik untuk aroma; hidang dengan segera."]', '["halal", "seafood", "cockles", "sambal", "sour", "malaysian", "ramadan"]', TRUE, TRUE, 'cockles quantity not stated; dried tamarind slices quantity stated as ''4-5 keping''; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7480771496906902802', 'Banana Chocolate Chip Cake with Custard Sauce', 'Kek Pisang Chocolate Chip dengan Sos Kastard', 'A moist banana cake packed with chocolate chips, baked until golden and served warm or chilled with a smooth vanilla custard sauce.', 'Kek pisang yang sangat moist dipenuhi dengan coklat chip, dibakar hingga cantik dan dihidangkan panas-panas atau sejuk bersama sos kastard vanilla yang creamy.', 'Western', 'Easy', 20, 50, 10, '["banana", "all-purpose flour", "bicarbonate of soda", "baking powder", "salt", "egg", "sweetened condensed milk", "vanilla essence", "butter", "chocolate chips", "liquid creamer", "water", "sugar", "custard powder"]', '[{"name": "banana", "name_ms": "pisang", "quantity": 6, "unit": null, "note": "very ripe; a few slices also used as topping"}, {"name": "all-purpose flour", "name_ms": "tepung gandum", "quantity": 2.5, "unit": "cup", "note": ""}, {"name": "bicarbonate of soda", "name_ms": "bicarbonat soda", "quantity": 2, "unit": "tsp", "note": ""}, {"name": "baking powder", "name_ms": "baking powder", "quantity": 2, "unit": "tsp", "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": 1, "unit": "tsp", "note": "for cake batter"}, {"name": "egg", "name_ms": "telur", "quantity": 4, "unit": null, "note": ""}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": 0.5, "unit": "cup", "note": "brand FNN"}, {"name": "vanilla essence", "name_ms": "esen vanila", "quantity": 2, "unit": "tsp", "note": "1 tsp for cake batter; 1 tsp for custard sauce (stated verbally in transcript, not filmed)"}, {"name": "butter", "name_ms": "butter", "quantity": 83, "unit": "g", "note": "1/3 block, approx. 83 g assuming 250 g block; melted"}, {"name": "chocolate chips", "name_ms": "coklat chip", "quantity": 1, "unit": "cup", "note": "some reserved as topping"}, {"name": "liquid creamer", "name_ms": "krimer siap", "quantity": 1, "unit": "can", "note": "approx. 375 ml; brand FNN; for custard sauce"}, {"name": "water", "name_ms": "air", "quantity": 0.5, "unit": "cup", "note": "for custard sauce"}, {"name": "sugar", "name_ms": "gula", "quantity": 2, "unit": "tbsp", "note": "for custard sauce"}, {"name": "custard powder", "name_ms": "tepung kastard", "quantity": 1.5, "unit": "tbsp", "note": "for custard sauce"}]', '["Coarsely mash 6 ripe bananas.", "Add 2.5 cup all-purpose flour, 2 tsp bicarbonate of soda, 2 tsp baking powder, and 1 tsp salt.", "Add 4 eggs, 0.5 cup sweetened condensed milk, 1 tsp vanilla essence, and 1/3 block melted butter; mix until combined.", "Add 1 cup chocolate chips and mix in.", "Pour the batter into a baking tin (or divide between 2 tins).", "Arrange banana slices and chocolate chips on top.", "Bake at 170°C for 50 minutes.", "For the custard sauce: stir together 1 can liquid creamer, 0.5 cup water, 2 tbsp sugar, 1.5 tbsp custard powder, and 1 tsp vanilla essence until smooth, then cook in a saucepan, stirring constantly, until thickened.", "Serve warm or chilled with the custard sauce."]', '["Lenyek kasar-kasar 6 biji pisang yang betul-betul masak.", "Tambahkan 2 cawan setengah tepung gandum, 2 sudu kecil bicarbonat soda, 2 sudu kecil baking powder, dan 1 sudu kecil garam.", "Masukkan 4 biji telur, setengah cawan krimer manis, 1 sudu kecil esen vanila, dan 1/3 blok butter cair; gaul sehingga sebati.", "Masukkan 1 cawan coklat chip dan gaul rata.", "Tuangkan adunan ke dalam loyang (boleh bahagi kepada 2 loyang).", "Susun hirisan pisang dan coklat chip di atas adunan.", "Bakar dalam oven pada suhu 170°C selama 50 minit.", "Untuk sos kastard: kacau sebati 1 tin krimer siap, setengah cawan air, 2 sudu besar gula, 1 sudu besar setengah tepung kastard, dan 1 sudu kecil esen vanila sehingga larut, kemudian masak dalam periuk atas api sederhana sambil dikacau sehingga pekat.", "Hidangkan kek panas-panas atau sejuk bersama sos kastard."]', '["halal", "dessert", "baked", "cake", "banana", "chocolate", "ramadan", "raya"]', TRUE, TRUE, 'butter quantity converted from ''1/3 block'' to 83 g (assumes 250 g standard block); vanilla essence for custard sauce stated verbally in transcript but not filmed; prep_time estimated; servings estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7480808151659318536', 'Crispy Banana Egg Pancake (Thai-Style Paratha)', 'Crispy Thai Pancake dengan Pisang dan Telur', 'A simple, crispy egg-and-banana filled paratha pancake made by pressing a frozen paratha flat and cooking over a very low flame until golden — no batter needed.', 'Roti paratha yang dilenyekkan nipis-nipis dan diisi dengan telur dan hirisan pisang, dimasak atas api paling kecil sehingga crispy keemasan.', 'Fusion', 'Easy', 5, 5, 1, '["egg", "banana", "frozen paratha", "sweetened condensed milk"]', '[{"name": "egg", "name_ms": "telur", "quantity": 1, "unit": null, "note": "per pancake"}, {"name": "banana", "name_ms": "pisang", "quantity": null, "unit": null, "note": "sliced; quantity not stated"}, {"name": "frozen paratha", "name_ms": "roti paratha", "quantity": null, "unit": null, "note": "number of parathas not stated"}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": null, "unit": null, "note": "optional topping; amount to taste"}]', '["Crack 1 egg into a bowl, add sliced banana and mix lightly.", "Take a frozen paratha (still in its plastic wrapper) and press it flat to thin it out; peel off one layer of plastic and place it in an unheated pan.", "Peel off the remaining plastic, add the egg-banana mixture on top and fold in all four sides.", "Cook over the lowest heat possible to avoid burning until the paratha is golden and crispy.", "Slice and skewer with toothpicks; drizzle sweetened condensed milk or any topping of choice over the top."]', '["Pecahkan 1 biji telur ke dalam mangkuk, masukkan hirisan pisang dan kacau perlahan.", "Ambil roti paratha (masih dalam plastiknya) dan lenyekkan sehingga nipis; buka 1 lapisan plastik dan letakkan dalam kuali yang belum dipanaskan.", "Buka plastik yang tinggal, letakkan adunan telur-pisang di atas dan lipat semua tepi ke dalam.", "Masak atas api paling kecil untuk elak hangus sehingga roti crispy keemasan.", "Potong dan cucuk dengan lidi; tuangkan susu pekat manis atau topping pilihan di atas."]', '["halal", "dessert", "snack", "banana", "egg", "crispy", "thai", "ramadan"]', TRUE, TRUE, 'number of parathas and bananas not stated; toppings are optional and not quantified', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7481141489939123463', 'Fried Chicken with Torch Ginger Bud Sambal (Ayam Goreng Sambal Kantan)', 'Ayam Goreng Sambal Kantan', 'Marinated fried chicken served with a fragrant fresh sambal made from blended torch ginger bud — aromatic and uniquely Malay.', 'Ayam goreng berempah dihidang dengan sambal bunga kantan yang segar dan wangi — aroma khas Melayu.', 'Malaysian', 'Easy', 30, 25, 4, '["chicken", "turmeric powder", "salt", "seasoning powder", "garlic", "cooking oil", "torch ginger bud", "bird''s eye chilli", "shallot", "shrimp paste", "calamansi lime", "sugar"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": 1, "unit": "tsp", "note": "for marinade"}, {"name": "salt", "name_ms": "garam", "quantity": 1, "unit": "tsp", "note": "for marinade; more to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste; for marinade"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": "crushed; for marinade"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying"}, {"name": "torch ginger bud", "name_ms": "bunga kantan", "quantity": null, "unit": null, "note": "quantity not stated; blended into sambal"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 10, "unit": null, "note": "blended into sambal"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "blended into sambal"}, {"name": "shrimp paste", "name_ms": "belacan", "quantity": 1, "unit": null, "note": "1 small block; roasted; blended into sambal"}, {"name": "calamansi lime", "name_ms": "limau kasturi", "quantity": 5, "unit": null, "note": "juiced"}, {"name": "sugar", "name_ms": "gula", "quantity": 1, "unit": "tsp", "note": "for sambal"}]', '["Marinate chicken with 1 tsp turmeric powder, 1 tsp salt, seasoning powder and 3 crushed garlic cloves; rest 20 minutes.", "Deep-fry until golden and cooked. Set aside.", "[Sambal Kantan] Blend torch ginger buds, 10 bird''s eye chillies, 1 onion and 1 small roasted shrimp paste block until coarse.", "Squeeze in juice of 5 calamansi limes; add 1 tsp sugar and salt to taste.", "Serve the fried chicken topped with the sambal kantan."]', '["Perap ayam dengan 1 sudu kecil serbuk kunyit, 1 sudu kecil garam, serbuk perasa dan 3 ulas bawang putih yang dihancurkan; rehat 20 minit.", "Goreng dalam minyak panas sehingga golden dan masak. Ketepikan.", "[Sambal Kantan] Blend bunga kantan, 10 biji cili padi, 1 biji bawang dan 1 ketul kecil belacan bakar sehingga kasar.", "Perah jus 5 biji limau kasturi; tambah 1 sudu kecil gula dan garam secukupnya.", "Hidang ayam goreng dengan sambal kantan di atas."]', '["halal", "chicken", "fried", "sambal", "torch ginger", "malaysian", "ramadan"]', TRUE, TRUE, 'chicken quantity not stated; bunga kantan (torch ginger bud) quantity not stated; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7481511745421315336', 'Roselle Lychee Jelly (Jeli Ros Laici)', 'Jeli Ros Laici', 'A wobbly roselle-flavoured jelly mixed with canned lychee and served cold in a creamy evaporated milk sauce.', 'Jeli bunga ros yang gebu-gebu dicampur laici tin dan dihidang sejuk dalam sos susu cair yang berkrim.', 'Malaysian', 'Easy', 10, 10, 4, '["jelly powder", "roselle syrup", "water", "lychee", "evaporated milk", "sweetened condensed milk"]', '[{"name": "jelly powder", "name_ms": "serbuk jeli", "quantity": 1, "unit": null, "note": "1 packet"}, {"name": "roselle syrup", "name_ms": "sirap ros", "quantity": null, "unit": null, "note": "quantity not stated; for colour and flavour"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "per packet instructions"}, {"name": "lychee", "name_ms": "laici", "quantity": 1, "unit": "can", "note": "with syrup"}, {"name": "evaporated milk", "name_ms": "susu cair", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": null, "unit": null, "note": "quantity not stated"}]', '["Mix 1 packet jelly powder with water per packet instructions; add roselle syrup for colour and flavour.", "Bring to a boil stirring until fully dissolved; pour into moulds and set for 2 hours at room temperature.", "Once set, cut into cubes.", "Mix evaporated milk and sweetened condensed milk in a bowl; stir in canned lychee with its syrup.", "Add jelly cubes; chill in the fridge and serve cold."]', '["Gaul 1 paket serbuk jeli dengan air ikut arahan pakej; masukkan sirap ros untuk warna dan rasa.", "Didihkan sambil kacau sehingga larut sepenuhnya; tuang ke dalam acuan dan biarkan set 2 jam di suhu bilik.", "Bila dah set, potong jadi kiub.", "Gaul susu cair dan susu pekat manis dalam mangkuk; masukkan laici tin bersama airnya.", "Masukkan kiub jeli; sejukkan dalam peti dan hidang dingin."]', '["halal", "dessert", "jelly", "roselle", "lychee", "cold", "malaysian", "ramadan", "iftar"]', TRUE, TRUE, 'roselle syrup quantity not stated; evaporated milk and sweetened condensed milk quantities not stated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7481511745421315336', 'Strawberry Mint Mocktail', 'Strawberry Cocktail', 'A quick, fresh strawberry and mint mocktail — muddled with lime and honey, topped with ice and sparkling water.', 'Mocktail strawberi dan pudina yang segar — dikisar dengan limau dan madu, ditambah ais dan air berkarbonat.', 'Malaysian', 'Easy', 5, 0, 1, '["strawberry", "mint", "lime", "honey", "ice", "sparkling water"]', '[{"name": "strawberry", "name_ms": "strawberi", "quantity": null, "unit": null, "note": "fresh; a few per glass"}, {"name": "mint", "name_ms": "daun pudina", "quantity": null, "unit": null, "note": "a few leaves"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "squeezed to taste"}, {"name": "honey", "name_ms": "madu", "quantity": null, "unit": null, "note": "a drizzle"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": "to fill glass"}, {"name": "sparkling water", "name_ms": "air berkarbonat", "quantity": null, "unit": null, "note": "or plain water"}]', '["Muddle fresh strawberries and mint leaves in a glass until bruised and fragrant.", "Add a squeeze of lime juice and a drizzle of honey.", "Fill with ice; top with sparkling water (or plain water).", "Stir and serve."]', '["Giling strawberi segar dan daun pudina dalam gelas sehingga hancur dan wangi.", "Perah jus limau dan titiskan madu.", "Isi dengan ais; tuang air berkarbonat (atau air biasa).", "Kacau dan hidang."]', '["halal", "drink", "mocktail", "strawberry", "cold", "malaysian", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'quantities all flexible/to taste; simple assembly drink', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7481557259689004306', 'Crispy Samosa (from Frozen Paratha)', 'Samosa Crispy dari Paratha', 'Easy crispy samosas made using frozen paratha sheets filled with spiced potato and mixed vegetable filling — no pastry-making needed.', 'Samosa crispy yang mudah menggunakan paratha beku diisi dengan inti kentang dan sayur berbumbu — tiada perlu buat pastri.', 'Fusion', 'Easy', 20, 20, 10, '["frozen paratha", "potato", "carrot", "pea", "shallot", "garlic", "curry powder", "salt", "seasoning powder", "cooking oil"]', '[{"name": "frozen paratha", "name_ms": "roti paratha", "quantity": null, "unit": null, "note": "number of sheets not stated"}, {"name": "potato", "name_ms": "kentang", "quantity": 3, "unit": null, "note": "boiled and diced"}, {"name": "carrot", "name_ms": "carrot", "quantity": 1, "unit": null, "note": "diced"}, {"name": "pea", "name_ms": "kacang pis", "quantity": null, "unit": null, "note": "frozen peas"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "diced"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": ""}, {"name": "curry powder", "name_ms": "serbuk kari", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying"}]', '["Boil 3 potatoes until soft; dice. Dice 1 carrot (parboil if needed).", "Sauté diced onion and 3 garlic cloves; add 1 tbsp curry powder.", "Add diced potato and carrot; season with salt and seasoning powder. Add frozen peas; mix well. Cool completely.", "Thaw frozen paratha sheets; cut each sheet into 3 strips.", "Place a spoonful of filling on one end of a strip; fold diagonally into a triangle, sealing with water as you go.", "Deep-fry in hot oil until golden and crispy on both sides.", "Drain and serve with chilli or mint sauce."]', '["Rebus 3 biji kentang sehingga empuk; potong kiub. Potong 1 carrot kiub (rebus sebentar jika perlu).", "Tumis bawang kiub dan 3 ulas bawang putih; masukkan 1 sudu serbuk kari.", "Masukkan kentang dan carrot; tambah garam dan serbuk perasa. Masukkan kacang pis beku; gaul rata. Biarkan sejuk sepenuhnya.", "Cairkan lembaran paratha beku; potong setiap keping menjadi 3 jalur.", "Letakkan sesenduk inti di hujung satu jalur; lipat serong menjadi segitiga, lekatkan dengan air sepanjang jalan.", "Goreng dalam minyak panas sehingga golden crispy di kedua-dua belah.", "Toskan dan hidang dengan sos cili atau sos pudina."]', '["halal", "vegetarian", "snack", "samosa", "potato", "malaysian", "raya", "ramadan"]', TRUE, TRUE, 'number of frozen paratha sheets not stated; potato quantity implied by filling yield', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7481911296225545479', 'Cheesy Garlic Bread (From Scratch)', 'Cheesy Garlic Bread dari Scratch', 'Soft, fluffy rolls stuffed with mozzarella cheese and topped with a fragrant garlic-ghee spread — made completely from scratch at home.', 'Roti gulung yang sangat fluffy diisi dengan mozzarella cheese dan disapu dengan mentega bawang putih yang wangi — dibuat dari awal di rumah.', 'Western', 'Medium', 100, 20, 12, '["fresh milk", "water", "sugar", "yeast", "egg", "bread flour", "salt", "ghee", "mozzarella cheese", "parsley"]', '[{"name": "fresh milk", "name_ms": "fresh milk", "quantity": 1, "unit": "cup", "note": "for dough"}, {"name": "water", "name_ms": "air", "quantity": 0.5, "unit": "cup", "note": "for dough"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "1/3 cup for dough"}, {"name": "yeast", "name_ms": "yis", "quantity": 1, "unit": null, "note": "1 packet"}, {"name": "egg", "name_ms": "telur", "quantity": 3, "unit": null, "note": "2 in dough; 1 for egg wash"}, {"name": "bread flour", "name_ms": "tepung roti", "quantity": 4.5, "unit": "cup", "note": "plus 3-4 extra tbsp if dough is too wet"}, {"name": "salt", "name_ms": "garam", "quantity": 1.5, "unit": "tsp", "note": "in dough; pinch for garlic spread"}, {"name": "ghee", "name_ms": "minyak sapi", "quantity": 4, "unit": "tbsp", "note": "2 tbsp for dough; 2 tbsp for garlic spread; brand QBB"}, {"name": "mozzarella cheese", "name_ms": "mozzarella cheese", "quantity": null, "unit": null, "note": "quantity per roll not stated"}, {"name": "parsley", "name_ms": "daun parsli", "quantity": null, "unit": null, "note": "optional; for garlic spread; fresh or dried"}]', '["Warm 1 cup fresh milk with 0.5 cup water for 30 seconds (just warm, not hot). Stir in 1/3 cup sugar and 1 packet yeast; rest 5 minutes until foamy.", "Add 2 eggs. Then add 4.5 cup bread flour and 1.5 tsp salt; mix to a rough dough.", "Melt 2 tbsp ghee and add to the dough; knead until smooth and no longer sticky. Add 3-4 tbsp extra flour if too wet (egg size varies).", "Cover and let rise for 1 hour until doubled.", "Knock back; divide into portions. Flatten each portion, place mozzarella cheese in the centre, gather the edges and roll into a smooth ball.", "Arrange in a greased baking tin; let rise for another 30 minutes until puffy.", "Brush tops with beaten egg for a golden finish.", "Bake at 190°C for 18–20 minutes until golden brown.", "[Garlic spread] Melt 2 tbsp ghee with 10 minced garlic cloves, a pinch of salt and chopped parsley (optional). Brush over the hot rolls immediately after baking."]', '["Panaskan 1 cawan susu segar dengan setengah cawan air selama 30 saat (suam sahaja). Gaul dengan 1/3 cawan gula dan 1 paket yis; rehat 5 minit sehingga berbuih.", "Masukkan 2 biji telur. Kemudian masukkan 4 cawan setengah tepung roti dan 1 sudu kecil setengah garam; gaul menjadi adunan kasar.", "Cairkan 2 sudu minyak sapi dan masukkan ke dalam adunan; uli sehingga licin dan tidak melekat. Tambah 3-4 sudu tepung roti jika terlalu basah (saiz telur berbeza).", "Tutup dan biarkan naik 1 jam sehingga dua kali ganda.", "Hembus keluar udara; bahagi kepada bahagian-bahagian. Lenyekkan setiap bahagian, letakkan mozzarella di tengah, kumpulkan tepi dan gulung menjadi bebola licin.", "Susun dalam loyang yang sudah disalutkan; biarkan naik 30 minit lagi sehingga gebu.", "Sapu atas roti dengan telur yang telah dipukul.", "Bakar pada suhu 190°C selama 18-20 minit sehingga golden brown.", "[Sapu bawang putih] Cairkan 2 sudu minyak sapi dengan 10 ulas bawang putih yang dihacam, sedikit garam dan daun parsli cincang (pilihan). Sapu di atas roti yang baru keluar dari oven."]', '["halal", "bread", "baked", "garlic", "cheese", "western", "ramadan", "moreh"]', TRUE, TRUE, 'mozzarella cheese quantity per roll not stated; may need extra bread flour depending on egg size; bake time is 18-20 min', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7482282461641100562', 'Curry Noodle Soup (Mee Kari)', 'Mee Kari', 'Rich, coconut-based curry noodle soup with chicken, tofu puffs and fish cake — a classic Malaysian street food.', 'Sup mi kari yang kaya berasaskan santan dengan ayam, tauhu goreng dan fishcake — makanan jalanan Malaysia yang klasik.', 'Malaysian', 'Medium', 20, 30, 4, '["cooking oil", "shallot", "garlic", "ginger", "curry powder", "chilli powder", "chicken", "water", "coconut milk", "tofu puffs", "fish cake", "fish ball", "salt", "sugar", "seasoning powder", "yellow noodles", "bean sprouts", "spring onion"]', '[{"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for sautéing"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": null, "unit": null, "note": "sliced"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": ""}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob"}, {"name": "curry powder", "name_ms": "serbuk kari", "quantity": 3, "unit": "tbsp", "note": "brand Adabi or any"}, {"name": "chilli powder", "name_ms": "serbuk cili", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": ""}, {"name": "coconut milk", "name_ms": "santan", "quantity": 1, "unit": null, "note": "1 box"}, {"name": "tofu puffs", "name_ms": "tauhu goreng", "quantity": null, "unit": null, "note": ""}, {"name": "fish cake", "name_ms": "fishcake", "quantity": null, "unit": null, "note": "sliced"}, {"name": "fish ball", "name_ms": "fishball", "quantity": null, "unit": null, "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "yellow noodles", "name_ms": "mi kuning", "quantity": null, "unit": null, "note": "blanched"}, {"name": "bean sprouts", "name_ms": "taugeh", "quantity": null, "unit": null, "note": "for serving"}, {"name": "spring onion", "name_ms": "daun bawang", "quantity": null, "unit": null, "note": "for serving"}]', '["Sauté sliced onion, 5 garlic cloves and a knob of ginger until fragrant.", "Add 3 tbsp curry powder and 1 tbsp chilli powder; fry briefly until fragrant.", "Add chicken pieces; coat in the spice paste.", "Add water; bring to a boil.", "Add 1 box coconut milk; season with salt, sugar and seasoning powder.", "Add tofu puffs, sliced fish cake and fish balls; simmer until chicken is cooked.", "Blanch yellow noodles; place in bowls.", "Ladle hot curry soup over the noodles; top with bean sprouts and spring onion."]', '["Tumis hirisan bawang, 5 ulas bawang putih dan seketul halia sehingga wangi.", "Masukkan 3 sudu serbuk kari dan 1 sudu serbuk cili; goreng sebentar sehingga wangi.", "Masukkan kepingan ayam; gaul rata dengan pes rempah.", "Masukkan air; didihkan.", "Masukkan 1 kotak santan; tambah garam, gula dan serbuk perasa.", "Masukkan tauhu goreng, hirisan fishcake dan fishball; reneh sehingga ayam masak.", "Celur mi kuning; susun dalam mangkuk.", "Tuang sup kari panas di atas mi; tabur taugeh dan daun bawang."]', '["halal", "noodles", "curry", "chicken", "coconut milk", "malaysian", "ramadan"]', TRUE, TRUE, 'chicken quantity not stated; spice paste powder brand ''Adabi'' or any brand; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7483041417590213895', 'Fritters (Cucur) with Thai Dipping Sauce', 'Colek Malas (Cucur dengan Sos Thai)', 'Simple yeasted vegetable fritters made with 1 kg flour and 1 L water, fried until golden, served with a tangy-sweet Thai-style dipping sauce.', 'Cucur ragi yang mudah dan sedap, dibuat dengan 1 kg tepung dan 1 liter air, digoreng garing dan dicicah dengan sos Thai yang pedas-masam-manis.', 'Malaysian', 'Easy', 70, 20, 10, '["all-purpose flour", "yeast", "sugar", "salt", "seasoning powder", "onion", "carrot", "water spinach", "water", "cooking oil", "chilli sauce", "bird''s eye chilli", "garlic", "palm sugar", "soy sauce", "fish sauce", "cornstarch", "lime", "sesame seeds"]', '[{"name": "all-purpose flour", "name_ms": "tepung gandum", "quantity": 1000, "unit": "g", "note": "1 kg"}, {"name": "yeast", "name_ms": "yis", "quantity": 1, "unit": null, "note": "1 packet"}, {"name": "sugar", "name_ms": "gula", "quantity": 2, "unit": "tbsp", "note": "for batter"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "onion", "name_ms": "bawang holland", "quantity": null, "unit": null, "note": "grated; quantity flexible"}, {"name": "carrot", "name_ms": "carrot", "quantity": null, "unit": null, "note": "grated; quantity flexible"}, {"name": "water spinach", "name_ms": "kangkung", "quantity": null, "unit": null, "note": "roughly chopped; bean sprouts can be added too"}, {"name": "water", "name_ms": "air", "quantity": 1000, "unit": "ml", "note": "1 L for batter (ratio: 1 kg flour : 1 L water)"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "deep frying"}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": 1, "unit": "cup", "note": "for dipping sauce; use the brand with a rooster logo"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 3, "unit": null, "note": "for sauce"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 2, "unit": "clove", "note": "for sauce"}, {"name": "palm sugar", "name_ms": "gula melaka", "quantity": 2, "unit": "tbsp", "note": "for sauce"}, {"name": "soy sauce", "name_ms": "kicap", "quantity": 1, "unit": "tbsp", "note": "for sauce"}, {"name": "fish sauce", "name_ms": "sos ikan", "quantity": 1, "unit": "tbsp", "note": "for sauce"}, {"name": "cornstarch", "name_ms": "tepung jagung", "quantity": null, "unit": null, "note": "slurry to thicken sauce"}, {"name": "lime", "name_ms": "limau nipis", "quantity": 0.5, "unit": null, "note": "juice; for sauce"}, {"name": "sesame seeds", "name_ms": "bijan", "quantity": null, "unit": null, "note": "optional garnish in sauce"}]', '["Combine 1 kg all-purpose flour, 1 packet yeast, 2 tbsp sugar, salt and seasoning powder to taste in a large bowl.", "Grate the sweet onion and carrot; roughly chop the water spinach. Add to the flour mixture.", "Add 1 L water and mix until a thick batter forms. Cover and rest for 1 hour until the batter rises.", "Fry spoonfuls in hot oil until deep golden and cooked through, turning once. Drain.", "[Sauce] Combine 1 cup Thai sweet chilli sauce, 3 bird''s eye chillies, 2 garlic cloves, 0.5 cup water, 2 tbsp palm sugar, 1 tbsp soy sauce, 1 tbsp fish sauce, salt and seasoning powder in a pot; bring to a boil.", "Stir in a cornstarch slurry to thicken, remove from heat, then squeeze in juice of 0.5 lime.", "Optionally sprinkle sesame seeds into the sauce before serving."]', '["Campurkan 1 kg tepung gandum, 1 paket yis, 2 sudu besar gula, garam dan serbuk perasa secukupnya dalam mangkuk besar.", "Sagat bawang Holland dan carrot; potong kasar kangkung. Masukkan ke dalam tepung.", "Tuang 1 liter air dan gaul sehingga jadi adunan pekat. Tutup dan rehatkan selama 1 jam sehingga adunan naik.", "Goreng sesudu adunan dalam minyak panas sehingga keemasan gelap dan masak, balikkan sekali. Toskan.", "[Sos] Campurkan 1 cawan sos Thai, 3 cili padi, 2 ulas bawang putih, setengah cawan air, 2 sudu besar gula Melaka, 1 sudu kicap, 1 sudu sos ikan, garam dan serbuk perasa dalam periuk; masak sehingga mendidih.", "Masukkan air tepung jagung untuk memekatkan, padamkan api, kemudian perah jus separuh biji limau nipis.", "Tabur bijan dalam sos sebelum dihidang (pilihan)."]', '["halal", "snack", "fritters", "fried", "vegetarian", "malaysian", "ramadan", "moreh"]', TRUE, FALSE, 'sesame seeds optional; vegetables (sweet onion, carrot, water spinach) quantities flexible; times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7483768833728154888', 'Chocolate Beignets', 'Chocolate Beignets', 'Light, crispy yeasted dough pockets fried until puffed and golden — filled with hazelnut chocolate spread and dusted with icing sugar.', 'Adunan ragi yang ringan dan crispy digoreng sehingga kembang dan keemasan — diisi dengan coklat hazelnut dan ditaburi gula serbuk.', 'Western', 'Easy', 80, 20, 12, '["water", "yeast", "evaporated milk", "sugar", "butter", "vanilla essence", "egg", "all-purpose flour", "salt", "cooking oil", "chocolate hazelnut spread", "icing sugar"]', '[{"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "3/4 cup warm water"}, {"name": "yeast", "name_ms": "yis", "quantity": 1, "unit": null, "note": "1 packet"}, {"name": "evaporated milk", "name_ms": "krimer sejat", "quantity": 0.5, "unit": "cup", "note": ""}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "1/3 cup"}, {"name": "butter", "name_ms": "butter", "quantity": 3, "unit": "tbsp", "note": "melted"}, {"name": "vanilla essence", "name_ms": "esen vanila", "quantity": 1, "unit": "tsp", "note": ""}, {"name": "egg", "name_ms": "telur", "quantity": 1, "unit": null, "note": ""}, {"name": "all-purpose flour", "name_ms": "tepung gandum", "quantity": 4, "unit": "cup", "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": 0.5, "unit": "tsp", "note": ""}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "deep frying"}, {"name": "chocolate hazelnut spread", "name_ms": "coklat hazelnut", "quantity": null, "unit": null, "note": "for filling; quantity to preference"}, {"name": "icing sugar", "name_ms": "gula serbuk", "quantity": null, "unit": null, "note": "for dusting"}]', '["Combine 3/4 cup warm water and 1 packet yeast; wait 5 minutes.", "Add 0.5 cup evaporated milk, 1/3 cup sugar, 3 tbsp melted butter, 1 tsp vanilla essence, 1 egg and 0.5 tsp salt; mix well.", "Add 4 cup all-purpose flour and knead until smooth and non-sticky. Cover and rest for 1 hour.", "After rising, lightly knock back; dust a board with flour and roll the dough thin.", "Cut into squares; re-roll any scraps.", "Deep-fry in hot oil in batches until puffed and golden. Drain.", "Optionally fill with chocolate hazelnut spread (press into the dough square before frying, or pipe in after).", "Dust generously with icing sugar and serve warm."]', '["Campurkan 3/4 cawan air suam dan 1 paket yis; tunggu 5 minit.", "Masukkan setengah cawan susu sejat, 1/3 cawan gula, 3 sudu butter cair, 1 sudu kecil esen vanila, 1 biji telur dan setengah sudu kecil garam; gaul sebati.", "Masukkan 4 cawan tepung gandum dan uli sehingga licin dan tidak melekat. Tutup dan rehat 1 jam.", "Lepas kembang, lenyek keluar udara; tabur tepung di papan dan lenyekkan doh sehingga nipis.", "Potong jadi petak-petak; gulung balik lebihan.", "Goreng dalam minyak panas sehingga kembang dan keemasan. Toskan.", "Boleh isi dengan coklat hazelnut (letakkan dalam petak sebelum goreng, atau paipkan masuk selepas).", "Taburi banyak gula serbuk dan hidang panas."]', '["halal", "dessert", "fried", "dough", "chocolate", "western", "ramadan"]', TRUE, FALSE, 'hazelnut spread filling quantity flexible; prep time includes 1 hour rise; times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7484150259581488392', 'Fried Chicken in Coconut Milk Gravy (Masak Lemak Cili Api)', 'Ayam Goreng Masak Lemak Cili Api', 'Golden fried chicken pieces simmered in a rich, turmeric-yellow coconut milk gravy spiked with bird''s eye chilli.', 'Ayam goreng yang dimasak dalam kuah lemak kunyit bersama cili padi, menghasilkan hidangan yang creamy, pedas dan sangat sedap dimakan dengan nasi putih.', 'Malaysian', 'Easy', 15, 25, 4, '["chicken", "turmeric powder", "salt", "shallot", "bird''s eye chilli", "garlic", "fresh turmeric", "water", "coconut milk", "turmeric leaf", "seasoning powder"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated; whole chicken or pieces"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": null, "unit": null, "note": "to coat chicken, and extra if blended colour insufficient"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste (chicken coating and gravy)"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "chopped or pounded"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 8, "unit": null, "note": "chopped or pounded"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": "chopped or pounded"}, {"name": "fresh turmeric", "name_ms": "kunyit hidup", "quantity": 1, "unit": null, "note": "1 knob; blended with water"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "for blending fresh turmeric"}, {"name": "coconut milk", "name_ms": "santan", "quantity": 1, "unit": null, "note": "1 small box"}, {"name": "turmeric leaf", "name_ms": "daun kunyit", "quantity": null, "unit": null, "note": "sliced; added at end"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}]', '["Toss chicken pieces with salt and turmeric powder until evenly coated; fry in hot oil until golden and crispy, then drain and set aside.", "Chop (or pound) 1 onion, 8 bird''s eye chillies and 3 cloves garlic.", "Blend 1 knob of fresh turmeric with a little water until smooth; add extra turmeric powder if colour is insufficient.", "Sauté the chopped aromatics briefly, then add the fresh turmeric blend.", "Add the fried chicken and 1 small box of coconut milk; stir to combine.", "Season with salt and seasoning powder; simmer until the gravy thickens slightly.", "Stir in sliced turmeric leaf and cook for another minute before serving."]', '["Gaul ayam dengan garam dan serbuk kunyit sehingga rata; goreng dalam minyak panas sehingga garing keemasan, kemudian angkat dan ketepikan.", "Chop atau tumbuk 1 biji bawang merah, 8 cili padi dan 3 ulas bawang putih.", "Blend 1 ketul kunyit hidup dengan sedikit air sehingga lumat; tambah serbuk kunyit jika warna kurang.", "Tumis bahan-bahan yang dah dihancurkan sebentar, kemudian masukkan blend kunyit hidup.", "Masukkan ayam goreng dan 1 kotak kecil santan; kacau sebati.", "Tambah garam dan serbuk perasa; masak sehingga kuah pekat sikit.", "Masukkan hirisan daun kunyit dan masak seminit lagi sebelum dihidang."]', '["halal", "chicken", "coconut milk", "spicy", "malaysian", "ramadan"]', TRUE, TRUE, 'chicken quantity not stated; fresh turmeric blended with water then no volume given; prep/cook/servings estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7484884162332069128', 'Marshmallow Nougat', 'Marshmallow Nougat', 'A chewy, festive nougat made by melting marshmallows with butter and milk powder, then folding in biscuits and mixed nuts — a modern Raya confection.', 'Nougat yang chewy dan moden dibuat dengan mencairkan marshmallow bersama butter dan susu tepung, kemudian dilipat bersama biskut dan kacang campuran — kuih raya moden.', 'Fusion', 'Easy', 120, 15, 20, '["butter", "marshmallow", "milk powder", "salt", "biscuit", "cashew nuts", "almond", "raisin", "dates"]', '[{"name": "butter", "name_ms": "butter", "quantity": 3, "unit": "tbsp", "note": ""}, {"name": "marshmallow", "name_ms": "marshmallow", "quantity": 500, "unit": "g", "note": "use a non-stick wok"}, {"name": "milk powder", "name_ms": "susu tepung", "quantity": 0.5, "unit": "cup", "note": "also for dusting"}, {"name": "salt", "name_ms": "garam", "quantity": 0.5, "unit": "tsp", "note": ""}, {"name": "biscuit", "name_ms": "biskut", "quantity": null, "unit": null, "note": "Mary biscuits used; any sturdy biscuit"}, {"name": "cashew nuts", "name_ms": "kacang gajus", "quantity": null, "unit": null, "note": "quantity flexible"}, {"name": "almond", "name_ms": "badam", "quantity": null, "unit": null, "note": "quantity flexible"}, {"name": "raisin", "name_ms": "kismis", "quantity": null, "unit": null, "note": "kismis; quantity flexible"}, {"name": "dates", "name_ms": "kurma", "quantity": null, "unit": null, "note": "optional; leftover Ramadan dates work well"}]', '["Melt 3 tbsp butter in a non-stick wok over the lowest heat.", "Add 500 g marshmallows; stir slowly and patiently until completely melted.", "Stir in 0.5 cup milk powder and 0.5 tsp salt until combined.", "Add biscuits (broken), cashews, almonds, raisins and/or dates gradually — fold in gently so the mixture doesn''t become too firm.", "Line a tray with baking paper dusted with milk powder; pour in the mixture.", "Press down firmly using your hands (and a top sheet of baking paper); compact as densely as possible.", "Leave at room temperature for several hours until fully set.", "Dust the top with milk powder; cut into pieces to serve."]', '["Cairkan 3 sudu besar butter dalam kuali non-stick atas api paling kecil.", "Masukkan 500g marshmallow; kacau perlahan-lahan dengan sabar sehingga cair sepenuhnya.", "Gaul masuk setengah cawan susu tepung dan setengah sudu kecil garam sehingga sebati.", "Masukkan biskut (dipatah-patah), kacang gajus, badam, kismis dan/atau kurma secara beransur — lipat perlahan supaya adunan tidak terlalu keras.", "Alaskan dulang dengan kertas pembakar yang ditaburi susu tepung; tuangkan adunan.", "Tekan padat dengan tangan (boleh guna kertas pembakar di atas sebagai lapisan); padatkan sebanyak mungkin.", "Biarkan di suhu bilik beberapa jam sehingga betul-betul keras.", "Taburi susu tepung di atas; potong kepada kepingan untuk dihidang."]', '["halal", "dessert", "nougat", "marshmallow", "raya", "easy", "no-bake"]', TRUE, FALSE, 'toppings (cashews, almonds, raisins, dates) quantities are flexible; prep time includes cooling; times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7485245974458289426', 'Whole Chicken Rendang', 'Rendang Satu Ekor Ayam', 'A classic Malay dry rendang made with a whole chicken, slow-cooked in spiced coconut milk with lemongrass and galangal until the sauce reduces and the chicken is tender.', 'Rendang ayam tradisional Melayu menggunakan satu ekor ayam yang dimasak perlahan dalam santan berempah sehingga kuah menjadi pekat dan kering.', 'Malaysian', 'Medium', 20, 60, 6, '["shallot", "lemongrass", "garlic", "ginger", "galangal", "fresh turmeric", "water", "cooking oil", "blended chilli", "chicken", "coconut milk", "kaffir lime leaf", "turmeric leaf", "toasted desiccated coconut", "palm sugar", "tamarind paste", "salt", "seasoning powder"]', '[{"name": "shallot", "name_ms": "bawang merah", "quantity": 4, "unit": null, "note": ""}, {"name": "lemongrass", "name_ms": "serai", "quantity": 4, "unit": null, "note": "stalks; blended"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 4, "unit": "clove", "note": "blended"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 thumb-sized knob; blended"}, {"name": "galangal", "name_ms": "lengkuas", "quantity": null, "unit": null, "note": "1 thumb-sized knob; blended"}, {"name": "fresh turmeric", "name_ms": "kunyit hidup", "quantity": null, "unit": null, "note": "1 small knob; blended"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "for blending"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for sautéing"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 2.5, "unit": "tbsp", "note": "2–3 tbsp; increase for more heat"}, {"name": "chicken", "name_ms": "ayam", "quantity": 1, "unit": null, "note": "1 whole chicken, cut into pieces"}, {"name": "coconut milk", "name_ms": "santan", "quantity": 2, "unit": null, "note": "2 small boxes"}, {"name": "kaffir lime leaf", "name_ms": "daun limau purut", "quantity": 4, "unit": null, "note": ""}, {"name": "turmeric leaf", "name_ms": "daun kunyit", "quantity": 1, "unit": null, "note": "1 large leaf; plus more sliced for garnish"}, {"name": "toasted desiccated coconut", "name_ms": "kerisik", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "palm sugar", "name_ms": "gula melaka", "quantity": null, "unit": null, "note": "1 small block"}, {"name": "tamarind paste", "name_ms": "pes asam jawa", "quantity": null, "unit": null, "note": "to taste; quantity not stated"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste; be careful not to over-salt"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}]', '["Blend 4 onions, 4 lemongrass stalks, 4 garlic cloves, a knob each of ginger and galangal, and a small knob of fresh turmeric with a little water until smooth.", "Heat oil in a wok; sauté the blended paste until fragrant.", "Add 2–3 tbsp blended chilli; cook until the oil separates.", "Add 1 whole chicken (cut into pieces) and stir to coat.", "Add 2 small boxes of coconut milk, 4 kaffir lime leaves and 1 large turmeric leaf; cook until the chicken is tender.", "Add 2 tbsp toasted desiccated coconut, 1 small block of palm sugar, tamarind paste (to taste), salt and seasoning powder.", "Continue cooking, stirring occasionally, until the gravy is very thick and almost dry.", "Finish with sliced turmeric leaf before serving."]', '["Blend 4 biji bawang merah, 4 batang serai, 4 ulas bawang putih, seketul halia dan lengkuas, serta seketul kecil kunyit hidup dengan sedikit air sehingga lumat.", "Panaskan minyak dalam kuali; tumis blend sehingga wangi.", "Masukkan 2-3 sudu cili kisar; masak sehingga pecah minyak.", "Masukkan 1 ekor ayam (potong) dan kacau sehingga rata.", "Masukkan 2 kotak kecil santan, 4 helai daun limau purut dan 1 helai besar daun kunyit; masak sehingga ayam empuk.", "Masukkan 2 sudu kerisik, 1 ketul kecil gula Melaka, pes asam jawa secukupnya, garam dan serbuk perasa.", "Sambung masak sambil dikacau sesekali sehingga kuah sangat pekat dan hampir kering.", "Hias dengan hirisan daun kunyit sebelum dihidang."]', '["halal", "chicken", "rendang", "coconut milk", "malaysian", "hari raya", "raya"]', TRUE, TRUE, 'tamarind paste quantity not stated (''letakkan pes asam jawa''); servings estimated for 1 whole chicken', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7485999289957616914', 'Siamese Laksa (Laksa Siam)', 'Laksa Siam', 'A rich, creamy Siamese-style laksa broth made from poached fish, coconut milk and a fragrant pounded spice paste — served with rice vermicelli, cockles, boiled egg and fresh herbs.', 'Kuah laksa Siam yang kaya dan berkrim daripada ikan rebus, santan dan pes rempah yang ditumbuk — dihidang dengan bihun, kerang, telur rebus dan ulam-ulam segar.', 'Fusion', 'Hard', 40, 40, 5, '["Indian mackerel", "water", "lemongrass", "galangal", "fresh turmeric", "shallot", "garlic", "dried chilli", "shrimp paste", "blended chilli", "coconut milk", "tamarind paste", "salt", "sugar", "seasoning powder", "rice vermicelli", "cockles", "egg", "garlic chives", "bean sprouts", "torch ginger bud", "cucumber", "Vietnamese mint"]', '[{"name": "Indian mackerel", "name_ms": "ikan kembung", "quantity": null, "unit": null, "note": "2-3 fish for broth; quantity not stated exactly"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "for poaching"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 4, "unit": null, "note": "2 bruised for poaching; 2 for paste"}, {"name": "galangal", "name_ms": "lengkuas", "quantity": null, "unit": null, "note": "1 knob for poaching; 1 knob for paste"}, {"name": "fresh turmeric", "name_ms": "kunyit hidup", "quantity": null, "unit": null, "note": "1 knob for poaching; 1 knob for paste"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 2, "unit": null, "note": "for paste"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": "for paste"}, {"name": "dried chilli", "name_ms": "cili kering", "quantity": 10, "unit": null, "note": "soaked in hot water; for paste"}, {"name": "shrimp paste", "name_ms": "belacan", "quantity": 1, "unit": null, "note": "1 block; roasted; for paste"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 3, "unit": "tbsp", "note": ""}, {"name": "coconut milk", "name_ms": "santan", "quantity": 1, "unit": null, "note": "1 small box"}, {"name": "tamarind paste", "name_ms": "pes asam jawa", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "rice vermicelli", "name_ms": "bihun", "quantity": null, "unit": null, "note": "blanched; for serving"}, {"name": "cockles", "name_ms": "kerang", "quantity": null, "unit": null, "note": "for serving"}, {"name": "egg", "name_ms": "telur", "quantity": null, "unit": null, "note": "boiled 7 min; for serving"}, {"name": "garlic chives", "name_ms": "kucai", "quantity": null, "unit": null, "note": "for serving"}, {"name": "bean sprouts", "name_ms": "taugeh", "quantity": null, "unit": null, "note": "for serving"}, {"name": "torch ginger bud", "name_ms": "bunga kantan", "quantity": null, "unit": null, "note": "sliced; for serving"}, {"name": "cucumber", "name_ms": "timun", "quantity": null, "unit": null, "note": "julienned; for serving"}, {"name": "Vietnamese mint", "name_ms": "daun kesum", "quantity": null, "unit": null, "note": "for serving"}]', '["Poach 2–3 mackerel in water with bruised lemongrass, galangal and a knob of fresh turmeric; once cooked, remove flesh and discard bones. Reserve the broth.", "Pound or blend 2 lemongrass stalks, 1 knob galangal, 1 knob fresh turmeric, 2 onions, 5 garlic cloves, 10 soaked dried chillies and 1 roasted shrimp paste block into a fine paste.", "Fry the paste in oil until fragrant and oil separates; add 3 tbsp blended chilli.", "Add the reserved fish broth; stir in the shredded fish flesh.", "Add 1 small box coconut milk and 1 tbsp tamarind paste; season with salt, sugar and seasoning powder.", "Simmer for 10–15 minutes until the broth is rich and fragrant.", "Blanch rice vermicelli; boil eggs (7 minutes for medium); open cockles and blanch briefly.", "Serve broth over rice vermicelli with cockles, halved egg, garlic chives, bean sprouts, sliced torch ginger bud, cucumber julienne and Vietnamese mint."]', '["Rebus 2-3 ekor ikan kembung dalam air bersama serai diketuk, lengkuas dan seketul kunyit hidup; bila masak, ambil isi ikan dan buang tulang. Simpan air rebusan.", "Tumbuk atau blend 2 batang serai, 1 ketul lengkuas, 1 ketul kunyit hidup, 2 biji bawang, 5 ulas bawang putih, 10 biji cili kering yang direndam dan 1 ketul belacan bakar sehingga lumat.", "Goreng pes dalam minyak sehingga wangi dan pecah minyak; masukkan 3 sudu cili kisar.", "Masukkan air rebusan ikan; masukkan isi ikan yang sudah disuwir.", "Masukkan 1 kotak kecil santan dan 1 sudu pes asam jawa; tambah garam, gula dan serbuk perasa.", "Reneh 10-15 minit sehingga kuah kaya dan wangi.", "Celur bihun; rebus telur (7 minit untuk setengah masak); buka kerang dan celur sebentar.", "Hidang kuah di atas bihun bersama kerang, telur belah dua, kucai, taugeh, hirisan bunga kantan, julien timun dan daun kesum."]', '["halal", "noodles", "laksa", "fish", "coconut milk", "thai", "malaysian", "ramadan"]', TRUE, TRUE, 'some garnish quantities (kucai, taugeh, torch ginger bud, laksa noodles) not explicitly stated; laksa paste qty flexible; fish quantity for poaching not stated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7486337073192946952', 'Tomato Rice with Festive Red Chicken (Nasi Tomato & Ayam Masak Merah)', 'Nasi Tomato dan Ayam Masak Merah Ala Kenduri', 'A festive open-house spread of fragrant tomato rice paired with rich, slow-cooked red chicken in a tangy tomato-based sauce.', 'Hidangan kenduri berupa nasi tomato yang wangi bersama ayam masak merah yang kaya dengan rasa tomato masam-manis yang sedap.', 'Malaysian', 'Medium', 30, 45, 8, '["ghee", "whole spices (cinnamon, cloves, star anise, cardamom)", "shallot", "garlic", "chicken stock cube", "ginger", "tomato puree", "pandan leaf", "sugar", "salt", "evaporated milk", "basmati rice", "water", "chicken", "turmeric powder", "cooking oil", "onion", "lemongrass", "blended chilli", "oyster sauce", "chilli sauce", "seasoning powder", "tomato"]', '[{"name": "ghee", "name_ms": "minyak sapi", "quantity": 3, "unit": "tbsp", "note": "for nasi tomato"}, {"name": "whole spices (cinnamon, cloves, star anise, cardamom)", "name_ms": "rempah 4 sekawan", "quantity": null, "unit": null, "note": "standard mixed whole spices; nasi tomato"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 7, "unit": null, "note": "3 for nasi tomato; 4 blended for ayam"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 11, "unit": "clove", "note": "3 for nasi tomato; 8 blended for ayam"}, {"name": "chicken stock cube", "name_ms": "kiub pati ayam", "quantity": 1, "unit": null, "note": "for nasi tomato"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; nasi tomato"}, {"name": "tomato puree", "name_ms": "tomato puree", "quantity": null, "unit": null, "note": "4 tbsp for nasi tomato; 1 small can for ayam"}, {"name": "pandan leaf", "name_ms": "daun pandan", "quantity": 2, "unit": null, "note": "1-2 for nasi tomato; 1 for ayam sauce"}, {"name": "sugar", "name_ms": "gula", "quantity": 1, "unit": "tbsp", "note": "for nasi tomato; a little more for ayam sauce"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "1/3 tbsp for nasi tomato; to taste for ayam"}, {"name": "evaporated milk", "name_ms": "susu cair", "quantity": null, "unit": null, "note": "0.5 cup for nasi tomato; 1/3 cup for ayam sauce"}, {"name": "basmati rice", "name_ms": "beras basmati", "quantity": 4, "unit": "cup", "note": "soaked 30 min; use 5 cup water"}, {"name": "water", "name_ms": "air", "quantity": 5, "unit": "cup", "note": "for cooking nasi tomato"}, {"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": null, "unit": null, "note": "to coat chicken"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying chicken"}, {"name": "onion", "name_ms": "bawang holland", "quantity": 2, "unit": null, "note": "blended for ayam sauce; some sliced for garnish"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 1, "unit": null, "note": "1 stalk; ayam sauce"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": null, "unit": null, "note": "adjust to taste for ayam sauce"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 2, "unit": "tbsp", "note": "ayam sauce"}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": 2, "unit": "tbsp", "note": "ayam sauce"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "tomato", "name_ms": "tomato", "quantity": null, "unit": null, "note": "sliced; garnish for ayam"}]', '["[Nasi Tomato] Heat 3 tbsp ghee; add whole spices, 3 onions, 3 garlic cloves and fry briefly. Add 1 chicken stock cube, a knob of ginger, 4 tbsp tomato puree, 1–2 pandan leaves, 1 tbsp sugar, 1/3 tbsp salt and 0.5 cup evaporated milk; stir.", "Add 4 cup basmati rice (soaked 30 min) and 5 cup water; cook as normal rice.", "[Ayam Masak Merah] Coat chicken with salt and turmeric; fry in oil until golden brown.", "Blend 2 sweet onions, 4 onions and 8 garlic cloves with water; sauté with 1 lemongrass stalk and 1 pandan leaf until fragrant.", "Add blended chilli (adjust to taste); cook until oil separates.", "Add 1 small can tomato puree, 2 tbsp oyster sauce, 2 tbsp chilli sauce; season with salt, seasoning powder and a little sugar.", "Return the fried chicken to the pot; add sliced sweet onion, sliced chilli and tomato.", "Pour in 1/3 cup evaporated milk for a creamier gravy; simmer until the chicken is cooked through."]', '["[Nasi Tomato] Panaskan 3 sudu besar minyak sapi; masukkan rempah 4 sekawan, 3 biji bawang merah, 3 ulas bawang putih dan goreng sebentar. Masukkan 1 kiub pati ayam, seketul halia, 4 sudu tomato puree, 1–2 helai daun pandan, 1 sudu gula, 1/3 sudu garam dan setengah cawan susu cair; kacau.", "Masukkan 4 cawan beras basmati (direndam 30 min) dan 5 cawan air; masak seperti biasa.", "[Ayam Masak Merah] Gaul ayam dengan garam dan kunyit; goreng dalam minyak sehingga golden brown.", "Blend 2 biji bawang Holland, 4 biji bawang merah dan 8 ulas bawang putih dengan air; tumis bersama 1 batang serai dan 1 helai daun pandan sehingga wangi.", "Masukkan cili kisar (ikut selera); masak sehingga pecah minyak.", "Masukkan 1 tin kecil tomato puree, 2 sudu sos tiram, 2 sudu sos cili; tambah garam, serbuk perasa dan sedikit gula.", "Masukkan balik ayam goreng; tambah hirisan bawang Holland, cili dan tomato.", "Tuang 1/3 cawan susu cair untuk kuah lebih creamy; masak sehingga ayam masak sepenuhnya."]', '["halal", "chicken", "rice", "tomato", "festive", "malaysian", "raya", "open house"]', TRUE, TRUE, 'chicken quantity not stated; multi-component recipe (nasi tomato + ayam masak merah); some whole spice quantities (rempah 4 sekawan) not quantified', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7516790452549438727', 'Spiced Braised Beef (Daging Belenggas)', 'Daging Belenggas', 'Tender braised beef cooked in a sweet-savoury sauce of caramel soy, oyster sauce, and aromatics until the liquid reduces.', 'Daging yang direbus sehingga empuk kemudian dimasak dengan kicap karamel, sos tiram dan rempah sehingga kuah meresap dan pekat.', 'Malaysian', 'Easy', 10, 45, 4, '["beef", "turmeric powder", "cooking oil", "garlic", "ginger", "caramel soy sauce", "sweet soy sauce", "chilli sauce", "tomato sauce", "oyster sauce", "salt", "seasoning powder", "water", "onion", "bird''s eye chilli", "long beans"]', '[{"name": "beef", "name_ms": "daging", "quantity": null, "unit": null, "note": "quantity not stated; leftover from Hari Raya Haji"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": 1, "unit": "tsp", "note": ""}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "a little to brown the beef"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 7, "unit": "clove", "note": "blended with ginger"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; blended with garlic"}, {"name": "caramel soy sauce", "name_ms": "kicap karamel", "quantity": null, "unit": null, "note": "to taste; omit and use extra sweet soy sauce if unavailable"}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": null, "unit": null, "note": "to taste"}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": null, "unit": null, "note": "to taste"}, {"name": "tomato sauce", "name_ms": "sos tomato", "quantity": null, "unit": null, "note": "to taste"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": null, "unit": null, "note": "use more than other sauces for best flavour"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a little if sauce is too dry"}, {"name": "onion", "name_ms": "bawang holland", "quantity": 1, "unit": null, "note": "sliced"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": null, "unit": null, "note": "to taste"}, {"name": "long beans", "name_ms": "kacang panjang", "quantity": null, "unit": null, "note": ""}]', '["Simmer the beef pieces for about 30 minutes until tender and the liquid has mostly reduced; drain.", "Add 1 tsp turmeric powder and a little cooking oil; stir to coat and let the beef brown slightly.", "Blend 7 cloves garlic with a knob of ginger.", "Add the garlic-ginger blend to the beef; stir and cook briefly.", "Add caramel soy sauce, sweet soy sauce, chilli sauce, tomato sauce and oyster sauce (use more oyster sauce for best flavour); stir to combine.", "Season with salt and seasoning powder; if too dry, add a little water.", "Add sliced sweet onion, bird''s eye chillies and long beans; stir-fry until the vegetables are cooked and the sauce clings to the beef."]', '["Rebus daging lebih kurang 30 minit sehingga empuk dan air hampir kering; toskan.", "Masukkan 1 sudu kecil serbuk kunyit dan sedikit minyak masak; gaul dan biarkan daging garing sikit.", "Blend 7 ulas bawang putih dengan seketul halia.", "Masukkan blend bawang putih-halia ke dalam daging; kacau dan masak sebentar.", "Masukkan kicap karamel, kicap manis, sos cili, sos tomato dan sos tiram (lebihkan sos tiram untuk rasa lebih sedap); kacau sebati.", "Tambah garam dan serbuk perasa; kalau terlalu kering masukkan sedikit air.", "Masukkan hirisan bawang Holland, cili padi dan kacang panjang; tumis sehingga sayur masak dan sos melekat pada daging."]', '["halal", "beef", "soy sauce", "braised", "malaysian", "hari raya"]', TRUE, TRUE, 'beef quantity not stated (described as ''raya leftover from freezer''); cook time estimated; servings estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7524576884361891079', 'Durian Crepe', 'Durian Crepe', 'Thin pandan crepe wrappers filled with a light, fluffy durian whipped cream — a popular Malaysian dessert.', 'Kulit crepe pandan yang nipis diisi dengan krim durian yang ringan dan gebu — pencuci mulut Malaysia yang popular.', 'Malaysian', 'Medium', 60, 20, 10, '["egg", "sugar", "salt", "all-purpose flour", "fresh milk", "butter", "pandan extract", "non-dairy whipping cream", "durian"]', '[{"name": "egg", "name_ms": "telur", "quantity": 4, "unit": null, "note": "for crepe batter"}, {"name": "sugar", "name_ms": "gula", "quantity": 3, "unit": "tbsp", "note": "for crepe batter"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "a pinch"}, {"name": "all-purpose flour", "name_ms": "tepung gandum", "quantity": 2, "unit": "cup", "note": "for crepe batter"}, {"name": "fresh milk", "name_ms": "fresh milk", "quantity": 2.5, "unit": "cup", "note": "for crepe batter"}, {"name": "butter", "name_ms": "butter", "quantity": 3, "unit": "tbsp", "note": "melted; for crepe batter"}, {"name": "pandan extract", "name_ms": "ekstrak pandan", "quantity": null, "unit": null, "note": "a few drops for colour; or pandan paste"}, {"name": "non-dairy whipping cream", "name_ms": "non-dairy cream", "quantity": null, "unit": null, "note": "quantity not stated; whipped to stiff peaks"}, {"name": "durian", "name_ms": "durian", "quantity": null, "unit": null, "note": "quantity flexible to taste"}]', '["Beat 4 eggs with 3 tbsp sugar and a pinch of salt.", "Gradually add 2 cup all-purpose flour, alternating with 2.5 cup fresh milk, whisking until smooth.", "Stir in 3 tbsp melted butter and a few drops of pandan extract for colour.", "Strain the batter; rest for 30 minutes.", "Cook thin crepes in a non-stick pan — pour a small ladle of batter, swirl to spread, cook until just set (no browning).", "Stack and cool completely.", "Whisk non-dairy cream until stiff peaks; fold in durian flesh until combined.", "Place a spoonful of durian cream in the centre of each crepe; fold or roll to enclose.", "Refrigerate for at least 1 hour before serving."]', '["Pukul 4 biji telur bersama 3 sudu gula dan secubit garam.", "Masukkan 2 cawan tepung gandum secara berselang-seli dengan 2 cawan setengah susu segar, kacau sehingga licin.", "Masukkan 3 sudu butter cair dan beberapa titik pewarna/ekstrak pandan.", "Tapis adunan; rehat 30 minit.", "Masak crepe nipis dalam kuali non-stick — tuang sedikit adunan, pusingkan supaya rata, masak sehingga set (jangan perang).", "Susun dan biarkan sejuk sepenuhnya.", "Pukul non-dairy cream sehingga kaku; lipat bersama isi durian sehingga sebati.", "Letakkan sesenduk krim durian di tengah-tengah setiap crepe; lipat atau gulung.", "Simpan dalam peti sejuk sekurang-kurangnya 1 jam sebelum dihidang."]', '["halal", "dessert", "crepe", "durian", "pandan", "malaysian", "raya"]', TRUE, TRUE, 'non-dairy cream quantity not stated; durian filling amount flexible; recipe is for crepes with durian cream filling', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608083211482172679', 'Chicken in Plum Sauce (Ayam Sos Plum)', 'Ayam Sos Plum', 'Crispy air-fried chicken pieces glazed in a sweet-tangy plum sauce with lemongrass, kaffir lime leaf and chilli.', 'Ayam goreng air fryer yang crispy kemudian digaulkan dalam sos plum manis-masam dengan serai, daun limau purut dan cili.', 'Malaysian', 'Easy', 15, 25, 4, '["chicken", "black pepper", "oyster sauce", "large red chilli", "bird''s eye chilli", "shallot", "garlic", "water", "plum sauce", "sweet soy sauce", "fish sauce", "lemongrass", "kaffir lime leaf", "cooking oil"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "black pepper", "name_ms": "black pepper", "quantity": null, "unit": null, "note": "for marinade; to taste"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": null, "unit": null, "note": "for marinade; 1 tbsp for sauce"}, {"name": "large red chilli", "name_ms": "lada besar", "quantity": 6, "unit": null, "note": "chopped for sauce"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 12, "unit": null, "note": "8 chopped for sauce; 4 more added as aromatics"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "chopped"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 4, "unit": "clove", "note": "chopped"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a little for sauce"}, {"name": "plum sauce", "name_ms": "sos plum", "quantity": 4, "unit": "tbsp", "note": "any brand"}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "fish sauce", "name_ms": "sos ikan", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "lemongrass", "name_ms": "serai", "quantity": 2, "unit": null, "note": "sliced; aromatic"}, {"name": "kaffir lime leaf", "name_ms": "daun limau purut", "quantity": 3, "unit": null, "note": "2-3 leaves"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for sautéing"}]', '["Marinate the chicken with black pepper and oyster sauce; air-fry at 200°C for 20 minutes until crispy and golden brown.", "Chop 6 large chillies, 8 bird''s eye chillies, 1 onion and 4 garlic cloves.", "Sauté the chopped aromatics until soft and the chilli is cooked.", "Add water, 4 tbsp plum sauce, 1 tbsp oyster sauce, 1 tbsp sweet soy sauce and 1 tbsp fish sauce; stir to combine.", "Add 2 sliced lemongrass stalks, 4 more bird''s eye chillies and 2–3 kaffir lime leaves.", "Add the crispy chicken and toss until evenly coated. Serve immediately."]', '["Perap ayam dengan black pepper dan sos tiram; bakar dalam air fryer pada suhu 200°C selama 20 minit sehingga crispy golden brown.", "Chop 6 biji lada besar, 8 biji cili padi, 1 biji bawang merah dan 4 ulas bawang putih.", "Tumis semua bahan yang dah dihacam sehingga layu dan cili masak.", "Masukkan air, 4 sudu sos plum, 1 sudu sos tiram, 1 sudu kicap manis dan 1 sudu sos ikan; kacau sebati.", "Masukkan 2 batang serai yang dihiris, 4 biji cili padi lagi dan 2-3 helai daun limau purut.", "Masukkan ayam crispy dan gaul sehingga rata. Hidang segera."]', '["halal", "chicken", "plum sauce", "air fryer", "sweet", "spicy", "malaysian", "ramadan", "sahur"]', TRUE, TRUE, 'chicken quantity not stated; initial marinade quantities (black pepper, oyster sauce) not stated; cook_time estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608088446246128914', 'Creamy Sardine in Coconut Milk (Sardin Bersantan)', 'Sardin Bersantan', 'Canned sardine gently simmered in coconut milk with aromatics — a simple, comforting side dish for sahur or lunch.', 'Sardin tin direneh perlahan dalam santan bersama rempah — lauk yang mudah dan menyelerakan untuk sahur atau makan tengah hari.', 'Malaysian', 'Easy', 10, 15, 3, '["canned sardine", "cooking oil", "shallot", "garlic", "ginger", "lemongrass", "tomato", "coconut milk", "salt", "seasoning powder", "sugar"]', '[{"name": "canned sardine", "name_ms": "sardin tin", "quantity": 1, "unit": "can", "note": "with sauce; stir gently"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for sautéing"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": ""}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": ""}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 2, "unit": null, "note": "bruised"}, {"name": "tomato", "name_ms": "tomato", "quantity": 1, "unit": null, "note": "chopped"}, {"name": "coconut milk", "name_ms": "santan", "quantity": 0.5, "unit": null, "note": "0.5 small box"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "a little"}]', '["Sauté 1 shallot, 5 garlic cloves, a knob of ginger and 2 bruised lemongrass stalks until fragrant.", "Add 1 tomato (chopped); cook until softened.", "Add 1 can sardines with their sauce; stir gently to avoid breaking the fish.", "Pour in 0.5 small box coconut milk; season with salt, seasoning powder and a little sugar.", "Simmer until the gravy thickens. Do not over-stir. Serve with rice."]', '["Tumis 1 bawang merah, 5 ulas bawang putih, seketul halia dan 2 batang serai diketuk sehingga wangi.", "Masukkan 1 biji tomato (dicincang); masak sehingga lembut.", "Masukkan 1 tin sardin bersama sosnya; gaul perlahan supaya ikan tidak hancur.", "Tuang setengah kotak kecil santan; tambah garam, serbuk perasa dan sedikit gula.", "Reneh sehingga kuah pekat. Jangan kacau terlalu kerap. Hidang bersama nasi."]', '["halal", "fish", "sardine", "coconut milk", "malaysian", "ramadan", "sahur"]', TRUE, FALSE, 'recipe for 1 can sardine; cook/prep times estimated; serves 3', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608088446246128914', 'Coconut Oil Fried Rice with Dried Chilli (Nasi Goreng Cili Kering)', 'Nasi Goreng Cili Kering', 'Smoky, fragrant fried rice cooked in coconut oil with a blended dried chilli paste — a distinctive and aromatic alternative to regular fried rice.', 'Nasi goreng yang berasap dan wangi dimasak dalam minyak kelapa dengan pes cili kering — alternatif yang berbeza dan aromatik daripada nasi goreng biasa.', 'Malaysian', 'Easy', 10, 10, 2, '["cooked white rice", "dried chilli", "shallot", "garlic", "coconut oil", "soy sauce", "oyster sauce", "egg", "spring onion"]', '[{"name": "cooked white rice", "name_ms": "nasi putih", "quantity": null, "unit": null, "note": "day-old rice preferred; quantity not stated"}, {"name": "dried chilli", "name_ms": "cili kering", "quantity": 10, "unit": null, "note": "soaked and blended"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "blended with chilli"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": "blended with chilli"}, {"name": "coconut oil", "name_ms": "minyak kelapa", "quantity": 2, "unit": "tbsp", "note": "gives distinctive flavour"}, {"name": "soy sauce", "name_ms": "kicap", "quantity": null, "unit": null, "note": "to taste"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": null, "unit": null, "note": "to taste"}, {"name": "egg", "name_ms": "telur", "quantity": 2, "unit": null, "note": "scrambled in"}, {"name": "spring onion", "name_ms": "daun bawang", "quantity": null, "unit": null, "note": "garnish"}]', '["Soak 10 dried chillies in hot water for 10 minutes; blend with 1 shallot and 5 garlic cloves until smooth.", "Heat 2 tbsp coconut oil in a wok; fry the paste until fragrant and the oil separates.", "Add cooked rice; toss well to combine with the paste.", "Season with soy sauce and oyster sauce to taste.", "Push rice to the side; crack in 2 eggs and scramble, then fold into the rice.", "Garnish with spring onion and serve."]', '["Rendam 10 biji cili kering dalam air panas 10 minit; blend bersama 1 bawang merah dan 5 ulas bawang putih sehingga lumat.", "Panaskan 2 sudu minyak kelapa dalam kuali; goreng pes sehingga wangi dan pecah minyak.", "Masukkan nasi masak; gaul rata bersama pes.", "Tambah kicap dan sos tiram secukup rasa.", "Tolak nasi ke tepi; pecahkan 2 biji telur dan scramble, kemudian gaul bersama nasi.", "Hiaskan dengan daun bawang dan hidang."]', '["halal", "fried rice", "coconut oil", "spicy", "malaysian", "ramadan", "sahur"]', TRUE, TRUE, 'cooked rice quantity not stated; day-old rice preferred', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608279986633510162', 'Pink Lemonade', 'Pink Lemonade', 'A classic sweet-sour pink lemonade coloured with a drop of food colouring — quick to make and refreshing for iftar.', 'Pink lemonade masam-manis klasik yang diwarnai dengan sedikit pewarna merah — cepat dibuat dan menyegarkan untuk berbuka.', 'Western', 'Easy', 5, 0, 2, '["lemon", "sugar syrup", "water", "red food colouring", "ice"]', '[{"name": "lemon", "name_ms": "lemon", "quantity": null, "unit": null, "note": "squeezed fresh"}, {"name": "sugar syrup", "name_ms": "air gula", "quantity": null, "unit": null, "note": "to taste; or dissolve sugar in a little hot water"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "cold"}, {"name": "red food colouring", "name_ms": "pewarna merah", "quantity": null, "unit": null, "note": "a few drops"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": ""}]', '["Squeeze fresh lemon juice into a pitcher.", "Add sugar syrup to taste and fill with cold water; stir.", "Add a few drops of red food colouring for the pink colour.", "Serve over ice."]', '["Perah jus lemon segar ke dalam jag.", "Masukkan air gula secukup rasa dan isi dengan air sejuk; kacau.", "Masukkan beberapa titik pewarna merah untuk warna pink.", "Hidang atas ais."]', '["halal", "drink", "cold", "lemonade", "western", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'all quantities to taste; simple assembly', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608279986633510162', 'Avocado Milkshake', 'Avocado Milkshake', 'A smooth and creamy avocado milkshake blended with fresh milk and sweetened condensed milk — popular at Malaysian iftar stalls.', 'Milkshake avokado yang licin dan berkrim diblend dengan susu segar dan susu pekat manis — popular di gerai berbuka Malaysia.', 'Malaysian', 'Easy', 5, 0, 2, '["avocado", "fresh milk", "sweetened condensed milk", "ice"]', '[{"name": "avocado", "name_ms": "avokado", "quantity": 1, "unit": null, "note": "ripe"}, {"name": "fresh milk", "name_ms": "fresh milk", "quantity": null, "unit": null, "note": ""}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": null, "unit": null, "note": "to taste"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": "handful"}]', '["Scoop 1 ripe avocado into a blender.", "Add fresh milk, sweetened condensed milk to taste and a handful of ice.", "Blend until smooth and creamy; pour and serve immediately."]', '["Masukkan isi 1 biji avokado masak ke dalam blender.", "Masukkan susu segar, susu pekat manis secukup rasa dan segenggam ais.", "Blend sehingga licin dan berkrim; tuang dan hidang dengan segera."]', '["halal", "drink", "milkshake", "cold", "avocado", "malaysian", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'quantities flexible; 1 ripe avocado per 2 glasses', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608279986633510162', 'Sirap Bandung Fizz', 'Sirap Bandung Fizz', 'A fizzy take on the classic Malaysian Sirap Bandung — rose syrup and evaporated milk topped with sparkling water.', 'Versi berkarbonat Sirap Bandung Malaysia — sirap ros dan susu cair ditambah air berkarbonat.', 'Malaysian', 'Easy', 3, 0, 1, '["roselle syrup", "evaporated milk", "sparkling water", "ice"]', '[{"name": "roselle syrup", "name_ms": "sirap ros", "quantity": null, "unit": null, "note": "generous pour; any rose/roselle syrup"}, {"name": "evaporated milk", "name_ms": "susu cair", "quantity": null, "unit": null, "note": "to taste"}, {"name": "sparkling water", "name_ms": "air berkarbonat", "quantity": null, "unit": null, "note": "to top up"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": "to fill glass"}]', '["Fill a glass with ice.", "Add a generous pour of rose/roselle syrup.", "Add evaporated milk; stir briefly.", "Top with sparkling water and serve."]', '["Isi gelas dengan ais.", "Masukkan sirap ros secara banyak.", "Masukkan susu cair; kacau sebentar.", "Tambah air berkarbonat dan hidang."]', '["halal", "drink", "cold", "bandung", "malaysian", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'quantities to taste; serve 1 tall glass', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608279986633510162', 'Mango Lassi', 'Mango Lassi', 'A classic Indian-style mango lassi blended with yogurt, milk and honey — light, tangy and perfect for iftar.', 'Mango lassi gaya India klasik yang diblend dengan yogurt, susu dan madu — ringan, masam-manis dan sempurna untuk berbuka.', 'Indian', 'Easy', 5, 0, 2, '["mango", "plain yogurt", "fresh milk", "honey", "ice"]', '[{"name": "mango", "name_ms": "mangga", "quantity": 1, "unit": null, "note": "ripe"}, {"name": "plain yogurt", "name_ms": "yogurt original", "quantity": null, "unit": null, "note": ""}, {"name": "fresh milk", "name_ms": "fresh milk", "quantity": null, "unit": null, "note": ""}, {"name": "honey", "name_ms": "madu", "quantity": null, "unit": null, "note": "to taste"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": ""}]', '["Blend mango flesh (from 1 ripe mango), plain yogurt, fresh milk, honey to taste and ice until smooth.", "Pour into glasses and serve cold."]', '["Blend isi mangga (dari 1 biji mangga masak), yogurt original, susu segar, madu secukup rasa dan ais sehingga licin.", "Tuang ke dalam gelas dan hidang dingin."]', '["halal", "drink", "cold", "mango", "lassi", "indian", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'quantities flexible; 1 mango per 2 glasses', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608279986633510162', 'Dragon Fruit Slushie', 'Dragon Fruit Slushie', 'A vibrant pink dragon fruit slushy blended with ice, honey and a squeeze of lime — naturally coloured and refreshing.', 'Slushy buah naga merah jambu yang cantik diblend dengan ais, madu dan perahan limau — warna semulajadi dan menyegarkan.', 'Malaysian', 'Easy', 5, 0, 2, '["dragon fruit", "ice", "honey", "lime"]', '[{"name": "dragon fruit", "name_ms": "buah naga", "quantity": 1, "unit": null, "note": "red variety for pink colour"}, {"name": "ice", "name_ms": "ais", "quantity": null, "unit": null, "note": "generous amount"}, {"name": "honey", "name_ms": "madu", "quantity": null, "unit": null, "note": "to taste"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "a squeeze"}]', '["Blend dragon fruit flesh with a generous amount of ice, honey to taste and a squeeze of lime until a slushy forms.", "Pour into glasses and serve immediately."]', '["Blend isi buah naga dengan banyak ais, madu secukup rasa dan perahan limau sehingga jadi slushy.", "Tuang ke dalam gelas dan hidang dengan segera."]', '["halal", "drink", "cold", "dragon fruit", "slushy", "malaysian", "ramadan", "iftar", "easy"]', TRUE, FALSE, 'quantities flexible; use red dragon fruit for bright pink colour', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608284402535107848', 'Steamed Caramel Pudding', 'Puding Karamel', 'A creamy, smooth caramel pudding made with cream cheese, evaporated milk and bread, steamed until set and best served cold straight from the fridge.', 'Puding karamel berkrim yang diperbuat daripada campuran roti, krim cheese dan krimer sejat, dikukus sehingga lembut dan paling sedap dimakan sejuk dari peti ais.', 'Malaysian', 'Easy', 20, 45, 8, '["sugar", "white bread", "evaporated milk", "egg", "sweetened condensed milk", "cream cheese", "vanilla essence", "salt"]', '[{"name": "sugar", "name_ms": "gula", "quantity": 0.5, "unit": "cup", "note": "for the caramel layer"}, {"name": "white bread", "name_ms": "roti putih", "quantity": 2, "unit": "slice", "note": "hard crusts removed"}, {"name": "evaporated milk", "name_ms": "krimer sejat", "quantity": 2, "unit": "cup", "note": "brand FNN"}, {"name": "egg", "name_ms": "telur", "quantity": 4, "unit": null, "note": ""}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": 0.5, "unit": "cup", "note": "brand FNN"}, {"name": "cream cheese", "name_ms": "krim cheese", "quantity": 0.5, "unit": "cup", "note": ""}, {"name": "vanilla essence", "name_ms": "esen vanila", "quantity": 1, "unit": "tsp", "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}]', '["Place 0.5 cup sugar in a dry pan and swirl over medium heat — do not stir with a spoon — until fully melted into golden caramel.", "Immediately pour the hot caramel into a baking tin; it is extremely hot so handle with care.", "Remove and discard the hard crusts from 2 slices of white bread.", "Blend 2 cup evaporated milk, the trimmed bread, 4 eggs, 0.5 cup sweetened condensed milk, 0.5 cup cream cheese, 1 tsp vanilla essence, and a pinch of salt until completely smooth.", "Strain the blended mixture through a sieve.", "Rest a ladle underneath the stream and slowly pour the strained mixture into the caramel-lined tin to avoid splashing.", "Wrap the tin tightly with aluminium foil.", "Steam over medium-low heat for 45 minutes.", "Allow to cool completely, then refrigerate for at least 2–3 hours before serving."]', '["Masukkan setengah cawan gula ke dalam kuali kering, gerak-gerakkan atas api sederhana — jangan kacau dengan sudu — sehingga gula cair dan jadi caramel keemasan.", "Tuangkan caramel ke dalam loyang dengan segera; sangat panas jadi berhati-hati.", "Potong dan buang bahagian keras tepi 2 keping roti putih.", "Blend 2 cawan krimer sejat, roti yang dipotong, 4 biji telur, setengah cawan krimer manis, setengah cawan krim cheese, 1 sudu kecil esen vanila, dan garam sikit sehingga sebati.", "Tapis adunan blend melalui penapis.", "Letakkan senduk di bawah aliran dan tuang adunan yang ditapis ke dalam loyang beralas caramel secara perlahan.", "Balut loyang dengan aluminium foil rapat-rapat.", "Kukus atas api sederhana-kecil selama 45 minit.", "Biarkan cool down sepenuhnya, kemudian simpan dalam peti sejuk sekurang-kurangnya 2–3 jam sebelum dihidang."]', '["halal", "dessert", "steamed", "pudding", "caramel", "ramadan", "raya"]', TRUE, FALSE, 'cook_time from transcript (45 min steaming); prep_time estimated; servings estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608286853602495762', 'Padang-Style Coconut Poached Chicken (Ayam Pop)', 'Ayam Pop', 'Tender chicken poached in coconut water and coconut milk, served with a rich fried sambal and a silky coconut milk gravy — a classic Padang restaurant favourite.', 'Ayam yang direbus dalam air kelapa dan santan sehingga lembut, dihidang dengan sambal goreng yang kaya dan kuah santan yang licin — kegemaran restoran nasi Padang.', 'Indonesian', 'Medium', 20, 35, 4, '["chicken", "lemongrass", "ginger", "garlic", "coconut water", "coconut milk", "salt", "tomato", "bird''s eye chilli", "shallot", "shrimp paste", "kaffir lime leaf", "water", "cornstarch", "sugar", "seasoning powder", "cassava shoots"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 4, "unit": null, "note": "bruised; for poaching"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; bruised; for poaching"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 10, "unit": "clove", "note": "5 bruised for poaching; 5 blended for sambal"}, {"name": "coconut water", "name_ms": "air kelapa", "quantity": 3, "unit": "cup", "note": "for poaching"}, {"name": "coconut milk", "name_ms": "santan", "quantity": null, "unit": null, "note": "1/4 cup for poaching; 2-3 tbsp for sambal; 0.5 small box for kuah"}, {"name": "salt", "name_ms": "garam", "quantity": 1, "unit": "tsp", "note": "for poaching; also to taste for sambal and kuah"}, {"name": "tomato", "name_ms": "tomato", "quantity": 1, "unit": null, "note": "for sambal"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 15, "unit": null, "note": "for sambal"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "for sambal"}, {"name": "shrimp paste", "name_ms": "belacan", "quantity": 1, "unit": null, "note": "1 block; roasted; for sambal"}, {"name": "kaffir lime leaf", "name_ms": "daun limau purut", "quantity": 2, "unit": null, "note": "sliced; for sambal"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "for sambal and kuah"}, {"name": "cornstarch", "name_ms": "tepung jagung", "quantity": null, "unit": null, "note": "slurry to thicken kuah"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "for sambal and kuah"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "cassava shoots", "name_ms": "pucuk ubi kayu", "quantity": null, "unit": null, "note": "optional side; boiled in salted water"}]', '["Place chicken in a pot with 4 bruised lemongrass stalks, a knob of ginger, 5 bruised garlic cloves, 3 cup coconut water, 1/4 cup coconut milk and 1 tsp salt.", "Simmer until the chicken is cooked through; remove chicken and set aside. Reserve the poaching liquid.", "[Sambal] Blend 1 tomato, 15 bird''s eye chillies, 1 onion, 5 garlic cloves and 1 roasted shrimp paste block with a little oil (not water).", "Fry the sambal paste over medium heat, adding 2 sliced kaffir lime leaves; cook until the oil separates and the colour is deep.", "Add a little water and 2–3 tbsp coconut milk; season with salt, sugar and seasoning powder. Continue cooking until glossy and the oil separates.", "[Kuah] Add coconut milk (0.5 small box), sugar and water to the reserved poaching liquid; thicken with a cornstarch slurry.", "Optionally boil cassava shoots in salted water and serve alongside.", "Plate the chicken; top with sambal and pour the coconut milk gravy over."]', '["Masukkan ayam dalam periuk bersama 4 batang serai diketuk, seketul halia, 5 ulas bawang putih diketuk, 3 cawan air kelapa, 1/4 cawan santan dan 1 sudu kecil garam.", "Rebus sehingga ayam masak; angkat ayam dan ketepikan. Simpan air rebusan.", "[Sambal] Blend 1 biji tomato, 15 biji cili padi, 1 biji bawang merah, 5 ulas bawang putih dan 1 ketul belacan yang dibakar dengan sedikit minyak (bukan air).", "Goreng pes sambal atas api sederhana bersama 2 helai daun limau purut yang dihiris; masak sehingga pecah minyak dan warna gelap.", "Tambah sedikit air dan 2-3 sudu santan; tambah garam, gula dan serbuk perasa. Sambung masak sehingga berkilat dan pecah minyak.", "[Kuah] Masukkan santan (setengah kotak kecil), gula dan air ke dalam air rebusan ayam tadi; pekatkan dengan air tepung jagung.", "Boleh rebus pucuk ubi kayu dalam air bergaram dan hidang bersama (pilihan).", "Susun ayam di atas pinggan; letak sambal di atas dan tuang kuah santan."]', '["halal", "chicken", "coconut milk", "padang", "indonesian", "sambal", "malaysian", "raya"]', TRUE, TRUE, 'chicken quantity not stated; cassava shoots optional and not quantified; coconut milk for gravy stated as ''2-3 sudu santan''', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608800441157061896', 'Cantonese Yee Mee (Hong Kong Egg Noodles in Thick Sauce)', 'Yimi Goreng Basah (Cantonese Yee Mee)', 'Silky Hong Kong egg noodles in a cornstarch-thickened savory sauce with mixed seafood — a Cantonese restaurant classic made at home.', 'Mi yimi Hong Kong dalam kuah pekat berasaskan kanji dengan seafood campuran — masakan restoran Cantonese yang dibuat di rumah.', 'Chinese', 'Medium', 15, 20, 3, '["Hong Kong egg noodles (yee mee)", "cooking oil", "garlic", "oyster sauce", "soy sauce", "dark soy sauce", "white pepper", "chicken stock cube", "water", "cornstarch", "prawn", "squid", "egg", "spring onion", "sesame oil"]', '[{"name": "Hong Kong egg noodles (yee mee)", "name_ms": "yimi", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for sautéing"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 4, "unit": "clove", "note": ""}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "soy sauce", "name_ms": "kicap", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "dark soy sauce", "name_ms": "kicap pekat", "quantity": 0.5, "unit": "tbsp", "note": ""}, {"name": "white pepper", "name_ms": "white pepper", "quantity": null, "unit": null, "note": "to taste"}, {"name": "chicken stock cube", "name_ms": "kiub pati ayam", "quantity": 1, "unit": null, "note": ""}, {"name": "water", "name_ms": "air", "quantity": 1.5, "unit": "cup", "note": "for sauce"}, {"name": "cornstarch", "name_ms": "tepung jagung", "quantity": 2, "unit": "tbsp", "note": "for slurry"}, {"name": "prawn", "name_ms": "udang", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "squid", "name_ms": "sotong", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "egg", "name_ms": "telur", "quantity": 1, "unit": null, "note": "folded into sauce"}, {"name": "spring onion", "name_ms": "daun bawang", "quantity": null, "unit": null, "note": "for garnish"}, {"name": "sesame oil", "name_ms": "minyak bijan", "quantity": null, "unit": null, "note": "a drop for fragrance"}]', '["Blanch yee mee noodles in boiling water for 30 seconds; drain and set aside.", "Sauté 4 garlic cloves in hot oil until golden.", "Add 2 tbsp oyster sauce, 1 tbsp soy sauce and 0.5 tbsp dark soy sauce; stir.", "Add white pepper, 1 chicken stock cube and 1.5 cup water; bring to a simmer.", "Add prawns and squid; cook until just done.", "Thicken with a cornstarch slurry (2 tbsp cornstarch + water) until the sauce is glossy and coats a spoon.", "Push the noodles to one side; crack in 1 egg and fold into the sauce.", "Add a drop of sesame oil; garnish with spring onion. Serve immediately."]', '["Celur yimi dalam air mendidih 30 saat; toskan dan ketepikan.", "Tumis 4 ulas bawang putih dalam minyak panas sehingga keemasan.", "Masukkan 2 sudu sos tiram, 1 sudu kicap dan setengah sudu kicap hitam; kacau.", "Masukkan white pepper, 1 kiub pati ayam dan 1 cawan setengah air; biarkan menggelegak.", "Masukkan udang dan sotong; masak sehingga baru masak.", "Pekatkan dengan bancuhan tepung jagung (2 sudu tepung jagung + air) sehingga kuah berkilat.", "Tolak mi ke tepi; pecahkan 1 telur dan lipat ke dalam kuah.", "Masukkan titisan minyak bijan; hiaskan dengan daun bawang. Hidang dengan segera."]', '["halal", "noodles", "cantonese", "seafood", "chinese", "yee mee", "malaysian", "raya"]', TRUE, TRUE, 'seafood (prawn/squid) quantity not stated; yee mee/yimi quantity not stated; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7608860626051452168', 'Fried Mantou with Buttermilk Sauce', 'Roti Mantou Goreng dengan Sos Buttermilk', 'Crispy fried mini mantou buns served with a creamy, garlicky buttermilk sauce made with curry leaf, cheese and evaporated milk.', 'Roti mantou mini yang digoreng garing dicicah dengan sos buttermilk yang creamy, berkari daun dan berkeju.', 'Fusion', 'Easy', 10, 15, 3, '["frozen mantou", "garlic", "bird''s eye chilli", "butter", "curry leaf", "evaporated milk", "chicken stock cube", "sweetened condensed milk", "processed cheese", "cooking oil"]', '[{"name": "frozen mantou", "name_ms": "mantou", "quantity": null, "unit": null, "note": "mini mantou buns from frozen section; quantity not stated"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 4, "unit": "clove", "note": "chopped"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 3, "unit": null, "note": "chopped"}, {"name": "butter", "name_ms": "butter", "quantity": 1, "unit": "tbsp", "note": "for sautéing"}, {"name": "curry leaf", "name_ms": "daun kari", "quantity": 2, "unit": null, "note": "2 stalks"}, {"name": "evaporated milk", "name_ms": "susu cair", "quantity": 0.5, "unit": "can", "note": "approx. 187 ml"}, {"name": "chicken stock cube", "name_ms": "kiub pati ayam", "quantity": null, "unit": null, "note": "a small amount; be careful not to oversalt"}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": 0.5, "unit": "tbsp", "note": ""}, {"name": "processed cheese", "name_ms": "cheese", "quantity": 2, "unit": "slice", "note": "melted into sauce"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying mantou"}]', '["Chop 4 garlic cloves and 3 bird''s eye chillies.", "Sauté in 1 tbsp butter until slightly soft; add 2 stalks curry leaf and stir briefly.", "Pour in 0.5 can evaporated milk; add a small amount of chicken stock cube (not too much — it will be salty).", "Add 0.5 tbsp sweetened condensed milk and 2 slices processed cheese; stir until the cheese melts into a creamy sauce.", "Meanwhile, fry the frozen mini mantou buns in hot oil until golden brown on all sides.", "Serve the mantou hot with the buttermilk sauce for dipping."]', '["Chop 4 ulas bawang putih dan 3 biji cili padi.", "Tumis dalam 1 sudu besar butter sehingga layu sikit; masukkan 2 tangkai daun kari dan kacau sebentar.", "Tuang setengah tin susu cair; masukkan sedikit kiub pati ayam (jangan banyak — nanti masin).", "Masukkan setengah sudu besar susu pekat manis dan 2 keping cheese; kacau sehingga cheese cair menjadi sos yang creamy.", "Sementara itu, goreng roti mantou mini beku dalam minyak panas sehingga golden brown semua sisi.", "Hidang mantou panas-panas bersama sos buttermilk untuk dicicah."]', '["halal", "snack", "buttermilk", "mantou", "cheese", "malaysian", "raya"]', TRUE, TRUE, 'mantou quantity not stated; chicken stock cube quantity vague (''sikit jangan banyak''); cheese slices quantity stated as ''2 keping''', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7609170882749041928', 'Peri Peri Chicken', 'Ayam Peri Peri', 'Tender chicken thighs marinated overnight in homemade peri peri sauce — grilled or baked, then basted and finished on a griddle for a charred finish.', 'Peha ayam yang diperap semalaman dalam sos peri peri buatan sendiri — dibakar atau dipanggang, kemudian digrid untuk kesan hangus yang wangi.', 'Fusion', 'Easy', 720, 40, 4, '["chicken", "bird''s eye chilli", "large red chilli", "garlic", "lemon", "cooking oil", "paprika powder", "oregano", "salt", "black pepper", "butter", "peri peri sauce"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "thigh pieces, skin-on; quantity not stated"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 5, "unit": null, "note": "for marinade"}, {"name": "large red chilli", "name_ms": "cili besar", "quantity": 3, "unit": null, "note": "for marinade"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 6, "unit": "clove", "note": "for marinade"}, {"name": "lemon", "name_ms": "lemon", "quantity": 1, "unit": null, "note": "juiced; more for basting sauce"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": 3, "unit": "tbsp", "note": "for marinade"}, {"name": "paprika powder", "name_ms": "serbuk paprika", "quantity": 1, "unit": "tbsp", "note": "for marinade"}, {"name": "oregano", "name_ms": "oregano", "quantity": 1, "unit": "tsp", "note": "for marinade"}, {"name": "salt", "name_ms": "garam", "quantity": 1, "unit": "tsp", "note": "for marinade"}, {"name": "black pepper", "name_ms": "black pepper", "quantity": null, "unit": null, "note": "to taste; for marinade"}, {"name": "butter", "name_ms": "butter", "quantity": 2, "unit": "tbsp", "note": "for basting sauce"}, {"name": "peri peri sauce", "name_ms": "sos peri peri", "quantity": 3, "unit": "tbsp", "note": "bottled; any brand; for basting sauce"}]', '["Blend 5 bird''s eye chillies, 3 large red chillies, 6 garlic cloves, juice of 1 lemon, 3 tbsp cooking oil, 1 tbsp paprika powder, 1 tsp oregano, 1 tsp salt and black pepper until smooth.", "Score the chicken thighs (skin-on) deeply; coat thoroughly with the marinade.", "Marinate overnight in the fridge for best results.", "Bake at 200°C for 30 minutes until cooked through.", "For the basting sauce: melt 2 tbsp butter; add 3 tbsp bottled peri peri sauce (Nando''s or any brand) and a squeeze of lemon.", "Sear the baked chicken on a hot griddle pan; baste with the butter-peri peri mix until lightly charred on both sides.", "Serve with rice or sides of choice."]', '["Blend 5 biji cili padi, 3 biji lada besar merah, 6 ulas bawang putih, jus 1 biji lemon, 3 sudu minyak goreng, 1 sudu serbuk paprika, 1 sudu kecil oregano, 1 sudu kecil garam dan black pepper sehingga lumat.", "Calit ayam (dengan kulit) secara dalam; salut dengan pes marinad secara menyeluruh.", "Perap semalaman dalam peti sejuk untuk hasil terbaik.", "Bakar pada suhu 200°C selama 30 minit sehingga masak.", "Untuk sos sapuan: cairkan 2 sudu butter; masukkan 3 sudu sos peri peri dari botol (Nando''s atau mana-mana jenama) dan perahan lemon.", "Masak ayam yang telah dibakar dalam kuali griddle panas; sapu dengan campuran butter-peri peri sehingga sedikit hangus di kedua-dua belah.", "Hidang dengan nasi atau ulam pilihan."]', '["halal", "chicken", "grilled", "peri peri", "western", "raya", "easy"]', TRUE, TRUE, 'chicken quantity not stated; peri peri sauce (bottled) amount flexible', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7609204260554689799', 'Banana Sago in Palm Sugar Syrup (Pisang Sagu Gula Melaka)', 'Pisang Sagu Gula Melaka', 'A refreshing cold dessert of soft banana pieces and sago pearls in a fragrant palm sugar syrup, served over ice with evaporated milk.', 'Pencuci mulut sejuk berupa kepingan pisang lembut dan sagu dalam sirup gula Melaka yang wangi, dihidang atas ais dengan susu cair.', 'Malaysian', 'Easy', 10, 15, 4, '["banana", "palm sugar", "water", "sago pearls", "salt", "evaporated milk"]', '[{"name": "banana", "name_ms": "pisang", "quantity": 5, "unit": null, "note": "very ripe; sliced"}, {"name": "palm sugar", "name_ms": "gula melaka", "quantity": 4, "unit": null, "note": "4 small blocks"}, {"name": "water", "name_ms": "air", "quantity": 0.5, "unit": "cup", "note": "for syrup"}, {"name": "sago pearls", "name_ms": "sagu", "quantity": null, "unit": null, "note": "quantity flexible"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "a pinch"}, {"name": "evaporated milk", "name_ms": "susu cair", "quantity": null, "unit": null, "note": "poured over when serving"}]', '["Cook sago pearls in boiling water until translucent; drain, rinse and set aside.", "Place 4 small blocks palm sugar and 0.5 cup water in a pot; add sliced ripe bananas (from 5 bananas).", "Cook until the bananas are soft and the palm sugar has dissolved into a syrup.", "Add a pinch of salt.", "Stir in the cooked sago.", "Let cool; serve over ice with a generous pour of evaporated milk."]', '["Masak sagu dalam air mendidih sehingga lutsinar; toskan, bilas dan ketepikan.", "Masukkan 4 ketul kecil gula Melaka dan setengah cawan air ke dalam periuk; masukkan hirisan pisang masak (dari 5 biji pisang).", "Masak sehingga pisang lembut dan gula Melaka cair menjadi sirup.", "Masukkan secubit garam.", "Gaul masuk sagu yang sudah dimasak.", "Biarkan sejuk; hidang atas ais dengan susu cair yang banyak."]', '["halal", "dessert", "banana", "sago", "palm sugar", "cold", "malaysian", "raya"]', TRUE, FALSE, 'sago quantity flexible; evaporated milk for serving not quantified; prep/cook times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7609536695586901256', 'Steamed Rice with Spiced Fried Chicken, Curry Gravy and Sambal Belacan', 'Nasi Kukus Ayam Berempah dengan Kuah Gulai dan Sambal Belacan', 'A complete nasi kukus set: fragrant spiced fried chicken, steamed basmati rice, a rich curry-style gravy with eggplant and long beans, and a spicy-sour sambal belacan.', 'Set nasi kukus lengkap: ayam goreng berempah yang wangi, nasi basmati kukus, kuah gulai yang kaya rasa dengan terung dan kacang panjang, serta sambal belacan pedas-masam.', 'Malaysian', 'Medium', 40, 40, 4, '["lemongrass", "galangal", "curry powder", "chilli powder", "coriander powder", "fennel seeds", "cumin", "turmeric powder", "salt", "curry leaf", "water", "chicken", "basmati rice", "onion", "ginger", "garlic", "whole spices (cinnamon, cloves, star anise, cardamom)", "blended chilli", "beef curry spice mix", "korma spice mix", "coconut milk", "palm sugar", "seasoning powder", "eggplant", "long beans", "bell pepper", "bird''s eye chilli", "shrimp paste", "calamansi lime", "sugar"]', '[{"name": "lemongrass", "name_ms": "serai", "quantity": 4, "unit": null, "note": "stalks; blended for ayam marinade"}, {"name": "galangal", "name_ms": "lengkuas", "quantity": null, "unit": null, "note": "1 knob; blended for ayam marinade"}, {"name": "curry powder", "name_ms": "serbuk kari", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "chilli powder", "name_ms": "serbuk cili", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "coriander powder", "name_ms": "serbuk ketumbar", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "fennel seeds", "name_ms": "jintan manis", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "cumin", "name_ms": "jintan putih", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": 1, "unit": "tsp", "note": "for ayam marinade"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "0.5 tsp for marinade; to taste for gulai and sambal"}, {"name": "curry leaf", "name_ms": "daun kari", "quantity": 2, "unit": null, "note": "2 stalks; for ayam marinade"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "for marinade and gulai"}, {"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "basmati rice", "name_ms": "beras basmati", "quantity": null, "unit": null, "note": "quantity not stated; steamed"}, {"name": "onion", "name_ms": "bawang holland", "quantity": 1, "unit": null, "note": "blended for gulai"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; blended for gulai"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": "blended for gulai"}, {"name": "whole spices (cinnamon, cloves, star anise, cardamom)", "name_ms": "rempah 4 sekawan", "quantity": null, "unit": null, "note": "for gulai"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 3, "unit": "tbsp", "note": "mild type; for gulai"}, {"name": "beef curry spice mix", "name_ms": "rempah kari daging", "quantity": 3, "unit": "tbsp", "note": "for gulai"}, {"name": "korma spice mix", "name_ms": "rempah kurma daging", "quantity": 2, "unit": "tbsp", "note": "for gulai"}, {"name": "coconut milk", "name_ms": "santan", "quantity": 1, "unit": null, "note": "1 small box; for gulai"}, {"name": "palm sugar", "name_ms": "gula melaka", "quantity": null, "unit": null, "note": "half a small block; for gulai"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "eggplant", "name_ms": "terung", "quantity": null, "unit": null, "note": "for gulai"}, {"name": "long beans", "name_ms": "kacang panjang", "quantity": null, "unit": null, "note": "for gulai"}, {"name": "bell pepper", "name_ms": "lada benggala", "quantity": 2, "unit": null, "note": "for sambal belacan"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 10, "unit": null, "note": "for sambal belacan"}, {"name": "shrimp paste", "name_ms": "belacan", "quantity": null, "unit": null, "note": "small amount; roasted; for sambal belacan"}, {"name": "calamansi lime", "name_ms": "limau kasturi", "quantity": 6, "unit": null, "note": "4 squeezed; 2 blended whole (seeds removed); for sambal belacan"}, {"name": "sugar", "name_ms": "gula", "quantity": 2, "unit": "tbsp", "note": "for sambal belacan"}]', '["[Ayam Berempah] Blend 4 lemongrass stalks and a knob of galangal; strain and keep only the pulp (discard liquid). Mix pulp with 1 tsp each: curry powder, chilli powder, coriander powder, fennel seeds, cumin, turmeric powder; 0.5 tsp salt; 2 stalks curry leaf; a little water. Marinate chicken for 20 minutes.", "Fry the marinated chicken (the pulp goes in too for crunch) until golden and crispy.", "[Nasi Kukus] Rinse basmati rice; add water and steam for 20–25 minutes until fluffy.", "[Kuah Gulai] Blend 1 sweet onion, a knob of ginger and 5 garlic cloves. Sauté with whole spices.", "Add 3 tbsp blended chilli (mild), 3 tbsp beef curry spice mix and 2 tbsp korma spice mix; cook until oil separates.", "Add chicken innards or offcuts if available; add water and 1 small box coconut milk.", "Season with half a small palm sugar block, salt and seasoning powder.", "Add eggplant and long beans; cook until tender.", "[Sambal Belacan] Blend 2 bell peppers, 10 bird''s eye chillies and a small amount of roasted shrimp paste. Squeeze in juice of 4 calamansi limes (remove seeds). Blend 2 more calamansi limes whole (seeds removed). Add 2 tbsp sugar, a little seasoning powder, salt and a little water. Blend until smooth.", "Plate rice with chicken, ladle gravy over and top with sambal belacan."]', '["[Ayam Berempah] Blend 4 batang serai dan seketul lengkuas; tapis, ambil serdak sahaja (buang air). Gaul serdak dengan 1 sudu kecil setiap satu: serbuk kari, serbuk cili, serbuk ketumbar, jintan manis, jintan putih, serbuk kunyit; setengah sudu kecil garam; 2 tangkai daun kari; sedikit air. Perap ayam 20 minit.", "Goreng ayam berempah (serdak ikut sekali untuk bunyi krup) sehingga golden crispy.", "[Nasi Kukus] Basuh beras basmati; masukkan air dan kukus 20-25 minit sehingga gebu.", "[Kuah Gulai] Blend 1 bawang Holland, seketul halia dan 5 ulas bawang putih. Tumis dengan rempah 4 sekawan.", "Masukkan 3 sudu cili kisar (tak pedas), 3 sudu rempah kari daging dan 2 sudu rempah kurma daging; masak sehingga pecah minyak.", "Masukkan hati/dalaman ayam jika ada; tambah air dan 1 kotak kecil santan.", "Tambah separuh ketul kecil gula Melaka, garam dan serbuk perasa.", "Masukkan terung dan kacang panjang; masak sehingga lembut.", "[Sambal Belacan] Blend 2 lada besar, 10 cili padi dan sedikit belacan yang dah dibakar. Perah jus 4 biji limau kasturi (buang biji). Blend 2 biji limau kasturi lagi (buang biji) bersama kulit. Tambah 2 sudu gula, sedikit serbuk perasa, garam dan sedikit air. Blend sehingga lumat.", "Susun nasi bersama ayam, tuang kuah gulai dan letak sambal belacan di atas."]', '["halal", "chicken", "rice", "coconut milk", "curry", "sambal", "malaysian", "raya"]', TRUE, TRUE, 'multi-component recipe with 4 departments (ayam berempah, nasi kukus, gulai, sambal belacan); chicken qty not stated; basmati rice water ratio not stated exactly; some spice powder quantities assumed 1 tsp each based on context', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7609573463442918663', 'S''mores Dip', 'S''mores Dip', 'A simple three-ingredient s''mores dip — toasted marshmallow topped with melted chocolate, served with biscuits for dipping.', 'Dip s''mores tiga bahan yang mudah — marshmallow yang dibakar dengan coklat cair di atas, dicicah dengan biskut yang rangup.', 'Western', 'Easy', 5, 5, 4, '["marshmallow", "chocolate bar", "biscuit"]', '[{"name": "marshmallow", "name_ms": "marshmallow", "quantity": null, "unit": null, "note": "quantity not stated; fill the container"}, {"name": "chocolate bar", "name_ms": "coklat bar", "quantity": null, "unit": null, "note": "quantity not stated; semi-sweet or dark recommended for balance"}, {"name": "biscuit", "name_ms": "biskut", "quantity": null, "unit": null, "note": "Hobnobs preferred per transcript; any sturdy biscuit works"}]', '["Use an oven-safe aluminium container (not plastic).", "Fill the container with marshmallows (do not overfill — they will expand); bake in an air fryer at 200°C for 3 minutes until toasted.", "Break the chocolate bar into pieces and place on top of the toasted marshmallow; bake at 140°C for 1–2 minutes until just melted.", "Serve immediately with biscuits for dipping — or press two biscuits around a spoonful to make a sandwich."]', '["Guna bekas aluminium yang sesuai untuk air fryer (jangan plastik — ia akan cair).", "Isi bekas dengan marshmallow (jangan penuh sangat — ia akan kembang); bakar dalam air fryer pada suhu 200°C selama 3 minit.", "Pecah-pecahkan bar coklat dan letak di atas marshmallow yang dah dibakar; bakar pada 140°C selama 1-2 minit sehingga cair sikit sahaja.", "Hidang segera dengan biskut untuk cicah — atau kapit di antara dua biskut jadi sandwich."]', '["halal", "dessert", "snack", "chocolate", "marshmallow", "western", "raya", "easy"]', TRUE, TRUE, 'marshmallow and chocolate bar quantities not stated; biscuit type stated as Hobnobs but any will work', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7609600086259125511', 'Sambal Tempeh with Soy Dipping Sauce', 'Sambal Tempe dengan Sambal Kicap', 'Crispy fried tempeh tossed in a pounded chilli sambal with calamansi lime — served with a blended sweet soy dipping sauce.', 'Tempe yang digoreng rangup kemudian dicampur dengan sambal cili yang ditumbuk dan perahan limau kasturi — dicicah dengan sambal kicap pedas.', 'Malaysian', 'Easy', 10, 15, 3, '["tempeh", "cooking oil", "bird''s eye chilli", "large red chilli", "tomato", "shallot", "garlic", "salt", "sugar", "seasoning powder", "calamansi lime", "sweet soy sauce"]', '[{"name": "tempeh", "name_ms": "tempe", "quantity": 1, "unit": null, "note": "1 block; sliced thin for maximum crispiness"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 10, "unit": null, "note": "halved before frying; more for sambal kicap"}, {"name": "large red chilli", "name_ms": "cili besar", "quantity": 2, "unit": null, "note": "halved; for sambal"}, {"name": "tomato", "name_ms": "tomato", "quantity": 0.5, "unit": null, "note": "half a tomato"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 0.5, "unit": null, "note": "half an onion"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": "for sambal; more for sambal kicap"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "calamansi lime", "name_ms": "limau kasturi", "quantity": 5, "unit": null, "note": "squeezed into sambal"}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": null, "unit": null, "note": "for sambal kicap; amount to taste"}]', '["Slice 1 block of tempeh thinly; fry in hot oil until golden and crispy. Drain and set aside.", "Halve the bird''s eye chillies and large red chillies (to prevent them from bursting during frying); fry in hot oil with 0.5 tomato, 0.5 onion and 5 garlic cloves until wilted and lightly charred.", "Pound the fried aromatics until coarsely ground.", "Season with salt, sugar and seasoning powder.", "Add the fried tempeh; fold it into the sambal — do not over-pound, keep some crunch.", "Squeeze in juice of 5 calamansi limes for a sour-spicy finish.", "[Sambal kicap] Blend sweet soy sauce, bird''s eye chilli and garlic until smooth; serve alongside."]', '["Potong 1 blok tempe nipis-nipis; goreng dalam minyak panas sehingga golden rangup. Toskan dan ketepikan.", "Belah dua cili padi dan lada besar (elak meletus semasa goreng); goreng dalam minyak panas bersama setengah biji tomato, setengah biji bawang merah dan 5 ulas bawang putih sehingga layu dan sedikit hangus.", "Tumbuk semua bahan yang dah digoreng sehingga lumat kasar.", "Tambah garam, gula dan serbuk perasa.", "Masukkan tempe goreng; gaul — jangan tumbuk terlalu hancur, kekalkan krup.", "Perah jus 5 biji limau kasturi untuk rasa masam-pedas.", "[Sambal kicap] Blend kicap manis, cili padi dan bawang putih sehingga lumat; hidang bersama tempe."]', '["halal", "vegetarian", "tempeh", "sambal", "malaysian", "ramadan", "sahur"]', TRUE, FALSE, 'serving and time estimates; recipe is for 1 block of tempeh', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7609908058969591047', 'Crispy Fried Chicken with Thai Aromatics', 'Ayam Goreng Crispy Cicah Sos Thai', 'Sesame-battered crispy fried chicken marinated in fish sauce, finished by frying with green chilli, kaffir lime leaf and garlic for fragrance.', 'Ayam goreng crispy berlapis bijan yang diperap dalam sos ikan, kemudian digoreng sekali dengan cili hijau, daun limau purut dan bawang putih untuk aroma yang wangi.', 'Fusion', 'Easy', 40, 20, 3, '["chicken", "fish sauce", "black pepper", "sugar", "chicken fried flour", "rice flour", "salt", "seasoning powder", "water", "sesame seeds", "cooking oil", "green chilli", "kaffir lime leaf", "garlic"]', '[{"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "fish sauce", "name_ms": "sos ikan", "quantity": 2, "unit": "tbsp", "note": "for marinade"}, {"name": "black pepper", "name_ms": "black pepper", "quantity": null, "unit": null, "note": "to taste; for marinade"}, {"name": "sugar", "name_ms": "gula", "quantity": 1, "unit": "tbsp", "note": "for marinade"}, {"name": "chicken fried flour", "name_ms": "tepung goreng ayam", "quantity": 2, "unit": "tbsp", "note": "brand Bestari; for batter"}, {"name": "rice flour", "name_ms": "tepung beras", "quantity": 2, "unit": "tbsp", "note": "for batter"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste; for batter"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste; for batter"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "for batter; add gradually"}, {"name": "sesame seeds", "name_ms": "bijan", "quantity": null, "unit": null, "note": "stirred into batter"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "deep frying"}, {"name": "green chilli", "name_ms": "cili hijau", "quantity": null, "unit": null, "note": "quantity not stated; fried with chicken at end"}, {"name": "kaffir lime leaf", "name_ms": "daun limau purut", "quantity": null, "unit": null, "note": "quantity not stated; fried with chicken at end"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": null, "unit": null, "note": "quantity not stated; fried with chicken at end"}]', '["Marinate the chicken with 2 tbsp fish sauce, black pepper to taste and 1 tbsp sugar; rest for 30 minutes.", "Mix 2 tbsp chicken fried flour, 2 tbsp rice flour, salt and seasoning powder; add water gradually until the batter is neither too thick nor too thin.", "Stir in sesame seeds.", "Coat the marinated chicken pieces in the batter.", "Fry in very hot oil, placing pieces in one by one; when almost done, add sliced green chilli, kaffir lime leaf and garlic cloves — all these are edible and add fragrance.", "Fry until golden and crispy. Drain and serve."]', '["Perap ayam dengan 2 sudu besar sos ikan, black pepper secukupnya dan 1 sudu besar gula; rehat selama 30 minit.", "Gaul 2 sudu tepung goreng ayam (Bestari), 2 sudu tepung beras, garam dan serbuk perasa; masukkan air sikit-sikit sehingga adunan tidak terlalu pekat mahupun cair.", "Masukkan bijan.", "Celupkan kepingan ayam yang dah diperap ke dalam adunan.", "Goreng dalam minyak betul-betul panas, masukkan satu-satu; bila hampir masak, masukkan hirisan cili hijau, daun limau purut dan bawang putih — semua ini boleh dimakan dan menambah aroma.", "Goreng sehingga golden crispy. Toskan dan hidang."]', '["halal", "chicken", "fried", "crispy", "thai", "sesame", "malaysian", "ramadan"]', TRUE, TRUE, 'chicken quantity not stated; green chilli/kaffir lime leaf/garlic fried at the end not quantified', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7610273174038662418', 'Honey BBQ Chicken Tenders with White Sauce', 'Honey BBQ Chicken Tenders dengan Sos Putih', 'Crispy chicken tenders tossed in a smoky honey BBQ glaze, served with a cool yogurt-mayo white sauce — an upgrade on the classic hot chicken tenders.', 'Chicken tenders yang crispy digaulkan dalam saduran madu BBQ yang smoky, dihidang dengan sos putih yogurt-mayo yang segar.', 'Western', 'Easy', 15, 20, 4, '["chicken fillet", "chicken fried flour", "water", "cooking oil", "paprika powder", "cayenne pepper", "chilli flakes", "garlic powder", "brown sugar", "BBQ sauce", "honey", "plain yogurt", "mayonnaise", "lemon", "black pepper", "garlic", "salt"]', '[{"name": "chicken fillet", "name_ms": "isi ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "chicken fried flour", "name_ms": "tepung goreng ayam", "quantity": 1, "unit": "cup", "note": "brand Bestari; split into wet and dry portions"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "to wet the batter"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying; a portion used for spice bloom"}, {"name": "paprika powder", "name_ms": "serbuk paprika", "quantity": 1, "unit": "tbsp", "note": "for spice mix"}, {"name": "cayenne pepper", "name_ms": "cayenne pepper", "quantity": 1, "unit": "tbsp", "note": "for spice mix"}, {"name": "chilli flakes", "name_ms": "cili flakes", "quantity": 0.5, "unit": "tbsp", "note": "for spice mix"}, {"name": "garlic powder", "name_ms": "garlic powder", "quantity": 0.5, "unit": "tbsp", "note": "for spice mix"}, {"name": "brown sugar", "name_ms": "brown sugar", "quantity": 1, "unit": "tbsp", "note": "for spice mix"}, {"name": "BBQ sauce", "name_ms": "sos barbeque", "quantity": null, "unit": null, "note": "to taste; near plum sauce in supermarket"}, {"name": "honey", "name_ms": "madu", "quantity": 0.5, "unit": "tbsp", "note": "added to glaze"}, {"name": "plain yogurt", "name_ms": "yogurt original", "quantity": 3, "unit": "tbsp", "note": "for white sauce"}, {"name": "mayonnaise", "name_ms": "mayonis", "quantity": 3, "unit": "tbsp", "note": "for white sauce"}, {"name": "lemon", "name_ms": "lemon", "quantity": null, "unit": null, "note": "squeeze to taste; for white sauce"}, {"name": "black pepper", "name_ms": "black pepper", "quantity": null, "unit": null, "note": "to taste; for white sauce"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 2, "unit": "clove", "note": "crushed; for white sauce"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "pinch; for white sauce"}]', '["Moisten 1 cup chicken fried flour with a little water to make a wet dip; keep the rest dry.", "Dip chicken tenders in the wet flour, then coat in the dry flour.", "Deep-fry in hot oil until golden and crispy; drain.", "Mix 1 tbsp paprika powder, 1 tbsp cayenne pepper, 0.5 tbsp chilli flakes, 0.5 tbsp garlic powder and 1 tbsp brown sugar in a bowl.", "Ladle hot frying oil over the spice mix to bloom the spices.", "Add BBQ sauce (to taste) and 0.5 tbsp honey; stir until a thick, glossy glaze forms.", "Toss the fried chicken in the glaze until evenly coated.", "[White sauce] Mix 3 tbsp plain yogurt, 3 tbsp mayonnaise, a squeeze of lemon, black pepper, 2 crushed garlic cloves and a pinch of salt."]', '["Basahkan 1 cawan tepung goreng ayam dengan sedikit air untuk jadi celupan basah; baki kekalkan kering.", "Celup chicken tenders dalam tepung basah, kemudian salut dengan tepung kering.", "Goreng dalam minyak panas sehingga golden crispy; toskan.", "Gaul 1 sudu serbuk paprika, 1 sudu cayenne pepper, setengah sudu cili flakes, setengah sudu garlic powder dan 1 sudu brown sugar dalam mangkuk.", "Tuang minyak goreng yang betul-betul panas ke atas campuran rempah untuk bloom.", "Masukkan sos barbeque (secukupnya) dan setengah sudu madu; gaul sehingga jadi saduran pekat berkilat.", "Toss ayam goreng dalam saduran sehingga rata.", "[Sos putih] Gaul 3 sudu yogurt original, 3 sudu mayo, perahan lemon, black pepper, 2 ulas bawang putih yang dihancurkan dan sedikit garam."]', '["halal", "chicken", "fried", "bbq", "honey", "western", "ramadan"]', TRUE, TRUE, 'chicken quantity not stated; BBQ sauce quantity from bottle not stated; white sauce same as V2 (Hot Chicken Tenders)', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7610678008025976071', 'Fried Doughnut Balls (Cekodok Donat)', 'Bebola Donat Goreng (Cekodok Donat)', 'Soft, fluffy yeast-risen doughnut balls rolled in sugar — crispy outside, airy inside.', 'Bebola donat yang lembut dan gebu menggunakan yis — garing kat luar, gebu kat dalam, digulingkan dalam gula.', 'Malaysian', 'Easy', 80, 15, 20, '["all-purpose flour", "sugar", "salt", "yeast", "water", "egg", "butter", "cooking oil", "icing sugar"]', '[{"name": "all-purpose flour", "name_ms": "tepung gandum", "quantity": 2.5, "unit": "cup", "note": ""}, {"name": "sugar", "name_ms": "gula", "quantity": 3, "unit": "tbsp", "note": "in dough"}, {"name": "salt", "name_ms": "garam", "quantity": 0.5, "unit": "tsp", "note": ""}, {"name": "yeast", "name_ms": "yis", "quantity": 1, "unit": null, "note": "1 packet instant yeast"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "3/4 cup warm (not hot)"}, {"name": "egg", "name_ms": "telur", "quantity": 1, "unit": null, "note": ""}, {"name": "butter", "name_ms": "butter", "quantity": 2, "unit": "tbsp", "note": "melted"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for deep frying"}, {"name": "icing sugar", "name_ms": "gula serbuk", "quantity": null, "unit": null, "note": "for dusting; amount to preference"}]', '["Mix 2.5 cup all-purpose flour, 3 tbsp sugar, 0.5 tsp salt and 1 packet yeast.", "Add 0.75 cup warm water, 1 egg and 2 tbsp melted butter; mix until a rough dough forms.", "Knead until smooth and non-sticky. Cover and rest 1 hour until doubled.", "Knock back; roll into small balls (golf-ball size).", "Deep-fry in hot oil over high heat for 2–3 minutes, turning, until evenly golden.", "Drain; while still warm, toss or dust with icing sugar."]', '["Gaul 2 cawan setengah tepung gandum, 3 sudu gula, setengah sudu kecil garam dan 1 paket yis.", "Masukkan 3/4 cawan air suam, 1 biji telur dan 2 sudu butter cair; gaul sehingga jadi adunan kasar.", "Uli sehingga licin dan tidak melekat. Tutup dan rehat 1 jam sehingga dua kali ganda.", "Hembus keluar udara; gulung menjadi bola-bola kecil (saiz bola golf).", "Goreng dalam minyak panas atas api besar 2-3 minit, pusingkan, sehingga golden rata.", "Toskan; selagi panas, guling atau tabur dengan gula serbuk."]', '["halal", "dessert", "doughnut", "fried", "sweet", "ramadan", "easy"]', TRUE, FALSE, 'fry 2-3 min at high heat; makes approx 20-25 balls; prep includes 1 hr rest', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7610699789948308744', 'Spanish Mackerel in Vinegar Gravy (Tenggiri Masak Cuka)', 'Tenggiri Masak Cuka', 'Fried Spanish mackerel steaks simmered in a piquant, slightly sweet sour gravy made with dried tamarind, vinegar and aromatic spices.', 'Steak ikan tenggiri yang digoreng kemudian direneh dalam kuah masam-manis dengan asam keping, cuka dan rempah yang aromatik.', 'Malaysian', 'Easy', 20, 20, 3, '["Spanish mackerel", "turmeric powder", "salt", "cooking oil", "shallot", "garlic", "ginger", "bird''s eye chilli", "dried tamarind slices", "vinegar", "water", "palm sugar", "seasoning powder", "curry leaf"]', '[{"name": "Spanish mackerel", "name_ms": "ikan tenggiri", "quantity": null, "unit": null, "note": "fish steaks; quantity not stated"}, {"name": "turmeric powder", "name_ms": "serbuk kunyit", "quantity": 1, "unit": "tsp", "note": "for rubbing fish"}, {"name": "salt", "name_ms": "garam", "quantity": 0.5, "unit": "tsp", "note": "for rubbing fish; more to taste"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for frying fish and sautéing"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": null, "unit": null, "note": "sliced"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 4, "unit": "clove", "note": ""}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob"}, {"name": "bird''s eye chilli", "name_ms": "cili padi", "quantity": 3, "unit": null, "note": ""}, {"name": "dried tamarind slices", "name_ms": "asam keping", "quantity": null, "unit": null, "note": "3-4 pieces; quantity vague"}, {"name": "vinegar", "name_ms": "cuka", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "water", "name_ms": "air", "quantity": 1, "unit": "cup", "note": ""}, {"name": "palm sugar", "name_ms": "gula melaka", "quantity": 1, "unit": null, "note": "1 block"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "curry leaf", "name_ms": "daun kari", "quantity": null, "unit": null, "note": "a few stalks"}]', '["Rub fish steaks with 1 tsp turmeric powder and 0.5 tsp salt; fry until cooked through and golden. Set aside.", "In the same pan, sauté sliced onion, 4 garlic cloves and a knob of ginger until soft.", "Add 3 bird''s eye chillies; sauté briefly.", "Add 3–4 dried tamarind slices, 1 tbsp vinegar, 1 cup water, 1 palm sugar block and seasoning powder.", "Simmer until the gravy is slightly thickened.", "Add the fried fish back; add curry leaf; simmer for a further 5 minutes.", "Adjust sourness and sweetness; serve hot with rice."]', '["Lumur kepingan ikan tenggiri dengan 1 sudu kecil serbuk kunyit dan setengah sudu kecil garam; goreng sehingga masak dan golden. Ketepikan.", "Dalam kuali yang sama, tumis hirisan bawang, 4 ulas bawang putih dan seketul halia sehingga layu.", "Masukkan 3 biji cili padi; tumis sebentar.", "Masukkan 3-4 keping asam keping, 1 sudu cuka, 1 cawan air, 1 ketul gula Melaka dan serbuk perasa.", "Reneh sehingga kuah sedikit pekat.", "Masukkan balik ikan yang sudah digoreng; masukkan daun kari; reneh 5 minit lagi.", "Laraskan rasa masam dan manis; hidang panas bersama nasi."]', '["halal", "fish", "sour", "malaysian", "ramadan", "easy"]', TRUE, TRUE, 'fish quantity not stated; dried tamarind slices quantity vague (''3-4 keping''); cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7610718382635191570', 'Fried Ice Cream (Aiskrim Goreng)', 'Aiskrim Goreng Pro Max', 'A viral two-ingredient fried ice cream: a scoop of ice cream sandwiched between two slices of bread, frozen solid, then deep-fried for just 10 seconds in very hot oil.', 'Aiskrim goreng dua bahan yang viral: skop aiskrim dikepit di antara dua keping roti, dibekukan hingga keras, kemudian digoreng hanya 10 saat dalam minyak betul-betul panas.', 'Fusion', 'Easy', 150, 1, 4, '["ice cream", "white bread", "cooking oil"]', '[{"name": "ice cream", "name_ms": "aiskrim", "quantity": null, "unit": null, "note": "any flavour; video shows chocolate, vanilla, taro and corn"}, {"name": "white bread", "name_ms": "roti putih", "quantity": null, "unit": null, "note": "2 slices per portion"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for deep frying; must be very hot"}]', '["Scoop ice cream onto a slice of bread; place another slice on top.", "Press and seal all four edges tightly; trim with a cup rim for a neat seal if desired.", "Freeze for 2–3 hours until rock-solid (tap to check — it should sound firm).", "Heat oil until very hot. Deep-fry the frozen ice cream sandwich for exactly 10 seconds; remove immediately.", "Serve and eat right away before the ice cream melts."]', '["Skopkan aiskrim atas sekeping roti; letak sekeping roti lagi di atas.", "Tekan dan lekatkan semua empat tepi rapat-rapat; boleh tekan dengan tepi cawan untuk bentuk yang kemas.", "Bekukan selama 2-3 jam sehingga keras seperti batu (ketuk untuk semak — bunyi mesti keras).", "Panaskan minyak betul-betul panas. Goreng sandwich aiskrim beku tepat 10 saat; angkat dengan segera.", "Hidang dan makan terus sebelum aiskrim cair."]', '["halal", "dessert", "fried", "ice cream", "western", "easy", "ramadan"]', TRUE, FALSE, 'ice cream flavour flexible; fry time approx. 10 seconds in very hot oil; freeze time 2-3 hours; prep time includes freezing', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7611431627465526536', 'Padang-Style Chicken Curry (Gulai Ayam Padang)', 'Gulai Ayam Padang', 'A rich, aromatic Padang-style chicken curry with whole spices, candlenuts, and blended coconut milk gravy — a classic nasi Padang restaurant dish.', 'Gulai ayam Padang yang kaya rempah, buah keras dan kuah santan yang diblend untuk tekstur berkilat — hidangan klasik restoran nasi Padang.', 'Indonesian', 'Medium', 20, 35, 4, '["garlic", "ginger", "galangal", "fresh turmeric", "coriander seeds", "cumin", "candlenut", "water", "star anise", "cardamom", "lemongrass", "bay leaf", "turmeric leaf", "onion", "blended chilli", "chicken", "coconut milk", "kaffir lime leaf", "sugar", "salt", "seasoning powder", "cooking oil"]', '[{"name": "garlic", "name_ms": "bawang putih", "quantity": 5, "unit": "clove", "note": "blended"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; blended"}, {"name": "galangal", "name_ms": "lengkuas", "quantity": null, "unit": null, "note": "1 knob; blended"}, {"name": "fresh turmeric", "name_ms": "kunyit hidup", "quantity": null, "unit": null, "note": "1 knob; blended"}, {"name": "coriander seeds", "name_ms": "biji ketumbar", "quantity": 1, "unit": "tsp", "note": "blended"}, {"name": "cumin", "name_ms": "jintan putih", "quantity": 1, "unit": "tsp", "note": "blended"}, {"name": "candlenut", "name_ms": "buah keras", "quantity": 2, "unit": null, "note": "blended"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "for blending and cooking"}, {"name": "star anise", "name_ms": "bunga lawang", "quantity": 2, "unit": null, "note": "whole; for sautéing"}, {"name": "cardamom", "name_ms": "buah pelaga", "quantity": 2, "unit": null, "note": "whole; for sautéing"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 2, "unit": null, "note": "bruised; for sautéing"}, {"name": "bay leaf", "name_ms": "daun salam", "quantity": 2, "unit": null, "note": ""}, {"name": "turmeric leaf", "name_ms": "daun kunyit", "quantity": 1, "unit": null, "note": ""}, {"name": "onion", "name_ms": "bawang holland", "quantity": null, "unit": null, "note": "sliced; for sautéing"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 1.5, "unit": "tbsp", "note": "1–2 tbsp for colour; 1 more added later if needed"}, {"name": "chicken", "name_ms": "ayam", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "coconut milk", "name_ms": "santan", "quantity": 1, "unit": null, "note": "1 small box"}, {"name": "kaffir lime leaf", "name_ms": "daun limau purut", "quantity": 3, "unit": null, "note": "3–4 leaves"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "to taste"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "for sautéing"}]', '["Blend 5 garlic cloves, a knob each of ginger and galangal, a knob of fresh turmeric, 1 tsp coriander seeds, 1 tsp cumin and 2 candlenuts with water.", "Heat oil; sauté the blend with 2 star anise and 2 cardamom pods until fragrant.", "Add 2 bruised lemongrass stalks, 2 bay leaves, 1 turmeric leaf and sliced sweet onion; continue sautéing.", "Add 1–2 tbsp blended chilli (for colour); cook until oil separates.", "Add chicken; stir to coat. Add 1 small box coconut milk, water, 3–4 kaffir lime leaves; season with sugar, salt and seasoning powder.", "When the chicken is cooked, optionally remove all the whole spices and lemongrass, then blend the gravy for a smooth, glossy finish.", "Pour the blended gravy back over the chicken and serve."]', '["Blend 5 ulas bawang putih, seketul masing-masing halia dan lengkuas, seketul kunyit hidup, 1 sudu kecil biji ketumbar, 1 sudu kecil jintan putih dan 2 biji buah keras dengan air.", "Panaskan minyak; tumis blend bersama 2 biji bunga lawang dan 2 biji buah pelaga sehingga wangi.", "Masukkan 2 batang serai diketuk, 2 helai daun salam, 1 helai daun kunyit dan hirisan bawang besar; sambung tumis.", "Masukkan 1-2 sudu cili kisar (untuk warna); masak sehingga pecah minyak.", "Masukkan ayam; gaul sebati. Masukkan 1 kotak kecil santan, air, 3-4 helai daun limau purut; tambah gula, garam dan serbuk perasa.", "Bila ayam dah masak, boleh angkat semua rempah kasar dan serai, kemudian blend kuah untuk tekstur berkilat licin.", "Tuang balik kuah yang dah diblend ke atas ayam dan hidang."]', '["halal", "chicken", "curry", "padang", "indonesian", "coconut milk", "malaysian", "raya"]', TRUE, TRUE, 'chicken quantity not stated; blended gravy step is optional but described; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7611453477151116552', 'Overnight Chia Pudding', 'Chia Pudding Overnight', 'A healthy, creamy overnight chia pudding with only 3 ingredients — perfect for a quick and nutritious sahur.', 'Puding chia semalaman yang sihat dan berkrim dengan hanya 3 bahan — sesuai untuk sahur yang mudah dan berkhasiat.', 'Western', 'Easy', 5, 0, 2, '["chia seeds", "sweetened condensed milk", "fresh milk", "mango", "honey"]', '[{"name": "chia seeds", "name_ms": "chia seed", "quantity": 4, "unit": "tbsp", "note": ""}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "fresh milk", "name_ms": "fresh milk", "quantity": 1, "unit": "cup", "note": ""}, {"name": "mango", "name_ms": "mangga", "quantity": null, "unit": null, "note": "optional topping; diced"}, {"name": "honey", "name_ms": "madu", "quantity": null, "unit": null, "note": "optional topping; drizzle to taste"}]', '["Combine 4 tbsp chia seeds, 2 tbsp sweetened condensed milk and 1 cup fresh milk in a jar; stir well.", "Refrigerate overnight (or at least 4 hours) until the chia seeds absorb the liquid and puff up into a pudding.", "Before serving, stir; top with diced mango and a drizzle of honey."]', '["Gaul 4 sudu chia seed, 2 sudu krimer manis dan 1 cawan susu segar dalam balang; kacau rata.", "Simpan dalam peti sejuk semalaman (atau sekurang-kurangnya 4 jam) sehingga chia seed menyerap cecair dan kembang jadi puding.", "Sebelum dihidang, kacau; hiaskan dengan kiub mangga dan titisan madu."]', '["halal", "healthy", "chia", "no-cook", "sahur", "breakfast", "easy", "ramadan"]', TRUE, FALSE, 'refrigerate overnight for best results; mango is optional topping; prep includes overnight soak', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7612554976145001735', 'Red Snapper Soup (Sup Ikan Merah)', 'Sup Ikan Merah', 'A clear, aromatic red snapper soup fragrant with ginger, lemongrass, tomato and fresh herbs — light and nourishing.', 'Sup ikan merah jernih yang wangi dengan halia, serai, tomato dan herba segar — ringan dan berkhasiat.', 'Malaysian', 'Easy', 15, 25, 4, '["red snapper", "water", "ginger", "lemongrass", "tomato", "shallot", "salt", "seasoning powder", "sugar", "spring onion", "coriander leaves", "lime"]', '[{"name": "red snapper", "name_ms": "ikan merah", "quantity": null, "unit": null, "note": "whole or pieces; quantity not stated"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "enough to cover fish"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; bruised"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 2, "unit": null, "note": "bruised"}, {"name": "tomato", "name_ms": "tomato", "quantity": 2, "unit": null, "note": "halved"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 1, "unit": null, "note": "sliced"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "a little"}, {"name": "spring onion", "name_ms": "daun bawang", "quantity": null, "unit": null, "note": "for garnish"}, {"name": "coriander leaves", "name_ms": "daun ketumbar", "quantity": null, "unit": null, "note": "for garnish"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "wedges for serving"}]', '["Clean and score the fish; rub with a little salt.", "Bring water to a boil with bruised ginger, 2 lemongrass stalks and sliced onion.", "Add the fish; simmer until cooked through (10–15 minutes).", "Add tomatoes (halved); season with salt, seasoning powder and a little sugar.", "Garnish with spring onion and coriander; serve with a wedge of lime."]', '["Bersihkan dan calit ikan; lumur dengan sedikit garam.", "Didihkan air bersama halia diketuk, 2 batang serai dan bawang merah yang dihiris.", "Masukkan ikan; reneh sehingga masak (10-15 minit).", "Masukkan tomato (dibelah); tambah garam, serbuk perasa dan sedikit gula.", "Hiaskan dengan daun bawang dan daun ketumbar; hidang dengan hirisan limau."]', '["halal", "fish", "soup", "clear soup", "malaysian", "ramadan", "easy"]', TRUE, TRUE, 'fish quantity not stated; tomato quantity for garnish flexible; cook/prep times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7612905423682784520', 'Instant Chocolate Mousse (3 Ingredients)', 'Coklat Mousse Instant (3 Bahan)', 'A quick, rich chocolate mousse made by dissolving chocolate chips in warm cream, then folding in whipped cream — ready in minutes.', 'Coklat mousse yang cepat dan kaya rasa, dibuat dengan mencairkan coklat chip dalam krim panas kemudian dilipat bersama whipping cream yang dikocok.', 'Western', 'Easy', 15, 5, 4, '["cooking cream", "chocolate chips", "whipping cream"]', '[{"name": "cooking cream", "name_ms": "cooking cream", "quantity": 0.5, "unit": "cup", "note": ""}, {"name": "chocolate chips", "name_ms": "coklat chip", "quantity": 2, "unit": "cup", "note": "semi-sweet or dark recommended"}, {"name": "whipping cream", "name_ms": "whipping cream", "quantity": 1, "unit": null, "note": "1 small box; must be cold before whipping"}]', '["Gently heat 0.5 cup cooking cream until just warm (do not boil); remove from heat.", "Stir in 2 cup chocolate chips; the warm cream will melt the chocolate. (Alternatively use a double boiler.)", "Let the chocolate mixture cool to room temperature.", "Whisk 1 small cold box of whipping cream until stiff peaks form.", "Gently fold the cooled chocolate into the whipped cream until combined.", "Pour into cups or moulds; refrigerate for a few hours before serving."]', '["Panaskan perlahan-lahan setengah cawan cooking cream sehingga panas sahaja (jangan mendidih); padamkan api.", "Masukkan 2 cawan coklat chip; krim yang panas akan cairkan coklat. (Boleh juga guna cara double boil.)", "Biarkan adunan coklat sejuk ke suhu bilik.", "Kocok 1 kotak kecil whipping cream yang sejuk sehingga kaku.", "Lipat perlahan adunan coklat ke dalam whipping cream sehingga sebati.", "Tuang ke dalam cawan atau bekas; simpan dalam peti sejuk beberapa jam sebelum dihidang."]', '["halal", "dessert", "chocolate", "mousse", "western", "easy", "ramadan"]', TRUE, FALSE, 'video contains extensive motivational speech (majority of runtime); actual recipe is short but complete with all quantities stated; prep_time and servings estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7614001409758924050', 'Local-Style Spaghetti Bolognese', 'Spaghetti Bolognese Versi Lokal', 'A Malaysian-style bolognese using frozen beef mince, tinned tomato puree, fresh tomato and Italian herbs — a budget-friendly, crowd-pleasing pasta dish.', 'Spaghetti bolognese gaya Malaysia menggunakan daging beku, tomato puree tin, tomato segar dan rempah Itali — mudah, murah dan sedap untuk open house.', 'Fusion', 'Easy', 15, 30, 4, '["frozen beef", "celery", "onion", "carrot", "garlic", "tomato puree", "tomato", "water", "oregano", "chilli flakes", "salt", "black pepper", "bay leaf", "chicken stock cube", "spaghetti", "parmesan cheese"]', '[{"name": "frozen beef", "name_ms": "daging beku", "quantity": 400, "unit": "g", "note": "any brand; no oil needed"}, {"name": "celery", "name_ms": "salari", "quantity": 1, "unit": null, "note": "1 stalk salari"}, {"name": "onion", "name_ms": "bawang holland", "quantity": 1, "unit": null, "note": ""}, {"name": "carrot", "name_ms": "carrot", "quantity": 1, "unit": null, "note": ""}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 4, "unit": "clove", "note": ""}, {"name": "tomato puree", "name_ms": "tomato puree", "quantity": 1, "unit": "can", "note": ""}, {"name": "tomato", "name_ms": "tomato", "quantity": 2, "unit": null, "note": "fresh; blended"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": ""}, {"name": "oregano", "name_ms": "oregano", "quantity": 0.5, "unit": "tbsp", "note": ""}, {"name": "chilli flakes", "name_ms": "cili flakes", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "black pepper", "name_ms": "black pepper", "quantity": null, "unit": null, "note": "to taste"}, {"name": "bay leaf", "name_ms": "daun salam", "quantity": 1, "unit": null, "note": ""}, {"name": "chicken stock cube", "name_ms": "kiub pati ayam", "quantity": 1, "unit": null, "note": "or beef stock cube"}, {"name": "spaghetti", "name_ms": "spagheti", "quantity": null, "unit": null, "note": "cook per package instructions"}, {"name": "parmesan cheese", "name_ms": "parmesan cheese", "quantity": null, "unit": null, "note": "for topping; quantity not stated"}]', '["Fry 400 g frozen beef (no oil needed) until its fat renders and it browns; set aside.", "Chop 1 celery stalk, 1 sweet onion, 1 carrot and 4 garlic cloves; sauté until golden.", "Add 1 can tomato puree and 2 blended fresh tomatoes (blended with a little water).", "Return the beef; add 0.5 tbsp oregano, 1 tbsp chilli flakes, salt, black pepper, 1 bay leaf and 1 chicken (or beef) stock cube.", "Add water; cover and simmer for 15 minutes (longer = more flavour). Add more water if it dries out.", "Cook spaghetti per package instructions; drain.", "Serve sauce over spaghetti; top with parmesan cheese."]', '["Goreng 400g daging beku (tanpa minyak) sehingga lemak cair dan daging garing; ketepikan.", "Chop 1 batang salari, 1 bawang Holland, 1 carrot dan 4 ulas bawang putih; tumis sehingga keemasan.", "Masukkan 1 tin tomato puree dan 2 biji tomato segar yang dah diblend (blend dengan sedikit air).", "Masukkan balik daging; tambah setengah sudu oregano, 1 sudu cili flakes, garam, black pepper, 1 helai daun salam dan 1 kiub pati ayam (atau lembu).", "Masukkan air; tutup dan reneh selama 15 minit (lebih lama lebih sedap). Tambah air kalau kering.", "Rebus spaghetti ikut arahan pakej; toskan.", "Hidang kuah di atas spaghetti; tabur parmesan cheese."]', '["halal", "pasta", "beef", "bolognese", "western", "open house", "raya"]', TRUE, TRUE, 'parmesan cheese topping quantity not stated; recipe self-described as non-authentic local version using frozen beef and tinned tomato puree', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7614748072328875282', 'Macaroni Goreng (Stir-Fried Macaroni)', 'Makaroni Goreng', 'Hearty stir-fried macaroni with minced beef and a rich, savoury sauce — a crowd-pleasing open-house dish for Raya.', 'Makaroni goreng berkuah pekat dengan daging cincang dan sos yang sedap — hidangan sempurna untuk open house raya.', 'Malaysian', 'Easy', 15, 25, 6, '["frozen beef", "shallot", "garlic", "blended chilli", "water", "oyster sauce", "tomato sauce", "chilli sauce", "sweet soy sauce", "chicken stock cube", "macaroni", "salt", "seasoning powder", "bell pepper", "Chinese celery", "crispy fried shallots", "lime"]', '[{"name": "frozen beef", "name_ms": "daging beku", "quantity": 400, "unit": "g", "note": "any brand; no oil needed"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 3, "unit": null, "note": "chopped"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 6, "unit": "clove", "note": "chopped"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 1.5, "unit": "tbsp", "note": "1–2 tbsp; adjust to taste"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "to deglaze wok"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "tomato sauce", "name_ms": "sos tomato", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": 3, "unit": "tbsp", "note": ""}, {"name": "chicken stock cube", "name_ms": "kiub pati ayam", "quantity": 1, "unit": null, "note": ""}, {"name": "macaroni", "name_ms": "makaroni", "quantity": 400, "unit": "g", "note": "1 packet; boiled in salted water"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "bell pepper", "name_ms": "lada benggala", "quantity": null, "unit": null, "note": "any colour; sliced"}, {"name": "Chinese celery", "name_ms": "daun sup", "quantity": null, "unit": null, "note": "garnish"}, {"name": "crispy fried shallots", "name_ms": "bawang goreng", "quantity": null, "unit": null, "note": "garnish; use generously"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "squeeze over before serving"}]', '["Fry 400 g frozen beef (no oil needed) until its fat renders and it browns slightly; drain and set aside.", "In the same wok, sauté 3 onions and 6 garlic cloves (chopped); add 1–2 tbsp blended chilli.", "Deglaze the browned bits on the wok with a little water — this is all flavour.", "Return the beef; add 2 tbsp oyster sauce, 2 tbsp tomato sauce, 2 tbsp chilli sauce, 3 tbsp sweet soy sauce and 1 chicken stock cube. Mix well.", "Boil 400 g macaroni in salted water until al dente; drain.", "Add the macaroni to the beef mixture and toss until the sauce coats evenly.", "Stir in sliced bell pepper (any colour); adjust seasoning with salt and seasoning powder.", "Serve topped with Chinese celery, crispy fried shallots and a squeeze of lime."]', '["Goreng 400g daging beku (tanpa minyak) sehingga lemaknya cair dan daging garing sikit; ketepikan.", "Dalam kuali yang sama, tumis 3 biji bawang merah dan 6 ulas bawang putih (dihacam); masukkan 1-2 sudu cili kisar.", "Deglaze kerak daging di tepi kuali dengan sedikit air — itu semua flavour.", "Masukkan balik daging; tambah 2 sudu sos tiram, 2 sudu sos tomato, 2 sudu sos cili, 3 sudu kicap manis dan 1 kiub pati ayam. Kacau sebati.", "Rebus 400g makaroni dalam air bergaram sehingga masak; toskan.", "Masukkan makaroni ke dalam tumisan daging dan gaul sehingga sos melekat rata.", "Masukkan hirisan lada benggala (warna apa pun); laraskan perasa dengan garam dan serbuk perasa.", "Hidang ditaburi daun sup, bawang goreng dan perahan limau nipis."]', '["halal", "pasta", "beef", "stir-fry", "malaysian", "raya", "open house"]', TRUE, FALSE, 'cook/prep times and servings estimated; recipe designed for 1 family', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7615766087359089927', 'Salted Caramel Cornflakes', 'Salted Caramel Cornflakes', 'Crunchy cornflakes coated in a homemade salted caramel and baked until crisp — a modern Raya biscuit that is very easy to make.', 'Cornflakes yang disalut dengan karamel bergaram buatan sendiri dan dibakar sehingga rangup — kuih raya moden yang sangat mudah dibuat.', 'Western', 'Easy', 10, 20, 20, '["sugar", "whipping cream", "butter", "vanilla essence", "salt", "cornflakes"]', '[{"name": "sugar", "name_ms": "gula", "quantity": 2, "unit": "cup", "note": "for caramel"}, {"name": "whipping cream", "name_ms": "whipping cream", "quantity": 1, "unit": "cup", "note": "must be at room temperature"}, {"name": "butter", "name_ms": "butter", "quantity": 200, "unit": "g", "note": "1 block unsalted butter, approx. 200g"}, {"name": "vanilla essence", "name_ms": "esen vanila", "quantity": 1, "unit": "tsp", "note": "stated as ''1 penutup (bottle cap)''; approx. 1 tsp"}, {"name": "salt", "name_ms": "garam", "quantity": 1.5, "unit": "tsp", "note": "reduce if using salted butter"}, {"name": "cornflakes", "name_ms": "cornflakes", "quantity": 500, "unit": "g", "note": "1 packet; thin variety used"}]', '["Place 2 cup sugar in a dry pan over medium heat; swirl (do not stir with a spoon) until it melts and turns golden caramel.", "Once the centre begins to melt, use a spatula to stir gently.", "Remove from heat and carefully pour in 1 cup whipping cream (room temperature); stir quickly — it will bubble vigorously.", "Add 1 block (approx. 200 g) unsalted butter and stir until melted.", "Add approx. 1 tsp vanilla essence and 1.5 tsp salt; stir to combine.", "Add a 500 g packet of cornflakes and fold until evenly coated.", "Spread on a baking tray and bake at 170°C for 5 minutes to crisp further.", "Leave to cool completely before storing — they must be fully cool to become crunchy."]', '["Masukkan 2 cawan gula dalam kuali kering atas api sederhana; pusingkan (jangan kacau dengan sudu) sehingga gula cair dan jadi karamel keemasan.", "Bila tengah dah mula cair, boleh kacau dengan senduk.", "Angkat dari api dan tuangkan 1 cawan whipping cream (suhu bilik) dengan berhati-hati; kacau cepat-cepat — ia akan berbuih kuat.", "Masukkan 1 blok (lebih kurang 200g) unsalted butter dan kacau sehingga cair.", "Tambah lebih kurang 1 sudu kecil esen vanila dan 1 sudu kecil setengah garam; gaul sebati.", "Masukkan sepaket 500g cornflakes dan gaul sehingga rata.", "Ratakan atas tray dan bakar pada suhu 170°C selama 5 minit untuk lebih rangup.", "Biarkan sejuk sepenuhnya sebelum disimpan — mesti betul-betul sejuk baru jadi rangup."]', '["halal", "dessert", "snack", "caramel", "cornflakes", "raya", "no-bake"]', TRUE, TRUE, 'vanilla measured by ''penutup'' (bottle cap) — quantity converted to approx. 1 tsp; butter stated as ''1 blok, lebih kurang 200g''', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7616247154121641237', 'Creamy Corn Pudding with Custard Sauce', 'Puding Jagung Creamy dengan Kuah Kastard', 'A creamy, jiggly corn pudding made with creamed corn, coconut milk and condensed milk, topped with a smooth vanilla custard sauce — perfect served cold for open house.', 'Puding jagung yang creamy dan gebu diperbuat daripada jagung krim, santan dan susu pekat, dihidang sejuk dengan kuah kastard yang lembut.', 'Malaysian', 'Easy', 15, 20, 10, '["corn", "evaporated milk", "coconut milk", "sweetened condensed milk", "cornstarch", "water", "salt", "custard powder", "sugar"]', '[{"name": "corn", "name_ms": "jagung", "quantity": 1, "unit": "can", "note": "creamed corn (tin); for pudding"}, {"name": "evaporated milk", "name_ms": "susu cair", "quantity": 1.5, "unit": "can", "note": "1 can for pudding; 1 can for custard sauce (use 0.5 can water with the remaining 0.5 can)"}, {"name": "coconut milk", "name_ms": "santan", "quantity": 1, "unit": null, "note": "1 small box; for pudding"}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": null, "unit": null, "note": "2/3 cup for pudding; 3 tbsp for custard sauce"}, {"name": "cornstarch", "name_ms": "tepung jagung", "quantity": null, "unit": null, "note": "1/3 cup dissolved in 1 cup water; for pudding"}, {"name": "water", "name_ms": "air", "quantity": 1, "unit": "cup", "note": "for dissolving cornstarch"}, {"name": "salt", "name_ms": "garam", "quantity": 0.5, "unit": "tsp", "note": "for pudding"}, {"name": "custard powder", "name_ms": "tepung kastard", "quantity": null, "unit": null, "note": "1 cup for pudding; 1.5 tbsp for custard sauce; dissolve before adding"}, {"name": "sugar", "name_ms": "gula", "quantity": null, "unit": null, "note": "red syrup (sirap ros) — a little for colour in pudding; quantity not stated"}]', '["In a pot, combine 1 can creamed corn, 1 can evaporated milk, 1 small box coconut milk, 2/3 cup sweetened condensed milk, 1/3 cup cornstarch dissolved in 1 cup water, 0.5 tsp salt and a dash of red syrup (for colour).", "Stir in 1 cup custard powder (dissolved beforehand) — add it last or it will clump.", "Cook over medium heat, stirring constantly, until the mixture is thick and glossy.", "Pour quickly into moulds or a tray; tap gently to remove air bubbles. Optionally top with whole corn kernels for texture. Let cool before refrigerating.", "[Custard sauce] Combine 1 can evaporated milk, 0.5 can water, 3 tbsp sweetened condensed milk and 1.5 tbsp custard powder in a pot.", "Cook over medium heat, stirring, until the mixture just boils and thickens slightly. Pour over the set pudding."]', '["Dalam periuk, campurkan 1 tin jagung krim, 1 tin susu cair, 1 kotak kecil santan, 2/3 cawan susu pekat, 1/3 cawan tepung jagung yang dilarutkan dalam 1 cawan air, setengah sudu kecil garam dan sikit sirap untuk warna.", "Masukkan 1 cawan tepung kastard (yang dah dilarutkan lebih awal) — masuk last sekali atau dia akan berketul.", "Masak atas api sederhana sambil dikacau sehingga adunan pekat dan berkilat.", "Tuang cepat-cepat ke dalam bekas atau loyang; hentak untuk buang buih. Boleh letak biji jagung di atas untuk tekstur. Biarkan sejuk sebelum dimasukkan ke dalam peti sejuk.", "[Kuah kastard] Campurkan 1 tin susu cair, setengah tin air, 3 sudu susu pekat dan 1 sudu setengah tepung kastard dalam periuk.", "Masak atas api sederhana sambil dikacau sehingga mendidih dan pekat sikit. Tuang di atas puding yang dah set."]', '["halal", "dessert", "pudding", "corn", "custard", "raya", "open house", "no-bake"]', TRUE, TRUE, 'red syrup (sirap) added ''sikit'' for colour — quantity not stated; servings and times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7616991468783291666', 'Stir-Fried Vermicelli (Bihun Goreng)', 'Bihun Goreng', 'A family-sized plate of stir-fried rice vermicelli with fish cake, fish ball and vegetables in a savory dark sauce — a classic Raya dish.', 'Bihun goreng untuk satu keluarga dengan fishcake, fishball, sawi dan sos pekat yang sedap — hidangan klasik yang sesuai untuk hari raya.', 'Malaysian', 'Easy', 15, 15, 4, '["rice vermicelli", "shallot", "garlic", "dried anchovies", "blended chilli", "fish cake", "fish ball", "water", "oyster sauce", "sweet soy sauce", "tomato sauce", "chilli sauce", "shrimp paste (petis)", "fish sauce", "salt", "seasoning powder", "mustard greens", "bell pepper"]', '[{"name": "rice vermicelli", "name_ms": "bihun", "quantity": 1, "unit": null, "note": "1 packet; soaked in tap water"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 2, "unit": null, "note": "blended"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 3, "unit": "clove", "note": "blended"}, {"name": "dried anchovies", "name_ms": "ikan bilis", "quantity": null, "unit": null, "note": "a small handful; blended"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": null, "unit": null, "note": "to taste"}, {"name": "fish cake", "name_ms": "fishcake", "quantity": null, "unit": null, "note": ""}, {"name": "fish ball", "name_ms": "fishball", "quantity": null, "unit": null, "note": ""}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "a little"}, {"name": "oyster sauce", "name_ms": "sos tiram", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": 4, "unit": "tbsp", "note": ""}, {"name": "tomato sauce", "name_ms": "sos tomato", "quantity": 2, "unit": "tbsp", "note": ""}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": 4, "unit": "tbsp", "note": ""}, {"name": "shrimp paste (petis)", "name_ms": "petis udang", "quantity": 0.5, "unit": "tbsp", "note": "optional"}, {"name": "fish sauce", "name_ms": "sos ikan", "quantity": null, "unit": null, "note": "generous amount; to taste"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "mustard greens", "name_ms": "sawi", "quantity": null, "unit": null, "note": ""}, {"name": "bell pepper", "name_ms": "lada benggala", "quantity": null, "unit": null, "note": "sliced"}]', '["Soak 1 packet of rice vermicelli in tap water (no need for hot water); drain and set aside.", "Blend 2 onions, 3 garlic cloves and a small handful of dried anchovies together; add blended chilli.", "Sauté the blend; add fish cake and fish ball, then a little water.", "Add 2 tbsp oyster sauce, 4 tbsp sweet soy sauce, 2 tbsp tomato sauce and 4 tbsp chilli sauce. Optionally add 0.5 tbsp shrimp paste (petis).", "Add the soaked vermicelli; it will initially look dry — just keep stirring.", "Add fish sauce generously; season with salt and seasoning powder.", "Once the vermicelli has absorbed the sauce and softened, add sliced mustard greens and bell pepper; toss until wilted.", "Serve topped with Chinese celery and crispy fried shallots if available."]', '["Rendam 1 paket bihun dalam air paip (tidak perlu air suam); toskan dan ketepikan.", "Blend 2 biji bawang merah, 3 ulas bawang putih dan segenggam kecil ikan bilis; masukkan cili kisar.", "Tumis blend; masukkan fishcake dan fishball, kemudian sedikit air.", "Masukkan 2 sudu sos tiram, 4 sudu kicap manis, 2 sudu sos tomato dan 4 sudu sos cili. Boleh tambah setengah sudu petis udang (pilihan).", "Masukkan bihun yang dah direndam; ia akan nampak kering pada mulanya — kacau sahaja.", "Masukkan banyak sos ikan; laraskan dengan garam dan serbuk perasa.", "Bila bihun sudah lembut dan menyerap sos, masukkan sawi dan hirisan lada besar; gaul sehingga layu.", "Hidang ditaburi daun sup dan bawang goreng jika ada."]', '["halal", "noodles", "vermicelli", "stir-fry", "seafood", "malaysian", "raya"]', TRUE, FALSE, 'petis udang is optional; vegetable quantities flexible; times estimated for 1 packet', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7617718005950172434', 'Peanut Sauce for Satay (Kuah Kacang)', 'Kuah Kacang', 'A rich, glossy peanut sauce for satay or nasi impit — made from scratch by dry-roasting half a kilo of peanuts then cooking them down in a spiced blended paste.', 'Kuah kacang yang berkilat dan kaya rasa untuk satay atau nasi impit — dibuat dari awal dengan memanggang setengah kilo kacang tanah dan memasaknya dalam pes rempah.', 'Malaysian', 'Medium', 30, 40, 10, '["peanuts", "cooking oil", "shallot", "lemongrass", "galangal", "ginger", "candlenut", "garlic", "dried shrimp", "blended chilli", "water", "palm sugar", "salt", "seasoning powder", "tamarind paste"]', '[{"name": "peanuts", "name_ms": "kacang tanah", "quantity": 500, "unit": "g", "note": "dry-roasted; 70% blended fine, 30% coarse"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "generous amount"}, {"name": "shallot", "name_ms": "bawang merah", "quantity": 4, "unit": null, "note": "blended"}, {"name": "lemongrass", "name_ms": "serai", "quantity": 3, "unit": null, "note": "stalks; blended"}, {"name": "galangal", "name_ms": "lengkuas", "quantity": null, "unit": null, "note": "1 knob; blended"}, {"name": "ginger", "name_ms": "halia", "quantity": null, "unit": null, "note": "1 knob; blended"}, {"name": "candlenut", "name_ms": "buah keras", "quantity": 3, "unit": null, "note": "blended"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": 6, "unit": "clove", "note": "blended"}, {"name": "dried shrimp", "name_ms": "udang kering", "quantity": 1, "unit": "tbsp", "note": "blended with aromatics"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 5, "unit": "tbsp", "note": "not spicy type"}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "added gradually during cooking"}, {"name": "palm sugar", "name_ms": "gula melaka", "quantity": 3, "unit": null, "note": "3 small blocks"}, {"name": "salt", "name_ms": "garam", "quantity": null, "unit": null, "note": "to taste"}, {"name": "seasoning powder", "name_ms": "serbuk perasa", "quantity": null, "unit": null, "note": "to taste"}, {"name": "tamarind paste", "name_ms": "pes asam jawa", "quantity": 0.5, "unit": "tbsp", "note": ""}]', '["Dry-roast 500 g peanuts in a pan over low heat for 15–20 minutes until the skins loosen; cool and rub off skins.", "Blend 70% of the peanuts finely; blend the remaining 30% coarsely.", "Blend 4 onions, 3 lemongrass stalks, a knob each of galangal and ginger, 3 candlenuts, 6 garlic cloves and 1 tbsp dried shrimp together.", "Heat a generous amount of oil; fry the blend with 5 tbsp blended chilli until the oil separates.", "Add the blended peanuts; the mixture will look dry — add water and continue cooking.", "Alternate between adding water and cooking down (repeat several times over about 20 minutes) until the peanuts are soft.", "Season with 3 small blocks palm sugar, salt, seasoning powder and 0.5 tbsp tamarind paste.", "Continue cooking until the sauce is glossy and the oil floats on top. Serve with ketupat or satay."]', '["Panggang 500g kacang tanah dalam kuali tanpa minyak atas api perlahan selama 15-20 minit sehingga kulit mudah tertanggal; sejukkan dan gosok kulit keluar.", "Blend 70% kacang secara halus; blend baki 30% secara kasar.", "Blend 4 biji bawang merah, 3 batang serai, seketul masing-masing lengkuas dan halia, 3 biji buah keras, 6 ulas bawang putih dan 1 sudu udang kering bersama.", "Panaskan banyak minyak masak; goreng blend bersama 5 sudu cili kisar sehingga pecah minyak.", "Masukkan kacang yang dah di-blend; akan nampak kering — masukkan air dan sambung masak.", "Bergilir-gilir antara tambah air dan masak sehingga kering (ulang beberapa kali lebih kurang 20 minit) sehingga kacang lembut.", "Tambah 3 ketul kecil gula Melaka, garam, serbuk perasa dan setengah sudu pes asam jawa.", "Sambung masak sehingga kuah berkilat dan minyak timbul di atas. Hidang dengan ketupat atau satay."]', '["halal", "peanut sauce", "satay", "raya", "malaysian", "side dish"]', TRUE, FALSE, 'cook time for peanuts approx. 15-20 min; total cook time for sauce approx. 20 min; servings estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7618118573059312916', 'Dragon Fruit Jelly Pudding (Puding Buah Naga)', 'Puding Buah Naga', 'A beautiful layered jelly pudding made with fresh dragon fruit blended into the jelly — sets to a gorgeous pink colour and needs no artificial colouring.', 'Puding jeli berlapis yang cantik dibuat dengan buah naga segar yang diblend masuk ke dalam jeli — warna merah jambu yang cantik semula jadi tanpa pewarna.', 'Malaysian', 'Easy', 30, 15, 8, '["jelly powder", "sugar", "water", "dragon fruit", "evaporated milk", "sweetened condensed milk"]', '[{"name": "jelly powder", "name_ms": "serbuk jeli", "quantity": 1, "unit": null, "note": "1 packet (10 g); any brand"}, {"name": "sugar", "name_ms": "gula", "quantity": 5, "unit": "tbsp", "note": "adjust to taste"}, {"name": "water", "name_ms": "air", "quantity": 3.5, "unit": "cup", "note": "2 cup for blending dragon fruit; 1.5 cup additional"}, {"name": "dragon fruit", "name_ms": "buah naga", "quantity": 1, "unit": null, "note": "red for pink colour; white also works"}, {"name": "evaporated milk", "name_ms": "susu cair", "quantity": 0.5, "unit": "cup", "note": "for sauce"}, {"name": "sweetened condensed milk", "name_ms": "krimer manis", "quantity": 0.5, "unit": "cup", "note": "for sauce"}]', '["Blend the flesh of 1 dragon fruit (red or white) with 2 cup water until smooth.", "Strain through a sieve; combine with 1.5 cup additional water.", "Add 1 packet (10 g) jelly powder and 5 tbsp sugar; stir well.", "Bring to a boil over medium heat, stirring continuously, until the jelly powder dissolves completely.", "Remove from heat; pour into moulds or a large tray.", "Allow to set at room temperature for about 2 hours, then refrigerate.", "For the sauce: mix 0.5 cup evaporated milk and 0.5 cup sweetened condensed milk; serve drizzled over sliced jelly."]', '["Blend isi 1 biji buah naga (merah atau putih) dengan 2 cawan air sehingga lumat.", "Tapis melalui penapis; campurkan dengan 1 cawan setengah air tambahan.", "Masukkan 1 paket (10g) serbuk jeli dan 5 sudu gula; kacau rata.", "Masak atas api sederhana sambil kacau berterusan sehingga serbuk jeli larut sepenuhnya.", "Angkat dari api; tuang ke dalam acuan atau tray besar.", "Biarkan set di suhu bilik kira-kira 2 jam, kemudian simpan dalam peti sejuk.", "Untuk sos: gaul setengah cawan susu cair dan setengah cawan susu pekat manis; hidang dititis di atas jeli yang dipotong."]', '["halal", "dessert", "jelly", "dragon fruit", "no-bake", "malaysian", "raya"]', TRUE, FALSE, 'sets at room temp in ~2 hrs then refrigerate; dragon fruit can be red or white; quantities all stated; prep/cook times estimated', 2, NULL, 'khairulaming_tiktok');
INSERT INTO recipes_ka (video_id, title, title_ms, description, description_ms, cuisine, difficulty, prep_time, cook_time, servings, ingredients, ingredients_detailed, steps, steps_ms, tags, is_recipe, needs_review, review_notes, contributor_id, image_url, source)
VALUES ('7628524921236294920', 'Spicy Instant Noodle Soup (Mee Goreng Basah)', 'Mee Goreng Basah Pedas dengan Sambal', 'A quick spicy wet instant noodle dish with fish balls, fish cake, seafood and egg in a bold, savoury sambal broth.', 'Mi segera goreng basah yang cepat dan pedas dengan fishball, fishcake, seafood dan telur dalam kuah sambal yang kaya rasa.', 'Malaysian', 'Easy', 5, 10, 2, '["shallot", "garlic", "cooking oil", "fish ball", "fish cake", "water", "blended chilli", "sweet soy sauce", "tomato sauce", "chilli sauce", "instant noodles", "prawn", "egg", "lime"]', '[{"name": "shallot", "name_ms": "bawang merah", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "garlic", "name_ms": "bawang putih", "quantity": null, "unit": null, "note": "quantity not stated"}, {"name": "cooking oil", "name_ms": "minyak goreng", "quantity": null, "unit": null, "note": "a little"}, {"name": "fish ball", "name_ms": "fishball", "quantity": null, "unit": null, "note": ""}, {"name": "fish cake", "name_ms": "fishcake", "quantity": null, "unit": null, "note": ""}, {"name": "water", "name_ms": "air", "quantity": null, "unit": null, "note": "enough to create broth"}, {"name": "blended chilli", "name_ms": "cili kisar", "quantity": 1, "unit": "tbsp", "note": "or use a branded sambal; video uses ''Sambal Nyet'' 1 tbsp"}, {"name": "sweet soy sauce", "name_ms": "kicap manis", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "tomato sauce", "name_ms": "sos tomato", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "chilli sauce", "name_ms": "sos cili", "quantity": 1, "unit": "tbsp", "note": ""}, {"name": "instant noodles", "name_ms": "mi segera", "quantity": 2, "unit": null, "note": "2 packets; use only 1 seasoning packet"}, {"name": "prawn", "name_ms": "udang", "quantity": null, "unit": null, "note": "optional; to taste"}, {"name": "egg", "name_ms": "telur", "quantity": 1, "unit": null, "note": "stirred in during cooking; 1 more fried as topping"}, {"name": "lime", "name_ms": "limau nipis", "quantity": null, "unit": null, "note": "squeeze over to serve"}]', '["Sauté onion and garlic in a little oil until fragrant.", "Add fish balls and fish cake; fry briefly until lightly browned.", "Add water and bring to a simmer.", "Add 1 tbsp blended chilli (or sambal), 1 tbsp sweet soy sauce, 1 tbsp tomato sauce and 1 tbsp chilli sauce.", "Add 2 packets of instant noodles with only 1 seasoning packet (2 packets is too salty); let the noodles soften.", "Add prawn, egg and a little vegetable; stir until the noodles have absorbed the sauce.", "Serve with a fried egg on top and a squeeze of lime."]', '["Tumis bawang merah dan bawang putih dalam sedikit minyak sehingga wangi.", "Masukkan fishball dan fishcake; goreng sebentar sehingga kekuningan.", "Masukkan air dan biarkan mendidih.", "Masukkan 1 sudu cili kisar (atau sambal), 1 sudu kicap manis, 1 sudu sos tomato dan 1 sudu sos cili.", "Masukkan 2 paket mi segera dengan hanya 1 paket perencah (2 paket terlalu masin); biarkan mi kembang.", "Masukkan udang, telur dan sedikit sayur; kacau sehingga mi menyerap kuah.", "Hidang dengan telur mata goyang di atas dan perahan limau."]', '["halal", "noodles", "spicy", "quick", "seafood", "malaysian", "ramadan"]', TRUE, TRUE, 'video contains product promotion for ''Sambal Nyet'' brand — no generic substitute shown; onion and garlic quantities vague (''tumis bawang merah dengan bawang putih''); seafood quantity optional/not stated', 2, NULL, 'khairulaming_tiktok');

COMMIT;
